/* ===== okane-app.js ===== */
// おかねの物差し：共通の道具・ヒーロー・はたらく時間・ランキング・クイズ・ことば辞典
(() => {
  const D = window;
  const $ = (id) => document.getElementById(id);
  const yen = (n) => Math.round(n).toLocaleString("ja-JP");
  const pos = (el, d) => { const v = parseFloat(el.value); return isFinite(v) && v > 0 ? v : d; };
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const store = {
    get(k, d) { try { const v = localStorage.getItem("okane:" + k); return v === null ? d : JSON.parse(v); } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem("okane:" + k, JSON.stringify(v)); } catch (e) {} },
  };
  function hm(hours) { const t = Math.round(hours * 60); return { h: Math.floor(t / 60), m: t % 60 }; }
  function hmText(hours) {
    if (hours < 1 / 60) return "1分未満";
    const { h, m } = hm(hours);
    if (h === 0) return `約${m}分`;
    return m ? `約${h}時間${m}分` : `約${h}時間`;
  }
  function hmHTML(hours) {
    if (hours < 1 / 60) return `1<span class="u">分未満</span>`;
    const { h, m } = hm(hours);
    return (h ? `${h.toLocaleString()}<span class="u">時間</span>` : "") + (m || !h ? `${m}<span class="u">分</span>` : "");
  }
  const pct = (a, b) => (b / a - 1) * 100;
  const sgn = (v, d = 0) => (v >= 0 ? "+" : "−") + Math.abs(v).toFixed(d) + "%";
  const cpiAt = (cat, y) => D.CPI[cat][y - D.CPI_FIRST_YEAR];
  const AVG10 = pct(cpiAt("総合", 2015), cpiAt("総合", 2025));
  const ONIGIRI = D.ITEMS.find((i) => i.id === "onigiri").p25;
  // 共有する道具
  D.OK = { $, yen, pos, esc, store, hmText, hmHTML, pct, sgn, cpiAt, AVG10 };

  // ===== ふりがな =====
  const furi = $("furiToggle");
  if (store.get("furigana", false)) { document.body.classList.add("furigana"); furi.setAttribute("aria-pressed", "true"); }
  furi.addEventListener("click", () => {
    const on = !document.body.classList.contains("furigana");
    document.body.classList.toggle("furigana", on); furi.setAttribute("aria-pressed", String(on)); store.set("furigana", on);
  });

  // ===== あなたの物差し（時給・おこづかい） =====
  const wageIn = $("wageIn"), allowIn = $("allowIn"), prefSel = $("prefSel");
  D.PREFS.forEach((p, i) => { const o = document.createElement("option"); o.value = i; o.textContent = `${p.p}${p.p === "北海道" ? "" : p.p === "東京" ? "都" : p.p === "大阪" || p.p === "京都" ? "府" : "県"}（${yen(D.PREF_WAGE[i])}円）`; prefSel.appendChild(o); });
  D.OK.prefName = (i) => { const p = D.PREFS[i].p; return p === "北海道" ? p : p + (p === "東京" ? "都" : p === "大阪" || p === "京都" ? "府" : "県"); };
  wageIn.value = store.get("wage", 1177); allowIn.value = store.get("allow", 3000); prefSel.value = store.get("pref", "");
  const listeners = [];
  D.OK.onUnit = (fn) => listeners.push(fn);
  D.OK.wage = () => pos(wageIn, 1177);
  D.OK.allow = () => pos(allowIn, 3000);
  D.OK.pref = () => prefSel.value === "" ? -1 : +prefSel.value;
  D.OK.setPref = (i) => { prefSel.value = String(i); wageIn.value = D.PREF_WAGE[i]; unitChanged(); };
  function unitChanged() {
    const w = D.OK.wage(), pi = D.OK.pref();
    if (pi >= 0 && D.PREF_WAGE[pi] !== w) prefSel.value = "";
    [...$("wageSeg").children].forEach((b) => b.setAttribute("aria-pressed", String(+b.dataset.wage === w)));
    $("pillWage").textContent = (D.OK.pref() >= 0 ? D.OK.prefName(D.OK.pref()) + " " : "") + yen(w) + "円";
    store.set("wage", w); store.set("allow", D.OK.allow()); store.set("pref", prefSel.value);
    listeners.forEach((fn) => fn());
  }
  $("wageSeg").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; wageIn.value = b.dataset.wage; prefSel.value = ""; unitChanged(); });
  prefSel.addEventListener("change", () => { if (prefSel.value !== "") wageIn.value = D.PREF_WAGE[+prefSel.value]; else wageIn.value = 1177; unitChanged(); });
  wageIn.addEventListener("input", unitChanged);
  allowIn.addEventListener("input", unitChanged);
  setTimeout(() => { $("pillWage").textContent = (D.OK.pref() >= 0 ? D.OK.prefName(D.OK.pref()) + " " : "") + yen(D.OK.wage()) + "円"; }, 0);

  // ===== ヒーロー：3つの物差し =====
  const heroPrice = $("heroPrice");
  const HERO = ["rice", "onigiri", "karaoke", "randoseru"].map((id) => D.ITEMS.find((i) => i.id === id));
  HERO.push({ name: "ゲーム機（例）", p25: 49980 });
  HERO.forEach((it) => {
    const b = document.createElement("button");
    b.type = "button"; b.className = "chip"; b.dataset.price = it.p25;
    b.innerHTML = `${esc(it.name)}<span class="num">${yen(it.p25)}円</span>`;
    b.addEventListener("click", () => { heroPrice.value = it.p25; renderHero(); });
    $("heroChips").appendChild(b);
  });
  heroPrice.addEventListener("input", renderHero);
  function renderHero() {
    const p = pos(heroPrice, 1), w = D.OK.wage(), a = D.OK.allow();
    [...$("heroChips").children].forEach((c) => c.setAttribute("aria-pressed", String(+c.dataset.price === p)));
    const h = p / w;
    $("cvHours").innerHTML = hmHTML(h).replace(/class="u"/g, "");
    $("cvHoursS").textContent = h >= 8 ? `1日8時間で ${(h / 8).toFixed(1)}日ぶん（時給${yen(w)}円）` : `時給${yen(w)}円ではたらくと`;
    const months = p / a;
    $("cvAllow").innerHTML = months < 1 ? `${Math.round(months * 100)}<small>%</small>` : `${months < 10 ? months.toFixed(1) : Math.round(months).toLocaleString()}<small>か月ぶん</small>`;
    $("cvAllowS").textContent = months < 1 ? `月${yen(a)}円のおこづかいのうち` : `月${yen(a)}円をぜんぶためると`;
    const oni = p / ONIGIRI;
    $("cvOni").innerHTML = oni < 1 ? `${(oni).toFixed(1)}<small>個ぶん</small>` : `${Math.round(oni).toLocaleString()}<small>個</small>`;
    drawHeroRuler(h);
  }
  function drawHeroRuler(h) {
    // 1日（8時間）を1本の物差しに。こえたら何日目かを数える
    const L = 16, R = 944, W = R - L, Y = 16, H = 30;
    const days = Math.floor(h / 8), rest = h - days * 8;
    const x = (hr) => L + (hr / 8) * W;
    let s = `<rect x="${L}" y="${Y}" width="${W}" height="${H}" rx="6" fill="var(--soft)"/>`;
    const fill = days >= 1 ? W : Math.max(3, x(rest) - L);
    s += `<rect x="${L}" y="${Y}" width="${fill}" height="${H}" rx="6" fill="var(--ruler)"/>`;
    for (let m = 0; m <= 8 * 4; m++) {
      const hr = m / 4, big = m % 4 === 0;
      s += `<line x1="${x(hr)}" x2="${x(hr)}" y1="${Y}" y2="${Y + (big ? 14 : 7)}" stroke="var(--ink)" stroke-width="${big ? 1.5 : 1}" opacity="${big ? .9 : .45}"/>`;
      if (big) s += `<text x="${x(hr)}" y="${Y + H + 20}" text-anchor="middle" font-family="DM Mono, monospace" font-size="13" fill="var(--muted)">${hr === 0 ? "0" : hr + "時間"}</text>`;
    }
    if (days >= 1) {
      s += `<text x="${R - 10}" y="${Y + 21}" text-anchor="end" font-size="15" font-weight="700" fill="var(--ruler-ink)" font-family="Zen Kaku Gothic New, sans-serif">1日8時間 × ${days.toLocaleString()}日${rest > 0.05 ? " ＋ " + hmText(rest).replace("約", "") : ""}</text>`;
    } else {
      const xm = x(rest);
      s += `<line x1="${xm}" x2="${xm}" y1="${Y - 6}" y2="${Y + H + 4}" stroke="var(--ink)" stroke-width="2.5"/><path d="M${xm - 6} ${Y - 12} h12 l-6 8 z" fill="var(--ink)"/>`;
    }
    $("heroRuler").innerHTML = s;
  }
  D.OK.onUnit(renderHero);
  renderHero();

  // ===== 01 はたらく時間 =====
  let group = store.get("group", "food"), cur = store.get("item", "onigiri");
  if (!D.ITEMS.some((i) => i.id === cur)) cur = "onigiri";
  const groupChips = $("groupChips");
  Object.entries(D.GROUPS).forEach(([k, v]) => {
    const b = document.createElement("button");
    b.type = "button"; b.className = "chip"; b.dataset.g = k; b.textContent = v;
    b.addEventListener("click", () => { group = k; store.set("group", k); renderGrid(); });
    groupChips.appendChild(b);
  });
  function renderGrid() {
    [...groupChips.children].forEach((c) => c.setAttribute("aria-pressed", String(c.dataset.g === group)));
    const grid = $("itemGrid"); grid.innerHTML = "";
    D.ITEMS.filter((i) => i.g === group).forEach((it) => {
      const b = document.createElement("button");
      b.type = "button"; b.className = "item"; b.setAttribute("aria-pressed", String(it.id === cur));
      b.innerHTML = `<span class="nm">${esc(it.name)}</span><span class="ut">${esc(it.unit)}</span><span class="pr">${yen(it.p25)}<small>円</small></span>`;
      b.addEventListener("click", () => { cur = it.id; store.set("item", cur); renderGrid(); renderHours(); });
      grid.appendChild(b);
    });
  }
  function renderHours() {
    const it = D.ITEMS.find((i) => i.id === cur), w = D.OK.wage();
    const h = it.p25 / w;
    $("hLabel").textContent = `${it.name}（${it.unit}・${yen(it.p25)}円）を買うには`;
    $("hValue").innerHTML = hmHTML(h);
    $("hSub").innerHTML = `${yen(it.p25)}円 ÷ 時給${yen(w)}円。` + (h >= 8 ? `1日8時間はたらくと <b>${(h / 8).toFixed(1)}日</b> ぶんです。` : `1日8時間のうち <b>${Math.max(1, Math.round(h / 8 * 100))}%</b> です。`);
    const viz = $("hViz"), leg = $("hLegend");
    if (h > 320) {
      const months = h / 160; let s = '<div class="months">';
      for (let i = 0; i < Math.min(Math.ceil(months), 36); i++) { const f = Math.min(1, months - i); s += `<div class="month${f >= 1 ? " full" : ""}"><i style="height:${f * 100}%"></i><span>${i + 1}か月</span></div>`; }
      viz.innerHTML = s + "</div>";
      leg.innerHTML = `<span><span class="sw" style="background:var(--accent)"></span>1マス＝1か月（1日8時間×20日）</span>`;
    } else {
      let s = '<div class="hours-viz">';
      const cells = Math.max(1, Math.ceil(h));
      for (let d = 0; d < Math.ceil(cells / 8); d++) {
        s += '<div class="day">';
        for (let k = 0; k < 8; k++) { const f = Math.max(0, Math.min(1, h - (d * 8 + k))); s += `<span class="cell">${f > 0 ? `<i style="width:${Math.max(f * 100, 8)}%"></i>` : ""}</span>`; }
        s += "</div>";
      }
      viz.innerHTML = s + "</div>";
      leg.innerHTML = `<span><span class="sw" style="background:var(--accent)"></span>1マス＝1時間</span><span>8マスで1日</span>`;
    }
    const h15 = it.p15 / D.MINWAGE[2015], h25 = it.p25 / D.MINWAGE[2025];
    $("tn15").textContent = hmText(h15); $("tn15s").textContent = `${yen(it.p15)}円 ÷ 時給798円`;
    $("tn25").textContent = hmText(h25); $("tn25s").textContent = `${yen(it.p25)}円 ÷ 時給1,121円`;
    const d = (h25 / h15 - 1) * 100;
    let t;
    if (Math.abs(d) < 3) t = `値段は ${sgn(pct(it.p15, it.p25))} 上がりましたが、時給も上がったので、<b>買うのにかかる時間はほぼ同じ</b>です。`;
    else if (d < 0) t = `値段は ${sgn(pct(it.p15, it.p25))} 上がりましたが、時給はそれ以上に上がったので、<b>買うのにかかる時間は${Math.round(-d)}%短く</b>なりました。10年前より買いやすくなっています。`;
    else t = `値段の上がり方（${sgn(pct(it.p15, it.p25))}）が時給の上がり方（+40%）より大きいので、<b>買うのにかかる時間は${Math.round(d)}%長く</b>なりました。10年前より買いにくくなっています。`;
    if (it.n) t += ` <span class="note-flag">条件変更</span> ${esc(it.spec)}`;
    $("tnText").innerHTML = t;
    drawTrend(it);
  }
  // 4時点の値段（棒＋折れ線）。棒の高さは値段、上に数字
  function drawTrend(it) {
    const tr = D.TREND[it.id] || [null, null];
    const vals = [tr[0], it.p15, tr[1], it.p25];
    const W = 560, H = 170, M = { l: 12, r: 12, t: 26, b: 26 };
    const max = Math.max(...vals.filter((v) => v != null)) * 1.12;
    const bw = 64, gap = (W - M.l - M.r - bw * 4) / 3;
    const X = (i) => M.l + i * (bw + gap), Y = (v) => M.t + (1 - v / max) * (H - M.t - M.b);
    let s = `<line x1="${M.l}" x2="${W - M.r}" y1="${H - M.b}" y2="${H - M.b}" stroke="var(--line)"/>`;
    vals.forEach((v, i) => {
      const y = D.TREND_YEARS[i], x = X(i);
      s += `<text x="${x + bw / 2}" y="${H - 8}" text-anchor="middle">${y}年</text>`;
      if (v == null) { s += `<text x="${x + bw / 2}" y="${H - M.b - 10}" text-anchor="middle">比べられない</text>`; return; }
      const last = i === 3;
      s += `<rect x="${x}" y="${Y(v)}" width="${bw}" height="${H - M.b - Y(v)}" rx="4" fill="${last ? "var(--ruler)" : "var(--soft)"}"/>`;
      s += `<text class="p" x="${x + bw / 2}" y="${Y(v) - 8}" text-anchor="middle">${yen(v)}円</text>`;
    });
    $("trendChart").innerHTML = s;
    let note = `東京23区の年平均。`;
    if (vals[2] != null) { const c = (it.p25 / vals[2] - 1) * 100; note += `2020年から2025年の5年間で ${sgn(c)}。`; }
    if (vals[0] != null) { const c = (vals[1] / vals[0] - 1) * 100; note += `2010年から2015年は ${sgn(c)} でした。`; }
    if (it.id === "rice" || it.id === "onigiri") note += "ここ数年で急に上がったことがわかります。";
    if (vals.includes(null)) note += "「比べられない」年は、調べる品物の条件が大きくちがうため出していません。";
    $("trendNote").textContent = note;
  }
  // さがす機能から、品物をえらんで開けるように
  D.OK.selectItem = (id) => { const it = D.ITEMS.find((i) => i.id === id); if (!it) return; cur = id; group = it.g; store.set("item", cur); store.set("group", group); renderGrid(); renderHours(); };
  // さがす機能から、品物をえらんで開けるように
  D.OK.selectItem = (id) => { const it = D.ITEMS.find((i) => i.id === id); if (!it) return; cur = id; group = it.g; store.set("item", cur); store.set("group", group); renderGrid(); renderHours(); };
  D.OK.onUnit(renderHours);
  renderGrid(); renderHours();

  // ===== 02 値上がりランキング =====
  $("avgPct").textContent = sgn(AVG10, 1);
  let rGroup = "all", rSel = "rice";
  const rankChips = $("rankChips");
  [["all", "ぜんぶ"], ...Object.entries(D.GROUPS)].forEach(([k, v]) => {
    const b = document.createElement("button");
    b.type = "button"; b.className = "chip"; b.dataset.g = k; b.textContent = v;
    b.addEventListener("click", () => { rGroup = k; renderRank(); });
    rankChips.appendChild(b);
  });
  function renderRank() {
    [...rankChips.children].forEach((c) => c.setAttribute("aria-pressed", String(c.dataset.g === rGroup)));
    const rows = D.ITEMS.filter((i) => rGroup === "all" || i.g === rGroup).map((i) => ({ ...i, c: pct(i.p15, i.p25) })).sort((a, b) => b.c - a.c);
    const all = D.ITEMS.map((i) => pct(i.p15, i.p25));
    const lo = Math.min(-10, ...all), hi = Math.max(...all) + 4;
    const X = (v) => ((v - lo) / (hi - lo)) * 100;
    const list = $("rankList"); list.innerHTML = "";
    rows.forEach((r) => {
      const b = document.createElement("button");
      b.type = "button"; b.className = "rank-row"; b.setAttribute("aria-pressed", String(r.id === rSel));
      const left = Math.min(X(0), X(r.c)), width = Math.abs(X(r.c) - X(0));
      const color = r.c > AVG10 ? "var(--hot)" : "var(--cool)";
      b.innerHTML = `<span class="nm">${esc(r.name)}</span>
        <span class="track"><span class="zero" style="left:${X(0)}%"></span><span class="bar${r.c < 0 ? " neg" : ""}" style="left:${left}%;width:${Math.max(width, .6)}%;background:${color}"></span><span class="axis" style="left:${X(AVG10)}%"></span></span>
        <span class="pc">${sgn(r.c)}</span>`;
      b.addEventListener("click", () => { rSel = r.id; renderRank(); });
      list.appendChild(b);
    });
    const s = D.ITEMS.find((i) => i.id === rSel) || rows[0];
    const c = pct(s.p15, s.p25);
    $("rankDetail").innerHTML = `<div><b>${esc(s.name)}</b>（${esc(s.unit)}）${s.n ? '<span class="note-flag">条件変更</span>' : ""}</div>
      <div>2015年 <b class="num">${yen(s.p15)}円</b> → 2025年 <b class="num">${yen(s.p25)}円</b>（${sgn(c)}）。物価全体の平均（${sgn(AVG10, 1)}）の <b class="num">${(c / AVG10).toFixed(1)}倍</b> の上がり方です。</div>
      <div class="hint">調べ方：${esc(s.spec)}</div>`;
  }
  renderRank();

  // ===== 08 ことば辞典 =====
  const realMW = (D.MINWAGE[2025] / D.MINWAGE[2015]) / (cpiAt("総合", 2025) / cpiAt("総合", 2015));
  const WORDS = [
    { w: "物価", r: "ぶっか", p: "いろいろな物やサービスの値段を、まとめて見たもの。ひとつの品物の値段ではなく「全体として」高いか安いかを表します。", ex: `2015年から2025年までに、物価は${sgn(AVG10, 1)}上がりました。` },
    { w: "消費者物価指数", r: "しょうひしゃぶっかしすう", p: "国（総務省統計局）が毎月発表する、物価の「ものさし」。ある年を100として、ほかの年がいくつかで表します。英語の頭文字でCPIとも言います。", ex: "今は2025年＝100。1990年は80.1なので、そのころは今より約2割安かったことになります。" },
    { w: "インフレ・デフレ", r: "", p: "物価が上がり続けることをインフレ、下がり続けることをデフレと言います。日本は1990年代の終わりから、物価がほとんど上がらない時代が長く続きました。", ex: "2022年ごろから、日本はふたたびインフレの時代に入りました。" },
    { w: "名目と実質", r: "めいもく・じっしつ", p: "金額そのものが名目、物価の動きを差し引いて「どれだけ買えるか」で見たものが実質です。", ex: `最低賃金は10年で名目+40%、実質では約${sgn((realMW - 1) * 100)}でした。` },
    { w: "最低賃金", r: "さいていちんぎん", p: "法律で決められた、時給の最低ライン。これより低い時給で人をやとってはいけません。都道府県ごとに毎年決まります。", ex: "2026年度の全国平均は1,177円。いちばん高い都道府県は1,280円、低い県は1,085円です。" },
    { w: "額面と手取り", r: "がくめん・てどり", p: "会社が決めた給料が額面、税金や保険料が引かれたあと口座に入るのが手取りです。", ex: "大学卒の初任給の平均262,300円なら、1年目の手取りはおよそ22万円です。" },
    { w: "社会保険", r: "しゃかいほけん", p: "病気、老後、失業など、だれにでも起こりうることに、みんなでお金を出しあって備えるしくみ。健康保険・年金・雇用保険などがあります。", ex: "保険料の多くは、はたらく人と会社が半分ずつ払います。" },
    { w: "基準年", r: "きじゅんねん", p: "物価指数で「100」にする年のこと。5年ごとに新しくなります。2026年から、2025年が基準年になりました。", ex: "基準年が変わっても、年と年の比べ方（何％上がったか）はほとんど変わりません。" },
    { w: "家計調査", r: "かけいちょうさ", p: "国（総務省統計局）が、全国の約9千世帯に家計簿をつけてもらい、収入や支出を調べる統計。毎月発表されます。", ex: "2人以上で暮らす家族が2025年に使ったお金は、平均で月314,001円でした。" },
    { w: "エンゲル係数", r: "えんげるけいすう", p: "使ったお金のうち、食べ物に使った割合。食べ物は節約しにくいので、物価が上がると高くなりやすい数字です。", ex: "2025年は28.6%。1981年以来、44年ぶりの高さでした。" },
    { w: "相関係数", r: "そうかんけいすう", p: "2つの数字が一緒に増えたり減ったりする関係の強さを、−1から1で表したもの。1に近いほど「片方が大きいともう片方も大きい」関係です。", ex: "おにぎりの値段と最低賃金の相関係数は0.18。ほとんど関係がありません。" },
    { w: "72の法則", r: "ななじゅうにのほうそく", p: "72を「1年あたりの上がり方（%）」でわると、2倍になるまでのおおよその年数がわかる計算のコツ。", ex: "物価が毎年3%上がると、72÷3＝24年で値段は約2倍になります。" },
    { w: "需要と供給", r: "じゅよう・きょうきゅう", p: "物を「ほしい」と思う人の多さが需要、「売りたい」と思って出てくる量が供給。需要が多く供給が少ないと値段は上がり、その逆だと下がります。", ex: "第4章の「値段は、どうやって決まる？」で、つまみを動かしてためせます。" },
    { w: "円高・円安", r: "えんだか・えんやす", p: "外国のお金とくらべた、円の値打ち。1ドルを買うのに必要な円が少なくなるのが円高、多くなるのが円安です。円安になると、外国から買う物が値上がりしやすくなります。", ex: `1ドルは、2011年の平均で${D.FX[2011 - D.FX_FIRST_YEAR].toFixed(0)}円、${D.FX_LATEST.label}は${D.FX_LATEST.value.toFixed(0)}円。今のほうが円安です。` },
    { w: "軽減税率", r: "けいげんぜいりつ", p: "消費税（ふつうは10%）のうち、食べ物や飲み物（お酒と外食をのぞく）と新聞だけを8%にしているしくみ。2019年10月から始まりました。", ex: "同じハンバーガーでも、お店で食べると10%、持ち帰ると8%です。" },
    { w: "経済の循環", r: "けいざいのじゅんかん", p: "家計（家）・会社・国のあいだを、お金が回っていくこと。買い物の代金は会社へ、給料は家計へ、税金は国へ行き、国は学校や道路や年金に使います。", ex: "第13章の「お金のめぐり図」で、1,100円の旅を追いかけられます。" },
    { w: "国債", r: "こくさい", p: "国が、足りないお金を借りるときに出す「借金の証明書」。あとで利息をつけて返します。", ex: `国の予算${D.BIG.find((b) => b.id === "budget").short}のうち、借金の返済と利息（国債費）が${D.BIG.find((b) => b.id === "debtpay").short}あります。` },
  ];
  $("wordGrid").innerHTML = WORDS.map((x) => `<div class="word"><span class="w">${x.w}</span>${x.r ? `<span class="r">${x.r}</span>` : ""}<p>${x.p}</p><span class="ex">${x.ex}</span></div>`).join("");

  // ===== 章ナビのハイライト =====
  const links = [...document.querySelectorAll("#chapters a")];
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver((ents) => ents.forEach((e) => {
      if (e.isIntersecting) links.forEach((a) => a.classList.toggle("on", a.getAttribute("href") === "#" + e.target.id));
    }), { rootMargin: "-40% 0px -55% 0px" });
    document.querySelectorAll("section.ch").forEach((s) => io.observe(s));
  }
})();

;

/* ===== okane-money.js ===== */
// おかねの物差し：00 そもそも、お金ってなに？（物々交換の物差し・硬貨のひみつ）
(() => {
  const D = window, { $, yen, esc, store } = D.OK;
  const item = (id) => D.ITEMS.find((i) => i.id === id);

  // ===== 物々交換の物差し =====
  const A = $("bxA"), B = $("bxB");
  D.ITEMS.forEach((it) => { [A, B].forEach((s) => { const o = document.createElement("option"); o.value = it.id; o.textContent = `${it.name}（${it.unit}・${yen(it.p25)}円）`; s.appendChild(o); }); });
  A.value = store.get("bxA", "rice"); B.value = store.get("bxB", "notebook");
  [A, B].forEach((s) => s.addEventListener("change", () => { store.set("bxA", A.value); store.set("bxB", B.value); renderBarter(); }));
  function renderBarter() {
    const a = item(A.value), b = item(B.value), n = a.p25 / b.p25;
    $("bxLabel").textContent = `${a.name}（${a.unit}）1つと同じ値打ちなのは`;
    // 数えることば（冊・個・本…）は、品物の単位から取る。わからないときは「つ」
    const m = b.unit.match(/(冊|個|杯|皿|本|足|枚|台|回|ゲーム|パック|袋)/), ctr = m ? m[1] : "つ";
    $("bxValue").innerHTML = `${b.name} ${n >= 10 ? Math.round(n).toLocaleString() : n.toFixed(1)}<span class="u">${ctr}分</span>`;
    // 1つ＝1マス（多いときは最大60マス）
    const shown = Math.min(60, Math.ceil(n)), whole = Math.floor(Math.min(n, 60));
    let s = `<i class="one" title="${esc(a.name)} 1つ"></i>`;
    for (let k = 0; k < shown; k++) s += k < whole ? "<i></i>" : `<i class="part"><b style="width:${(n - whole) * 100}%"></b></i>`;
    $("bxPile").innerHTML = s;
    $("bxSub").innerHTML = `${yen(a.p25)}円 ÷ ${yen(b.p25)}円 ＝ ${n.toFixed(2)}。黄色のマスが${esc(a.name)}1つ、青いマスが${esc(b.name)}1つです${n > 60 ? "（多いので60こまで表示）" : ""}。お金がなかったら、このくらいの${esc(b.name)}を持ち歩いて交換しなければなりません。`;
  }

  // ===== 硬貨のひみつ =====
  let coin = store.get("coin", 1);
  D.COINS.forEach((c) => { const b = document.createElement("button"); b.type = "button"; b.dataset.v = c.v; b.innerHTML = `${c.name}<span class="num">${c.g.toFixed(2)}g・直径${c.d}mm</span>`; b.addEventListener("click", () => { coin = c.v; store.set("coin", coin); renderCoins(); }); $("cnSeg").appendChild(b); });
  $("cnAmt").addEventListener("input", renderCoins);
  const kg = (g) => g >= 1000 ? `${(g / 1000).toLocaleString("ja-JP", { maximumFractionDigits: 1 })}kg` : `${Math.round(g).toLocaleString()}g`;
  const len = (mm) => mm >= 1e6 ? `約${(mm / 1e6).toLocaleString("ja-JP", { maximumFractionDigits: 1 })}km` : mm >= 1000 ? `約${(mm / 1000).toLocaleString("ja-JP", { maximumFractionDigits: 1 })}m` : `約${(mm / 10).toFixed(1)}cm`;
  function renderCoins() {
    [...$("cnSeg").children].forEach((b) => b.setAttribute("aria-pressed", String(+b.dataset.v === coin)));
    const c = D.COINS.find((x) => x.v === coin), amt = Math.max(0, Math.floor(parseFloat($("cnAmt").value) || 0));
    const n = Math.floor(amt / c.v), rest = amt - n * c.v, g = n * c.g, mm = n * c.d;
    $("cnLabel").textContent = `${yen(amt)}円を、全部${c.name}にすると`;
    $("cnValue").innerHTML = `${n.toLocaleString()}<span class="u">枚</span>`;
    const bills = Math.floor(amt / 10000);
    $("cnGrid").innerHTML = [
      { k: "重さ", v: kg(g), s: g >= 2000 ? `2Lのペットボトルの水 約${(g / 2000).toFixed(1)}本ぶん` : "手で持てる重さ" },
      { k: "横にならべると", v: len(mm), s: mm >= 25000 ? `25mプールの約${(mm / 25000).toFixed(1)}ぱいぶん` : `直径${c.d}mmの硬貨を${n.toLocaleString()}枚` },
      { k: "あまり", v: rest ? `${yen(rest)}円` : "なし", s: rest ? `${c.name}ではおつりなしで払えない分` : "ぴったり" },
      { k: "お札なら", v: bills ? `1万円札 ${bills.toLocaleString()}枚・約${bills}g` : "1万円未満", s: "お札は1枚約1g。だからお札は便利" },
    ].map((x) => `<div><span class="k">${x.k}</span><span class="v">${esc(x.v)}</span><span class="s">${esc(x.s)}</span></div>`).join("");
  }

  renderBarter(); renderCoins();
})();

;

/* ===== okane-charts.js ===== */
// おかねの物差し：物価タイムマシン・55年グラフ・できごと・給料と物価・貯金とインフレ・手取り
(() => {
  const D = window, { $, yen, pos, esc, sgn, cpiAt, AVG10 } = D.OK;
  const Y0 = D.CPI_FIRST_YEAR, Y1 = 2025;
  const YEARS = Array.from({ length: Y1 - Y0 + 1 }, (_, i) => Y0 + i);
  const CATS = ["総合", "食料", "菓子類", "外食", "電気代", "通信", "教育", "教養娯楽", "被服及び履物"];
  const CAT_NAME = { "総合": "総合（くらし全体）", "食料": "食料", "菓子類": "菓子類（おやつ）", "外食": "外食", "電気代": "電気代", "通信": "通信（電話・スマホ）", "教育": "教育（授業料など）", "教養娯楽": "教養娯楽（あそび・習いごと）", "被服及び履物": "服とくつ" };
  const EVENTS = [
    { y: 1974, t: "オイルショック", d: "石油の値段が急に上がり、1年で物価が約23%も上がりました。トイレットペーパーの買いだめさわぎも起きました。" },
    { y: 1989, t: "消費税3%スタート", d: "物を買うときに税金がかかるようになりました。その後、1997年に5%、2014年に8%、2019年に10%になりました。" },
    { y: 1999, t: "物価が上がらない時代", d: "1990年代の終わりから約20年、物価はほとんど上がりませんでした。給料もあまり上がりませんでした。" },
    { y: 2014, t: "消費税8%", d: "税率が上がった年は、物価のグラフが一段上がります。" },
    { y: 2022, t: "世界的な物価高と円安", d: "エネルギーや食べ物の値段が世界中で上がり、円安で輸入品も高くなりました。日本でも物価が急に上がり始めました。" },
  ];
  const STORIES = [
    { cat: "通信", from: 2020, to: 2022, t: "スマホ代が大きく下がった", d: "2021年に、携帯電話会社が安い料金プランを次々に出しました。通信の指数は2年で3割ほど下がりました。" },
    { cat: "教育", from: 2009, to: 2011, t: "教育費が下がった年", d: "2010年に公立高校の授業料が無料になりました。2019〜2020年にも、幼児教育や高校・大学の支援が広がり、ふたたび下がっています。" },
    { cat: "電気代", from: 2021, to: 2024, t: "電気代のジェットコースター", d: "2022年に燃料の値段が上がって電気代が急に上がり、2023年は国の補助で下がりました。補助が終わると、また上がります。" },
  ];

  // 汎用：折れ線グラフ
  function lineChart(svg, opt) {
    const { W, H, M, xs, series, yMin, yMax, yTicks, xTicks, fmtX, onHover, marks = [] } = opt;
    const X = (i) => M.l + (i / (xs.length - 1)) * (W - M.l - M.r);
    const Y = (v) => M.t + (1 - (v - yMin) / (yMax - yMin)) * (H - M.t - M.b);
    let s = "";
    yTicks.forEach((g) => { s += `<line x1="${M.l}" x2="${W - M.r}" y1="${Y(g)}" y2="${Y(g)}" stroke="var(--line)" stroke-dasharray="${g === 100 ? "" : "2 4"}"/><text x="${M.l - 8}" y="${Y(g) + 4}" text-anchor="end">${g}</text>`; });
    xs.forEach((x, i) => { if (xTicks(x, i)) s += `<text x="${X(i)}" y="${H - 8}" text-anchor="middle">${fmtX(x)}</text>`; });
    marks.forEach((m) => { s += m(X, Y); });
    series.forEach((se) => {
      const d = se.v.map((v, i) => v == null ? null : [X(i), Y(v)]).filter(Boolean).map((p, i) => `${i ? "L" : "M"}${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join(" ");
      s += `<path d="${d}" fill="none" stroke="${se.c}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>`;
      const li = se.v.length - 1;
      s += `<circle cx="${X(li)}" cy="${Y(se.v[li])}" r="4.5" fill="${se.c}" stroke="var(--card)" stroke-width="2"/>`;
      if (se.label) s += `<text class="lbl" x="${X(li) + 10}" y="${Y(se.v[li]) + (se.dy || 0) - 2}">${se.label}</text><text x="${X(li) + 10}" y="${Y(se.v[li]) + (se.dy || 0) + 13}">${se.end}</text>`;
    });
    s += `<g class="hov" style="display:none"><line class="hl" y1="${M.t}" y2="${H - M.b}" stroke="var(--ink-2)"/>${series.map((se, k) => `<circle class="hc${k}" r="5" fill="${se.c}" stroke="var(--card)" stroke-width="2"/>`).join("")}</g>`;
    s += `<rect class="hit" x="${M.l - 10}" y="0" width="${W - M.l - M.r + 20}" height="${H}" fill="transparent"/>`;
    svg.innerHTML = s;
    const hov = svg.querySelector(".hov"), tip = opt.tip;
    function move(ev) {
      const pt = svg.createSVGPoint(); pt.x = ev.clientX; pt.y = ev.clientY;
      const p = pt.matrixTransform(svg.getScreenCTM().inverse());
      const i = Math.max(0, Math.min(xs.length - 1, Math.round(((p.x - M.l) / (W - M.l - M.r)) * (xs.length - 1))));
      hov.style.display = ""; hov.querySelector(".hl").setAttribute("x1", X(i)); hov.querySelector(".hl").setAttribute("x2", X(i));
      let top = Infinity;
      series.forEach((se, k) => { const c = hov.querySelector(".hc" + k); c.setAttribute("cx", X(i)); c.setAttribute("cy", Y(se.v[i])); top = Math.min(top, Y(se.v[i])); });
      const box = svg.getBoundingClientRect(), card = tip.parentElement.getBoundingClientRect(), sc = box.width / W;
      const z = parseFloat(getComputedStyle(tip.parentElement).zoom) * (parseFloat(getComputedStyle(document.querySelector("main")).zoom) || 1) || 1; // 文字を大きくしたとき（zoom）のずれを直す
      tip.hidden = false;
      tip.style.left = Math.max(80, Math.min(card.width - 80, box.left - card.left + X(i) * sc)) / z + "px";
      tip.style.top = (box.top - card.top + top * sc - 8) / z + "px";
      tip.innerHTML = onHover(i);
    }
    const hit = svg.querySelector(".hit");
    hit.addEventListener("pointermove", move); hit.addEventListener("pointerdown", move);
    hit.addEventListener("pointerleave", () => { hov.style.display = "none"; tip.hidden = true; });
    return { X, Y };
  }
  D.OK.lineChart = lineChart;

  // ===== 03 物価タイムマシン =====
  const tmCat = $("tmCat"), tmYear = $("tmYear"), tmPrice = $("tmPrice");
  CATS.forEach((c) => { const o = document.createElement("option"); o.value = c; o.textContent = CAT_NAME[c]; tmCat.appendChild(o); });
  function renderTM() {
    const cat = tmCat.value, y = +tmYear.value, p = pos(tmPrice, 1);
    const then = p * cpiAt(cat, y) / cpiAt(cat, 2025);
    $("tmYearLabel").textContent = y;
    [...$("tmPresets").children].forEach((c) => c.setAttribute("aria-pressed", String(+c.dataset.y === y)));
    $("tmLabel").textContent = `${y}年なら、だいたい`;
    $("tmValue").innerHTML = `${yen(then)}<span class="u">円</span>`;
    const ch = (cpiAt(cat, 2025) / cpiAt(cat, y) - 1) * 100;
    $("tmSub").innerHTML = `「${esc(CAT_NAME[cat])}」の値段は、${y}年から2025年までに <b>${sgn(ch, 1)}</b> 変わりました（指数 ${cpiAt(cat, y).toFixed(1)} → 100）。` + (ch < 0 ? " 昔のほうが高かったことになります。" : "");
    const ev = EVENTS.find((e) => Math.abs(e.y - y) <= 1);
    $("tmWage").innerHTML = (D.MINWAGE[y] ? `そのころの最低賃金（全国平均）は <b>${yen(D.MINWAGE[y])}円</b>。今の値段${yen(p)}円の品物は、当時の値段で約${(then / D.MINWAGE[y] * 60).toFixed(0)}分はたらけば買えました。` : `最低賃金の全国平均は2002年度からのデータを使っています。`) + (ev ? `<br>このころのできごと：<b>${ev.t}</b>` : "");
    drawLong();
  }
  [tmCat, tmYear, tmPrice].forEach((el) => el.addEventListener("input", renderTM));
  // よく使う年（2026年に何歳かで考える）
  [[2010, "今の高校1年生が生まれた年"], [1995, "今31歳の人が生まれた年"], [1985, "今41歳の人が生まれた年"], [1974, "オイルショックの年"]].forEach(([y, t]) => {
    const b = document.createElement("button");
    b.type = "button"; b.className = "chip"; b.dataset.y = y; b.innerHTML = `${y}年<span class="num">${t}</span>`;
    b.addEventListener("click", () => { tmYear.value = y; renderTM(); });
    $("tmPresets").appendChild(b);
  });

  function drawLong() {
    const cat = tmCat.value, y = +tmYear.value;
    const vals = YEARS.map((yy) => cpiAt(cat, yy));
    const showBase = cat !== "総合";
    const hi = Math.max(...vals, 100), lo = Math.min(...vals, 20);
    const yMax = Math.ceil(hi / 20) * 20, yMin = Math.max(0, Math.floor(lo / 20) * 20);
    const ticks = []; for (let g = yMin; g <= yMax; g += 20) ticks.push(g);
    $("longTitle").textContent = `${CAT_NAME[cat]}の物価の55年（2025年＝100）`;
    $("longLegend").innerHTML = `<span style="--c:var(--cool)">${esc(CAT_NAME[cat])}</span>` + (showBase ? `<span style="--c:var(--muted)">総合（くらし全体）</span>` : "");
    const series = [{ v: vals, c: "var(--cool)", label: cat === "総合" ? "総合" : cat.replace("及び履物", ""), end: "100" }];
    if (showBase) series.unshift({ v: YEARS.map((yy) => cpiAt("総合", yy)), c: "var(--muted)" });
    const yi = y - Y0;
    lineChart($("longChart"), {
      W: 760, H: 330, M: { l: 40, r: 84, t: 30, b: 28 }, xs: YEARS, series, yMin, yMax, yTicks: ticks,
      xTicks: (x) => x % 10 === 0 || x === 2025, fmtX: (x) => x, tip: $("longTip"),
      marks: [
        (X, Y) => `<rect x="${X(yi)}" y="30" width="${X(YEARS.length - 1) - X(yi)}" height="272" fill="var(--ruler)" opacity=".18" rx="4"/><line x1="${X(yi)}" x2="${X(yi)}" y1="30" y2="302" stroke="var(--ruler)" stroke-width="2"/><text class="ev" x="${X(yi) + 4}" y="42">${y}年→今</text>`,
        (X, Y) => cat === "総合" ? EVENTS.map((e, k) => { const i = e.y - Y0; return `<circle cx="${X(i)}" cy="${Y(vals[i])}" r="4" fill="var(--ruler)" stroke="var(--ink)" stroke-width="1.5"/><text class="ev" x="${X(i)}" y="${Y(vals[i]) - (k % 2 ? 26 : 12)}" text-anchor="middle">${e.t}</text>`; }).join("") : "",
      ],
      onHover: (i) => `<b>${YEARS[i]}年</b><br>${esc(CAT_NAME[cat])} <b>${vals[i].toFixed(1)}</b>` + (showBase ? `<br>総合 <b>${cpiAt("総合", YEARS[i]).toFixed(1)}</b>` : "") + `<br>今の1,000円は <b>${yen(1000 * vals[i] / 100)}円</b>`,
    });
  }
  $("longTableBtn").addEventListener("click", () => {
    const w = $("longTable"), open = w.hidden;
    w.hidden = !open; $("longTableBtn").setAttribute("aria-expanded", String(open)); $("longTableBtn").textContent = open ? "表を閉じる" : "数字の表で見る";
    if (open && !w.innerHTML) {
      w.innerHTML = `<table class="data"><thead><tr><th>年</th>${CATS.map((c) => `<th>${c.replace("及び履物", "")}</th>`).join("")}<th>最低賃金</th></tr></thead><tbody>` +
        YEARS.slice().reverse().map((y) => `<tr><td>${y}</td>${CATS.map((c) => `<td>${cpiAt(c, y).toFixed(1)}</td>`).join("")}<td>${D.MINWAGE[y] ? yen(D.MINWAGE[y]) : "—"}</td></tr>`).join("") + "</tbody></table>";
    }
  });

  // できごとカード（小さなグラフつき）
  $("events").innerHTML = STORIES.map((s, k) => {
    const ys = YEARS.filter((y) => y >= s.from - 4 && y <= Math.min(2025, s.to + 2));
    const v = ys.map((y) => cpiAt(s.cat, y));
    const lo = Math.min(...v), hi = Math.max(...v);
    const X = (i) => 4 + (i / (ys.length - 1)) * 292, Y = (x) => 40 - ((x - lo) / (hi - lo || 1)) * 34;
    const d = v.map((x, i) => `${i ? "L" : "M"}${X(i).toFixed(1)} ${Y(x).toFixed(1)}`).join(" ");
    const a = ys.indexOf(s.from), b = ys.indexOf(s.to);
    const ch = (cpiAt(s.cat, s.to) / cpiAt(s.cat, s.from) - 1) * 100;
    return `<div class="event"><span class="yr">${s.from}→${s.to}年・${esc(CAT_NAME[s.cat])} ${sgn(ch)}</span><b>${s.t}</b>
      <svg viewBox="0 0 300 46" preserveAspectRatio="none" aria-hidden="true"><rect x="${X(a)}" y="0" width="${X(b) - X(a)}" height="46" fill="var(--ruler)" opacity=".25"/><path d="${d}" fill="none" stroke="var(--cool)" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>
      <p>${s.d}</p></div>`;
  }).join("");

  // ===== 04 給料と物価 =====
  const RY = Object.keys(D.MINWAGE).map(Number).filter((y) => y <= 2025);
  const w0 = D.MINWAGE[2002], c0 = cpiAt("総合", 2002);
  const wI = RY.map((y) => D.MINWAGE[y] / w0 * 100), cI = RY.map((y) => cpiAt("総合", y) / c0 * 100);
  lineChart($("raceChart"), {
    W: 760, H: 300, M: { l: 40, r: 110, t: 16, b: 28 }, xs: RY, yMin: 90, yMax: 180, yTicks: [100, 120, 140, 160, 180],
    series: [
      { v: wI, c: "var(--hot)", label: "最低賃金", end: wI[wI.length - 1].toFixed(0) + "（" + (wI[wI.length - 1] / 100).toFixed(2) + "倍）" },
      { v: cI, c: "var(--cool)", label: "物価", end: cI[cI.length - 1].toFixed(0) + "（" + (cI[cI.length - 1] / 100).toFixed(2) + "倍）" },
    ],
    xTicks: (x) => x % 4 === 2 || x === 2025, fmtX: (x) => x, tip: $("raceTip"),
    onHover: (i) => `<b>${RY[i]}年</b><br>最低賃金 <b>${yen(D.MINWAGE[RY[i]])}円</b>（${wI[i].toFixed(0)}）<br>物価指数 <b>${cpiAt("総合", RY[i]).toFixed(1)}</b>（${cI[i].toFixed(0)}）`,
  });
  const real = wI[wI.length - 1] / cI[cI.length - 1];
  $("raceText").innerHTML = `2002年から2025年までに、最低賃金は <b>${(wI[wI.length - 1] / 100).toFixed(2)}倍</b>、物価は <b>${(cI[cI.length - 1] / 100).toFixed(2)}倍</b> になりました。物価の上がり方を差し引くと、最低賃金ではたらいて買えるものは約 <b>${Math.round((real - 1) * 100)}%</b> 増えたことになります。2026年度にはさらに1,177円に上がります。`;

  // ===== 05 貯金とインフレ =====
  let inf = 2;
  $("infSeg").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; inf = +b.dataset.v; renderSave(); });
  ["svAmt", "svYears", "svRate"].forEach((id) => $(id).addEventListener("input", renderSave));
  function renderSave() {
    [...$("infSeg").children].forEach((b) => b.setAttribute("aria-pressed", String(+b.dataset.v === inf)));
    const A = pos($("svAmt"), 10000), n = +$("svYears").value, r = Math.max(0, parseFloat($("svRate").value) || 0) / 100, f = inf / 100;
    $("svYearsLabel").textContent = n; $("svLabel").textContent = `${n}年後、通帳には ${yen(A * Math.pow(1 + r, n))}円`;
    const realV = A * Math.pow(1 + r, n) / Math.pow(1 + f, n);
    $("svValue").innerHTML = `${yen(realV)}<span class="u">円ぶんの価値</span>`;
    const diff = realV / A - 1;
    $("svSub").innerHTML = Math.abs(diff) < 0.005 ? "利息と物価の上がり方がほぼ同じなので、買う力はほとんど変わりません。"
      : diff < 0 ? `利息より物価の上がり方が大きいので、今の${yen(A)}円で買えるものの <b>${Math.round(realV / A * 100)}%</b> しか買えなくなります。`
      : `物価より利息のほうが大きいので、買う力は <b>${Math.round(diff * 100)}%</b> 増えます。`;
    const W = 560, H = 220, M = { l: 52, r: 12, t: 12, b: 26 };
    const pts = Array.from({ length: n + 1 }, (_, i) => ({ nom: A * Math.pow(1 + r, i), real: A * Math.pow(1 + r, i) / Math.pow(1 + f, i) }));
    const mx = Math.max(...pts.map((p) => p.nom)) * 1.05, mn = Math.min(...pts.map((p) => p.real)) * 0.9;
    const yMin = Math.floor(mn / (A / 10)) * (A / 10), yMax = mx;
    const X = (i) => M.l + (i / n) * (W - M.l - M.r), Y = (v) => M.t + (1 - (v - yMin) / (yMax - yMin)) * (H - M.t - M.b);
    let s = "";
    for (let k = 0; k <= 4; k++) { const v = yMin + (yMax - yMin) * k / 4; s += `<line x1="${M.l}" x2="${W - M.r}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--line)" stroke-dasharray="2 4"/><text x="${M.l - 6}" y="${Y(v) + 4}" text-anchor="end">${yen(v)}</text>`; }
    [0, Math.round(n / 2), n].forEach((i) => { s += `<text x="${X(i)}" y="${H - 6}" text-anchor="middle">${i}年後</text>`; });
    const path = (k) => pts.map((p, i) => `${i ? "L" : "M"}${X(i).toFixed(1)} ${Y(p[k]).toFixed(1)}`).join(" ");
    s += `<path d="${path("nom")} L${X(n)} ${Y(pts[n].real)} ${pts.slice().reverse().map((p, j) => `L${X(n - j).toFixed(1)} ${Y(p.real).toFixed(1)}`).join(" ")} Z" fill="var(--hot)" opacity=".10"/>`;
    s += `<path d="${path("nom")}" fill="none" stroke="var(--accent)" stroke-width="2.5"/><path d="${path("real")}" fill="none" stroke="var(--hot)" stroke-width="2.5"/>`;
    s += `<circle cx="${X(n)}" cy="${Y(pts[n].real)}" r="4.5" fill="var(--hot)" stroke="var(--card)" stroke-width="2"/>`;
    $("svChart").innerHTML = s;
  }
  const c15 = cpiAt("総合", 2015);
  $("svReal").innerHTML = `物価指数は2015年が${c15.toFixed(1)}、2025年が100です。2015年に貯金箱に入れた1万円は、2025年には <b>約${yen(10000 * c15 / 100)}円ぶん</b> の物しか買えなくなっています（金額は1万円のまま）。反対に、2015年の1万円と同じだけ買うには、今は <b>約${yen(10000 * 100 / c15)}円</b> 必要です。1年あたりにならすと、物価は約${((Math.pow(100 / c15, 1 / 10) - 1) * 100).toFixed(1)}%ずつ上がりました。`;

  // ===== 06 手取り =====
  const payIn = $("payIn"); let yearN = 1;
  $("paySeg").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; payIn.value = b.dataset.pay; renderPay(); });
  $("yearSeg").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; yearN = +b.dataset.y; renderPay(); });
  payIn.addEventListener("input", renderPay);
  const kyuyo = (a) => a <= 1900000 ? Math.min(a, 650000) : a <= 3600000 ? a * .3 + 80000 : a <= 6600000 ? a * .2 + 440000 : a <= 8500000 ? a * .1 + 1100000 : 1950000;
  const kiso = (i) => i <= 1320000 ? 950000 : i <= 3360000 ? 880000 : i <= 4890000 ? 680000 : i <= 6550000 ? 630000 : i <= 23500000 ? 580000 : 0;
  function itax(t) {
    if (t <= 0) return 0;
    const br = [[1950000, .05, 0], [3300000, .10, 97500], [6950000, .20, 427500], [9000000, .23, 636000], [18000000, .33, 1536000], [40000000, .40, 2796000], [Infinity, .45, 4796000]];
    const [, r, d] = br.find((b) => t <= b[0]); return (t * r - d) * 1.021;
  }
  D.OK.calcPay = (m, yr) => {
    const ken = m * .0495, kodomo = m * .00115, nen = Math.min(m, 650000) * .0915, koyo = m * .005;
    const sha = ken + kodomo + nen + koyo, annual = m * 12, shaY = sha * 12;
    const shotoku = Math.max(0, annual - kyuyo(annual));
    const taxable = Math.max(0, Math.floor((shotoku - shaY - kiso(shotoku)) / 1000) * 1000);
    const tax = itax(taxable) / 12;
    let jumin = 0;
    if (yr === 2 && shotoku > 450000) jumin = (Math.max(0, (shotoku - shaY - 430000) * .1 - 2500) + 5000) / 12;
    return { ken, kodomo, nen, koyo, tax, jumin, net: m - sha - tax - jumin };
  };
  function renderPay() {
    const m = Math.max(0, parseFloat(payIn.value) || 0);
    [...$("paySeg").children].forEach((c) => c.setAttribute("aria-pressed", String(+c.dataset.pay === m)));
    [...$("yearSeg").children].forEach((c) => c.setAttribute("aria-pressed", String(+c.dataset.y === yearN)));
    const r = D.OK.calcPay(m, yearN);
    const parts = [
      { k: "厚生年金", v: r.nen, c: "var(--seg1)", w: "老後などにもらう年金のための保険料" },
      { k: "健康保険", v: r.ken, c: "var(--seg2)", w: "病院代が3割ですむための保険料" },
      { k: "子ども・子育て支援金", v: r.kodomo, c: "var(--seg6)", w: "2026年度から。子育て支援に使われる" },
      { k: "雇用保険", v: r.koyo, c: "var(--seg5)", w: "仕事をなくしたときなどのための保険料" },
      { k: "所得税", v: r.tax, c: "var(--seg3)", w: "国に払う税金。収入が多いほど割合が上がる" },
      { k: "住民税", v: r.jumin, c: "var(--seg4)", w: yearN === 1 ? "1年目は、ふつうはまだ引かれない" : "住んでいる市区町村・都道府県に払う税金" },
    ];
    const ded = m - r.net;
    $("netValue").innerHTML = `${yen(r.net)}<span class="u">円</span>`;
    $("netSub").innerHTML = m ? `額面 ${yen(m)}円のうち <b>${yen(ded)}円</b>（約${Math.round(ded / m * 100)}%）が引かれます。1年では約${yen(ded * 12)}円です。` : "給料を入れてください。";
    $("stack").innerHTML = m ? `<div class="take" style="flex:0 0 ${(r.net / m) * 100}%" title="手取り"></div>` + parts.filter((p) => p.v > 0).map((p) => `<div style="flex:1 1 ${(p.v / m) * 100}%;background:${p.c}" title="${p.k} ${yen(p.v)}円"></div>`).join("") : "";
    // 給与明細書のかたちで見せる
    const sha = r.ken + r.kodomo + r.nen + r.koyo, zei = r.tax + r.jumin;
    const row = (p) => `<div class="slip-row"><span class="sw" style="background:${p.c}"></span><span class="nm">${p.k}<small>${p.w}</small></span><span class="amt">${yen(p.v)}</span></div>`;
    $("deds").innerHTML = `<div class="slip">
      <div class="slip-head"><b>給与明細書</b><span>${yearN === 1 ? "はたらきはじめて1年目" : "2年目から"}・2026年度の料率・単位：円</span></div>
      <div class="slip-sec"><span class="tag">支給</span><div class="slip-rows"><div class="slip-row"><span></span><span class="nm">基本給（額面）<small>会社が決めた1か月の給料</small></span><span class="amt">${yen(m)}</span></div></div></div>
      <div class="slip-sec"><span class="tag">控除</span><div class="slip-rows">${parts.slice(0, 4).map(row).join("")}<div class="slip-row sum"><span></span><span class="nm">社会保険料の合計</span><span class="amt">${yen(sha)}</span></div>${parts.slice(4).map(row).join("")}<div class="slip-row sum"><span></span><span class="nm">税金の合計</span><span class="amt">${yen(zei)}</span></div></div></div>
      <div class="slip-total"><b>差引支給額（手取り）</b><span class="slip-stamp">${yearN === 1 ? "住民税<br>まだ<br>なし" : "住民税<br>スタート"}</span><span class="num">${yen(r.net)}円</span></div>
    </div>
    <p class="hint">手取りは、あなたの時給（${yen(D.OK.wage())}円）でいうと約${Math.round(r.net / D.OK.wage())}時間ぶんです。</p>`;
    const emp = r.ken + r.kodomo + r.nen + m * .0085;
    $("employerText").innerHTML = `この給料なら、会社は健康保険・厚生年金・子ども・子育て支援金・雇用保険で、毎月およそ <b class="num">${yen(emp)}円</b> を給料とは別に払っています。会社から見ると、あなたをやとうのに月 <b class="num">${yen(m + emp)}円</b> 以上かかっている計算です（雇用保険の会社負担0.85%。労災保険などはふくみません）。`;
  }
  D.OK.onUnit(renderPay);

  renderTM(); renderSave(); renderPay();
})();

;

/* ===== okane-map.js ===== */
// おかねの物差し：日本地図（47都道府県のタイル地図）
(() => {
  const D = window, { $, yen, esc, store } = D.OK;
  const N = D.PREFS.length;
  let metric = store.get("mapMetric", "minutes"), item = store.get("mapItem", "onigiri"), sel = D.OK.pref() >= 0 ? D.OK.pref() : 12;
  if (!D.CITY[item]) item = "onigiri";
  const itemSel = $("mapItem");
  D.ITEMS.forEach((it) => { if (!D.CITY[it.id]) return; const o = document.createElement("option"); o.value = it.id; o.textContent = `${it.name}（${it.unit}）`; itemSel.appendChild(o); });
  itemSel.value = item;
  itemSel.addEventListener("change", () => { item = itemSel.value; store.set("mapItem", item); render(); });
  $("mapMetric").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; metric = b.dataset.m; store.set("mapMetric", metric); render(); });
  const short = (p) => p;
  const it = () => D.ITEMS.find((x) => x.id === item);

  function values() {
    const price = D.CITY[item];
    if (metric === "wage") return D.PREF_WAGE.slice();
    if (metric === "price") return price.slice();
    if (metric === "rpi") return D.RPI_TOTAL.slice();
    // 物価の高さを考えた最低賃金：最低賃金 ÷ 物価の高さ（全国＝100）× 100
    if (metric === "realwage") return D.PREF_WAGE.map((w, i) => w / D.RPI_TOTAL[i] * 100);
    return price.map((p, i) => p == null ? null : p / D.PREF_WAGE[i] * 60);
  }
  const noItem = () => ["wage", "rpi", "realwage"].includes(metric);
  const fmt = (v) => v == null ? "—" : metric === "minutes" ? (v < 60 ? v.toFixed(1) : (v / 60).toFixed(1) + "h") : metric === "rpi" ? v.toFixed(1) : (metric === "wage" || metric === "realwage") ? yen(v) : v >= 10000 ? (v / 10000).toFixed(1) + "万" : yen(v);
  const fmtLong = (v) => v == null ? "調査なし" : metric === "minutes" ? D.OK.hmText(v / 60) : metric === "rpi" ? `${v.toFixed(1)}（全国＝100）` : yen(v) + "円";
  function rankOf(vals, i) {
    // 大きい順の順位（値段・最低賃金は高い順、分は長い順）
    const v = vals[i]; if (v == null) return null;
    return vals.filter((x) => x != null && x > v).length + 1;
  }

  function render() {
    [...$("mapMetric").children].forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.m === metric)));
    itemSel.disabled = noItem();
    const vals = values(), known = vals.filter((v) => v != null);
    const lo = Math.min(...known), hi = Math.max(...known);
    const bin = (v) => v == null ? 0 : Math.min(5, 1 + Math.floor(((v - lo) / (hi - lo || 1)) * 5));
    const C = 42, my = D.OK.pref();
    let s = "";
    D.PREFS.forEach((p, i) => {
      const [cx, cy] = D.PREF_TILE[i], x = cx * C + 6, y = cy * C + 4, b = bin(vals[i]);
      const fill = b ? `var(--q${b})` : "var(--soft)", ink = b >= 4 ? "var(--q-ink-hi)" : "var(--q-ink-lo)";
      s += `<g class="tile${i === sel ? " sel" : ""}" data-i="${i}" tabindex="0" role="button" aria-label="${esc(D.OK.prefName(i))} ${esc(fmtLong(vals[i]))}">
        <rect x="${x}" y="${y}" width="${C - 2}" height="${C - 2}" rx="6" fill="${fill}"/>
        <text x="${x + (C - 2) / 2}" y="${y + 17}" text-anchor="middle" fill="${ink}">${short(p.p)}</text>
        <text class="v" x="${x + (C - 2) / 2}" y="${y + 32}" text-anchor="middle" fill="${ink}">${fmt(vals[i])}</text>
        ${i === my ? `<circle cx="${x + C - 8}" cy="${y + 6}" r="5" fill="var(--ruler)" stroke="var(--card)" stroke-width="1.5"/>` : ""}
      </g>`;
    });
    // 見出しと補助
    const unitLabel = metric === "minutes" ? `${it().name}を買うのに何分はたらく？` : metric === "wage" ? "2026年度の最低賃金（円／時）" : metric === "rpi" ? "くらし全体の物価の高さ（全国平均＝100）" : metric === "realwage" ? "物価の高さを考えた最低賃金（円／時）" : `${it().name}（${it().unit}）の値段（円）`;
    s += `<text x="8" y="24" font-family="Zen Kaku Gothic New, sans-serif" font-size="15" font-weight="700" fill="var(--ink)">${esc(unitLabel)}</text><text x="8" y="44" font-family="Zen Kaku Gothic New, sans-serif" font-size="12" fill="var(--muted)">マスを押すと、くわしい数字が出ます</text>`;
    $("mapSvg").innerHTML = s;
    $("mapSvg").querySelectorAll(".tile").forEach((g) => {
      const go = () => { sel = +g.dataset.i; render(); };
      g.addEventListener("click", go);
      g.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); go(); } });
    });
    $("mapLegend").innerHTML = `<span>${metric === "minutes" ? "短い" : "低い"}</span><span class="ramp">${[1, 2, 3, 4, 5].map((k) => `<i style="background:var(--q${k})"></i>`).join("")}</span><span>${metric === "minutes" ? "長い" : "高い"}</span><span class="num">（${fmtLong(lo)} 〜 ${fmtLong(hi)}）</span>` + (my >= 0 ? `<span><span class="sw" style="background:var(--ruler);border-radius:50%"></span>あなたの県</span>` : "");
    renderCard(vals);
    renderRank(vals);
    renderInsight();
  }

  function renderCard(vals) {
    const i = sel, p = D.PREFS[i], x = it(), price = D.CITY[item][i];
    const w = D.PREF_WAGE[i], old = D.PREF_WAGE_OLD[i];
    const mins = price == null ? null : price / w * 60;
    const rk = rankOf(vals, i);
    const rkText = rk == null ? "" : metric === "minutes" ? `47都道府県で、長いほうから${rk}番目` : metric === "wage" ? `47都道府県で、高いほうから${rk}番目` : `47都道府県で、高いほうから${rk}番目`;
    $("prefCard").innerHTML = `<div class="label">えらんだ県</div>
      <div><div class="pname">${esc(D.OK.prefName(i))}</div><div class="pcity">値段は${esc(p.city)}の2025年平均</div></div>
      <div class="pref-stats">
        <div><span class="k">最低賃金（2026年度）</span><span class="v">${yen(w)}円</span><span class="s">前の年度 ${yen(old)}円から +${w - old}円・${D.PREF_WAGE_DATE[i]}から</span></div>
        <div><span class="k">${esc(x.name)}（${esc(x.unit)}）</span><span class="v">${price == null ? "—" : yen(price) + "円"}</span><span class="s">東京23区は ${yen(D.CITY[item][12])}円</span></div>
        <div><span class="k">買うのにはたらく時間</span><span class="v">${mins == null ? "—" : D.OK.hmText(mins / 60)}</span><span class="s">値段 ÷ この県の最低賃金</span></div>
        <div><span class="k">くらしの物価の高さ</span><span class="v">${D.RPI_TOTAL[i].toFixed(1)}</span><span class="s">全国平均＝100・家賃など住居は${D.RPI_HOUSING[i].toFixed(1)}</span></div>
        <div><span class="k">物価を考えた最低賃金</span><span class="v">${yen(w / D.RPI_TOTAL[i] * 100)}円</span><span class="s">全国と同じ物価だったらいくら分か</span></div>
        <div><span class="k">地図の順位</span><span class="v">${rk == null ? "—" : rk + "位"}</span><span class="s">${rkText}</span></div>
      </div>`;
    const b = document.createElement("button");
    b.type = "button"; b.className = "btn ghost";
    b.textContent = D.OK.pref() === i ? "あなたの物差しに設定ずみ" : "この県の時給を、あなたの物差しにする";
    b.disabled = D.OK.pref() === i;
    b.addEventListener("click", () => { D.OK.setPref(i); render(); });
    $("prefCard").appendChild(b);
  }

  function renderRank(vals) {
    const rows = vals.map((v, i) => ({ v, i })).filter((r) => r.v != null).sort((a, b) => b.v - a.v);
    const top = rows.slice(0, 5), bot = rows.slice(-5).reverse();
    const hiT = metric === "minutes" ? "長くはたらく" : "高い", loT = metric === "minutes" ? "短くてすむ" : (metric === "wage" || metric === "realwage") ? "低い" : "安い";
    $("mapRankTitle").textContent = metric === "minutes" ? `${it().name}を買うのにかかる時間` : metric === "wage" ? "最低賃金" : metric === "rpi" ? "くらしの物価の高さ" : metric === "realwage" ? "物価の高さを考えた最低賃金" : `${it().name}の値段`;
    const li = (r) => `<li><button type="button" data-i="${r.i}">${esc(D.OK.prefName(r.i))}</button><span class="num">${metric === "minutes" ? r.v.toFixed(1) + "分" : metric === "rpi" ? r.v.toFixed(1) : yen(r.v) + "円"}</span></li>`;
    $("mapRank").innerHTML = `<div><h4>${hiT} 5県</h4><ol>${top.map(li).join("")}</ol></div><div><h4>${loT} 5県</h4><ol>${bot.map(li).join("")}</ol></div>`;
    $("mapRank").querySelectorAll("button").forEach((b) => b.addEventListener("click", () => { sel = +b.dataset.i; render(); }));
  }

  function renderInsight() {
    const xs = [], ys = [];
    D.CITY[item].forEach((p, i) => { if (p != null) { xs.push(D.PREF_WAGE[i]); ys.push(p); } });
    const n = xs.length, mx = xs.reduce((a, b) => a + b) / n, myv = ys.reduce((a, b) => a + b) / n;
    let sxy = 0, sxx = 0, syy = 0;
    for (let k = 0; k < n; k++) { sxy += (xs[k] - mx) * (ys[k] - myv); sxx += (xs[k] - mx) ** 2; syy += (ys[k] - myv) ** 2; }
    const r = sxy / Math.sqrt(sxx * syy);
    const word = r >= 0.6 ? "強い関係があります" : r >= 0.3 ? "少し関係があります" : r > -0.3 ? "ほとんど関係がありません" : "反対の関係があります";
    const x = it(), mins = D.CITY[item].map((p, i) => p == null ? null : p / D.PREF_WAGE[i] * 60);
    const valid = mins.map((m, i) => ({ m, i })).filter((o) => o.m != null).sort((a, b) => a.m - b.m);
    const best = valid[0], worst = valid[valid.length - 1];
    $("mapInsight").innerHTML = `「${esc(x.name)}」の値段と、その県の最低賃金をくらべると、<b>${word}</b>（相関係数 r＝${r.toFixed(2)}）。相関係数は、2つの数字が一緒に増えたり減ったりするかを −1〜1 で表したもので、1に近いほど「片方が高いともう片方も高い」ことを表します。<br>同じ${esc(x.name)}を買うのにはたらく時間がいちばん短いのは${esc(D.OK.prefName(best.i))}（${D.OK.hmText(best.m / 60)}）、いちばん長いのは${esc(D.OK.prefName(worst.i))}（${D.OK.hmText(worst.m / 60)}）。最低賃金が高い県でも、値段も高ければ、買いやすいとはかぎりません。`;
  }

  // さがす機能から、県をえらんで開けるように
  D.OK.selectPrefOnMap = (i) => { sel = i; render(); };
  D.OK.onUnit(render);
  render();
})();

;

/* ===== okane-kakei.js ===== */
// おかねの物差し：家族の1万円（家計調査）・今日の発見・スタンプラリー
(() => {
  const D = window, { $, yen, esc, store, sgn, cpiAt } = D.OK;
  const K = D.KAKEI, KY0 = D.KAKEI_FIRST_YEAR, KY1 = KY0 + K["消費支出"].length - 1;
  const kv = (cat, y) => K[cat][y - KY0] / 12; // 年間 → 1か月
  const GROUPS = [
    { k: "食料", cats: ["食料"], c: "var(--seg3)", d: "食べ物・飲み物・外食" },
    { k: "住まい・光熱", cats: ["住居", "光熱・水道", "家具・家事用品"], c: "var(--seg1)", d: "家賃や修理、電気・ガス・水道、家具や洗剤" },
    { k: "交通・通信", cats: ["交通・通信"], c: "var(--seg6)", d: "電車、車、ガソリン、スマホ・インターネット" },
    { k: "教養娯楽", cats: ["教養娯楽"], c: "var(--seg5)", d: "旅行、ゲーム、本、習いごと、テレビ" },
    { k: "教育・医療", cats: ["教育", "保健医療"], c: "var(--ruler)", d: "授業料や塾、病院や薬" },
    { k: "服とくつ", cats: ["被服及び履物"], c: "var(--seg4)", d: "服、くつ、クリーニング" },
    { k: "その他", cats: ["その他の消費支出"], c: "var(--muted)", d: "こづかい、おつきあい、理容・美容、仕送りなど" },
  ];
  const gv = (g, y) => g.cats.reduce((s, c) => s + kv(c, y), 0);

  // ===== 06 家族の1万円 =====
  const kkYear = $("kkYear"), kkComp = $("kkComp");
  for (let y = KY1; y >= KY0; y--) { [kkYear, kkComp].forEach((s) => { const o = document.createElement("option"); o.value = y; o.textContent = y + "年"; s.appendChild(o); }); }
  kkYear.value = KY1; kkComp.value = 2015;
  let focus = -1;
  [kkYear, kkComp].forEach((s) => s.addEventListener("change", renderKakei));
  function renderKakei() {
    const y = +kkYear.value, c = +kkComp.value, tot = kv("消費支出", y), totC = kv("消費支出", c);
    $("kkTotal").innerHTML = `<div class="big">月 ${yen(tot)}円</div><div class="s">1日あたり約${yen(tot / 30.4)}円・${c}年は月${yen(totC)}円（${sgn((tot / totC - 1) * 100, 1)}）</div>`;
    // 100マスに配分（最大剰余法）
    const shares = GROUPS.map((g) => gv(g, y) / tot * 100);
    const base = shares.map(Math.floor); let rest = 100 - base.reduce((a, b) => a + b);
    shares.map((s, i) => ({ i, r: s - Math.floor(s) })).sort((a, b) => b.r - a.r).slice(0, rest).forEach((o) => base[o.i]++);
    const w = $("waffle"); w.innerHTML = "";
    base.forEach((n, gi) => { for (let k = 0; k < n; k++) {
      const b = document.createElement("button"); b.type = "button"; b.style.background = GROUPS[gi].c;
      b.className = focus >= 0 && focus !== gi ? "dim" : "";
      b.title = `${GROUPS[gi].k}：1万円のうち約${yen(shares[gi] * 100)}円`;
      b.setAttribute("aria-label", b.title);
      b.addEventListener("click", () => { focus = focus === gi ? -1 : gi; renderKakei(); });
      w.appendChild(b);
    } });
    $("kkList").innerHTML = "";
    GROUPS.forEach((g, gi) => {
      const v = gv(g, y), vc = gv(g, c), ch = (v / vc - 1) * 100;
      const r = document.createElement("button"); r.type = "button"; r.className = "kk-row"; r.setAttribute("aria-pressed", String(focus === gi));
      r.innerHTML = `<span class="sw" style="background:${g.c}"></span><span class="nm">${g.k}<small>${g.d}・1万円のうち約${yen(shares[gi] * 100)}円</small></span><span class="amt">${yen(v)}円</span><span class="ch ${ch >= 0 ? "up" : "down"}">${sgn(ch)}</span>`;
      r.addEventListener("click", () => { focus = focus === gi ? -1 : gi; renderKakei(); });
      $("kkList").appendChild(r);
    });
  }
  renderKakei();

  // 家計簿からわかる変化（数字はすべてデータから計算）
  function spark(cat, a, b) {
    const ys = []; for (let y = KY0; y <= KY1; y++) ys.push(y);
    const v = ys.map((y) => kv(cat, y)), lo = Math.min(...v), hi = Math.max(...v);
    const X = (i) => 4 + (i / (ys.length - 1)) * 292, Y = (x) => 40 - ((x - lo) / (hi - lo || 1)) * 34;
    const d = v.map((x, i) => `${i ? "L" : "M"}${X(i).toFixed(1)} ${Y(x).toFixed(1)}`).join(" ");
    const ia = a - KY0, ib = b - KY0;
    return `<svg viewBox="0 0 300 46" preserveAspectRatio="none" aria-hidden="true"><rect x="${X(ia)}" y="0" width="${Math.max(2, X(ib) - X(ia))}" height="46" fill="var(--ruler)" opacity=".25"/><path d="${d}" fill="none" stroke="var(--cool)" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`;
  }
  const peakYear = (cat) => { let best = KY0; for (let y = KY0; y <= KY1; y++) if (K[cat][y - KY0] > K[cat][best - KY0]) best = y; return best; };
  const pk = peakYear("通信");
  const STORIES = [
    { cat: "食料", a: 2015, b: KY1, t: "食べ物に使うお金が増えた", d: (x) => `月${yen(kv("食料", 2015))}円 → ${yen(kv("食料", KY1))}円。物の値段が上がり、食べ物は節約しにくいので、食費がふくらんでいます。` },
    { cat: "通信", a: pk, b: KY1, t: "スマホ代は、ピークから下がった", d: () => `いちばん多かったのは${pk}年の月${yen(kv("通信", pk))}円。${KY1}年は月${yen(kv("通信", KY1))}円です。2021年の携帯電話の値下げが大きく関係しています。` },
    { cat: "外食", a: 2019, b: 2020, t: "コロナで外食が急にへった", d: () => `2019年の月${yen(kv("外食", 2019))}円から、2020年は月${yen(kv("外食", 2020))}円へ（${sgn((kv("外食", 2020) / kv("外食", 2019) - 1) * 100)}）。${KY1}年は月${yen(kv("外食", KY1))}円で、${kv("外食", KY1) > kv("外食", 2019) ? "コロナの前より多くなりました" : "コロナの前の近くまでもどりました"}。` },
    { cat: "こづかい(使途不明)", a: KY0, b: KY1, t: "「使い道がわからないこづかい」が約4分の1に", d: () => `${KY0}年の月${yen(kv("こづかい(使途不明)", KY0))}円から、${KY1}年は月${yen(kv("こづかい(使途不明)", KY1))}円。キャッシュレス決済が広がり、何に使ったか記録しやすくなったことも理由と考えられます。` },
    { cat: "被服及び履物", a: KY0, b: KY1, t: "服とくつのお金は、約4割へった", d: () => `${KY0}年の月${yen(kv("被服及び履物", KY0))}円から、${KY1}年は月${yen(kv("被服及び履物", KY1))}円。安い服のお店がふえたことなどが関係しています。` },
    { cat: "菓子類", a: 2015, b: KY1, t: "おかしは過去最高", d: () => `月${yen(kv("菓子類", 2015))}円（2015年）→ ${yen(kv("菓子類", KY1))}円（${KY1}年）。チョコなどの値上がりもあり、${peakYear("菓子類")}年がこの26年でいちばん多くなりました。` },
  ];
  $("kkStories").innerHTML = STORIES.map((s) => {
    const ch = (kv(s.cat, s.b) / kv(s.cat, s.a) - 1) * 100;
    return `<div class="event"><span class="yr">${s.a}→${s.b}年 ${sgn(ch)}</span><b>${s.t}</b>${spark(s.cat, s.a, s.b)}<p>${s.d()}</p></div>`;
  }).join("");

  // ===== 今日の発見 =====
  const CITY = D.CITY, PW = D.PREF_WAGE, item = (id) => D.ITEMS.find((i) => i.id === id);
  const mm = (arr) => { let lo = -1, hi = -1; arr.forEach((v, i) => { if (v == null) return; if (lo < 0 || v < arr[lo]) lo = i; if (hi < 0 || v > arr[hi]) hi = i; }); return [lo, hi]; };
  const [oLo, oHi] = mm(CITY.onigiri);
  const [wLo, wHi] = mm(PW);
  const rice = item("rice");
  const FACTS = [
    `お米5kgは、2020年の<b>${yen(D.TREND.rice[1])}円</b>から2025年は<b>${yen(rice.p25)}円</b>に。5年で2倍以上になりました（東京23区）。`,
    `県庁所在地でおにぎりがいちばん安いのは${esc(D.PREFS[oLo].city)}の<b>${CITY.onigiri[oLo]}円</b>、高いのは${esc(D.PREFS[oHi].city)}の<b>${CITY.onigiri[oHi]}円</b>（2025年平均）。`,
    `2人以上で暮らす家族が使うお金は、平均で月<b>${yen(kv("消費支出", KY1))}円</b>。1日あたり約<b>${yen(kv("消費支出", KY1) / 30.4)}円</b>です。`,
    `2026年度の最低賃金は、${esc(D.OK.prefName(wHi))}の<b>${yen(PW[wHi])}円</b>から${esc(D.OK.prefName(wLo))}の<b>${yen(PW[wLo])}円</b>まで。差は<b>${PW[wHi] - PW[wLo]}円</b>です。`,
    `1990年の物価は今の約<b>${Math.round(cpiAt("総合", 1990))}%</b>。今の1,000円の買い物は、1990年なら約<b>${yen(1000 * cpiAt("総合", 1990) / 100)}円</b>でした。`,
    `ランドセルは2010年の<b>${yen(D.TREND.randoseru[0])}円</b>から2025年は<b>${yen(item("randoseru").p25)}円</b>に（東京23区）。`,
    `2025年のエンゲル係数（食べ物にお金を使う割合）は<b>${D.ENGEL_OFFICIAL.value}%</b>。${D.ENGEL_OFFICIAL.note}です。`,
    `消せるボールペンは2015年<b>${yen(item("pen").p15)}円</b>、2025年<b>${yen(item("pen").p25)}円</b>。10年間、ほとんど値上がりしていません。`,
  ];
  let fi = Math.floor(Math.random() * FACTS.length), auto = !matchMedia("(prefers-reduced-motion: reduce)").matches, timer;
  function showFact() { $("factText").innerHTML = FACTS[fi]; $("factNo").textContent = `${fi + 1}/${FACTS.length}`; }
  function step(d) { fi = (fi + d + FACTS.length) % FACTS.length; showFact(); }
  $("factPrev").addEventListener("click", () => { auto = false; clearInterval(timer); step(-1); });
  $("factNext").addEventListener("click", () => { auto = false; clearInterval(timer); step(1); });
  showFact();
  if (auto) timer = setInterval(() => { if (!document.hidden) step(1); }, 8000);

  // ===== スタンプラリー =====
  const CH = [["money", "お金ってなに？"], ["hours", "はたらく時間"], ["map", "日本地図"], ["rank", "ランキング"], ["time", "タイムマシン"], ["race", "給料と物価"], ["save", "貯金"], ["fx", "円安・円高"], ["kakei", "家族の1万円"], ["school", "学校のお金"], ["pay", "手取り"], ["agewage", "年れいと給料"], ["big", "1人あたり"], ["tax", "消費税"], ["diary", "おこづかい帳"], ["quiz", "クイズ"], ["words", "ことば"]];
  let got = new Set(store.get("stamps", []));
  const rot = (i) => [-8, 6, -4, 9, -11, 5, -6, 10, -3, 7, -9, 4, -7, 8, -5, 6, -10][i];
  function renderStamps(popId) {
    $("stampGrid").innerHTML = CH.map(([id, t], i) => `<a class="stamp${got.has(id) ? " got" : ""}${popId === id ? " pop" : ""}" href="#${id}" style="--rot:${rot(i)}deg"><span><span class="n">${String(i + 1).padStart(2, "0")}</span>${got.has(id) ? t : "まだ"}</span></a>`).join("");
    $("stampCount").textContent = `${got.size} / ${CH.length}`;
    $("stampPillN").textContent = `${got.size}/${CH.length}`;
    if (got.size === CH.length) {
      const day = store.get("certDay", null) || (() => { const d = new Date(); const s = `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`; store.set("certDay", s); return s; })();
      $("cert").innerHTML = `<div class="cert"><span class="hint">にんていしょう</span><span class="t">物差しはかせ</span>
        <input id="certName" type="text" maxlength="20" placeholder="なまえを書こう" aria-label="なまえ" value="${esc(store.get("certName", ""))}">
        <p>あなたは「おかねの物差し」の${CH.length}の章をすべて読み、<br>お金を自分の生活の単位ではかる力を身につけました。</p>
        <span class="seal">物差し<br>認定</span><span class="hint">${day}・スクリーンショットで残しておこう</span></div>`;
      $("certName").addEventListener("input", (e) => store.set("certName", e.target.value));
    } else {
      $("cert").innerHTML = `<p class="hint">あと${CH.length - got.size}こ。スタンプを押すと、その章にとべます。</p>`;
    }
  }
  renderStamps();
  if ("IntersectionObserver" in window) {
    const timers = {};
    const io = new IntersectionObserver((ents) => ents.forEach((e) => {
      const id = e.target.id;
      if (got.has(id)) return;
      if (e.isIntersecting) timers[id] = setTimeout(() => { got.add(id); store.set("stamps", [...got]); renderStamps(id); document.dispatchEvent(new CustomEvent("okane:stamp")); }, 1500);
      else clearTimeout(timers[id]);
    }), { threshold: 0.25 });
    CH.forEach(([id]) => { const el = $(id); if (el) io.observe(el); });
  }
})();

;

/* ===== okane-school.js ===== */
// おかねの物差し：学校に通うのに、1年でいくらかかる？（子供の学習費調査）
(() => {
  const D = window, { $, yen, esc, store, hmText } = D.OK;
  const S = D.SCHOOL, byId = (id) => S.find((s) => s.id === id);
  const ORDER = ["kg-pub", "kg-pri", "es-pub", "es-pri", "jh-pub", "jh-pri", "hs-pub", "hs-pri"];
  const PARTS = [["edu", "学校教育費", "var(--seg1)", "授業料・教材・遠足や修学旅行・制服・通学など"], ["lunch", "給食費", "var(--seg6)", "学校の給食"], ["out", "塾・習いごとなど", "var(--seg3)", "塾・家庭教師・参考書・スポーツや音楽の習いごと"]];
  let level = store.get("scLevel", "es"), type = store.get("scType", "pub");
  $("scLevel").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; level = b.dataset.v; store.set("scLevel", level); render(); });
  $("scType").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; type = b.dataset.v; store.set("scType", type); render(); });
  const K = D.KAKEI, famYear = K["消費支出"][K["消費支出"].length - 1];

  function render() {
    [...$("scLevel").children].forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.v === level)));
    [...$("scType").children].forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.v === type)));
    const s = byId(`${level}-${type}`), w = D.OK.wage();
    $("scLabel").textContent = `${s.t}に1年間通うと（子ども1人あたりの平均）`;
    $("scValue").innerHTML = `${yen(s.total)}<span class="u">円</span>`;
    const hrs = s.total / w;
    $("scSub").innerHTML = `1か月あたり約<b>${yen(s.total / 12)}円</b>。${s.y}年間通うと約<b>${Math.round(s.total * s.y / 1e4).toLocaleString()}万円</b>です。最低賃金（時給${yen(w)}円）ではたらくと約${Math.round(hrs).toLocaleString()}時間ぶん、家族が1年に使うお金（家計調査）の約${Math.round(s.total / famYear * 100)}%にあたります。`;
    $("scBar").innerHTML = PARTS.filter(([k]) => s[k] > 0).map(([k, t, c]) => `<div style="flex:${s[k]};background:${c}" title="${t} ${yen(s[k])}円"></div>`).join("");
    $("scList").innerHTML = PARTS.map(([k, t, c, d]) => `<div class="ded"><span class="sw" style="background:${c}"></span><div><div class="name">${t}</div><div class="what">${d}</div></div><span class="amt">${s[k] > 0 ? yen(s[k]) + "円（" + Math.round(s[k] / s.total * 100) + "%）" : "調査なし"}</span></div>`).join("");
    drawBars(s.id);
  }
  function drawBars(sel) {
    const max = Math.max(...S.map((s) => s.total));
    $("scBars").innerHTML = ORDER.map((id) => { const s = byId(id); return `<button type="button" class="sc-row${id === sel ? " on" : ""}" data-id="${id}"><span class="nm">${esc(s.t.replace("（全日制）", ""))}</span><span class="tr" style="width:${s.total / max * 100}%">${PARTS.filter(([k]) => s[k] > 0).map(([k, , c]) => `<i style="flex:${s[k]};background:${c}"></i>`).join("")}</span><span class="v">${(s.total / 1e4).toFixed(1)}万円</span></button>`; }).join("");
    $("scBars").querySelectorAll(".sc-row").forEach((b) => b.addEventListener("click", () => { [level, type] = b.dataset.id.split("-"); store.set("scLevel", level); store.set("scType", type); render(); }));
    // 幼稚園3年＋小学校6年＋中学校3年＋高校3年の合計
    const sum = (t) => ["kg", "es", "jh", "hs"].reduce((a, l) => { const s = byId(`${l}-${t}`); return a + s.total * s.y; }, 0);
    $("scTotal").innerHTML = `幼稚園から高校まで15年間の合計は、<b>ぜんぶ公立で約${Math.round(sum("pub") / 1e4).toLocaleString()}万円</b>、<b>ぜんぶ私立で約${Math.round(sum("pri") / 1e4).toLocaleString()}万円</b>（この調査の平均から計算）。公立小学校では、学校に払うお金より、塾や習いごとのお金のほうが多くなっています。`;
  }
  D.OK.onUnit(render);
  render();
})();

;

/* ===== okane-big.js ===== */
// おかねの物差し：ニュースの大きな数字を1人あたりに・結果をコピー
(() => {
  const D = window, { $, yen, esc, store, hmText } = D.OK;
  const SITE = "https://azakeiten.github.io/okane-monosashi/";
  const POP = D.POPULATION.value;
  // 長い時間は分を出さない（例：約847時間）
  const hrsText = (h) => h >= 100 ? `約${Math.round(h).toLocaleString()}時間` : hmText(h);
  const popText = `${Math.floor(POP / 1e8)}億${Math.round((POP % 1e8) / 1e4).toLocaleString()}万人`;

  // ===== 結果をコピー（どの章からも使える） =====
  D.OK.copy = (text, statusEl) => {
    const done = (ok) => { if (statusEl) { statusEl.textContent = ok ? "コピーしました。LINEやメモに貼りつけて送れます。" : "コピーできませんでした。下の文を長押しして選んでください。"; } };
    const fallback = () => { if (statusEl) { statusEl.innerHTML = `<span style="user-select:all;display:block;margin-top:6px">${esc(text)}</span>`; } };
    try {
      navigator.clipboard.writeText(text).then(() => done(true), () => { done(false); fallback(); });
    } catch (e) { done(false); fallback(); }
  };

  // 円の金額を、読みやすい日本語に（例：9,333,225 → 約933万円、1.2兆 → 約1.2兆円）
  function jp(v) {
    if (v >= 1e12) return `約${(v / 1e12).toLocaleString("ja-JP", { maximumFractionDigits: 1 })}兆円`;
    if (v >= 1e8) return `約${(v / 1e8).toLocaleString("ja-JP", { maximumFractionDigits: 1 })}億円`;
    if (v >= 1e4) return `約${(v / 1e4).toLocaleString("ja-JP", { maximumFractionDigits: v >= 1e6 ? 0 : 1 })}万円`;
    return `約${yen(v)}円`;
  }
  // 1万円札の高さ（100万円で約1cm）→ メートル
  const heightM = (v) => v / 1e8;
  function len(m) { return m >= 1000 ? `約${(m / 1000).toLocaleString("ja-JP", { maximumFractionDigits: m >= 1e5 ? 0 : 1 })}km` : m >= 1 ? `約${m.toLocaleString("ja-JP", { maximumFractionDigits: 1 })}m` : `約${(m * 100).toLocaleString("ja-JP", { maximumFractionDigits: 1 })}cm`; }

  let sel = store.get("big", "budget");
  const seg = $("bigSeg"), input = $("bigIn"), unit = $("bigUnit");
  D.BIG.forEach((b) => {
    const btn = document.createElement("button");
    btn.type = "button"; btn.dataset.id = b.id; btn.innerHTML = `${esc(b.name)}<span class="num">${b.short}</span>`;
    btn.addEventListener("click", () => { sel = b.id; store.set("big", sel); input.value = b.value / 1e12; unit.value = "1e12"; render(); });
    seg.appendChild(btn);
  });
  const cur = D.BIG.find((b) => b.id === sel) || D.BIG[0];
  input.value = +(cur.value / 1e12).toFixed(4);
  [input, unit].forEach((el) => el.addEventListener("input", () => { sel = "custom"; render(); }));

  function value() { const v = parseFloat(input.value); return isFinite(v) && v > 0 ? v * +unit.value : 0; }
  function render() {
    const v = value(), b = D.BIG.find((x) => x.id === sel), w = D.OK.wage();
    [...seg.children].forEach((c) => c.setAttribute("aria-pressed", String(c.dataset.id === sel)));
    $("bigNote").textContent = b ? `${b.note}。` : "自分で入れた金額です。";
    const per = v / POP;
    $("bigPer").innerHTML = v ? `${jp(per).replace("約", "")}` : "—";
    $("bigPerSub").innerHTML = v ? `${jp(v).replace("約", "")} ÷ 日本の人口 ${popText}。` : "金額を入れてください。";
    const hrs = per / w;
    const cells = [
      { k: "4人家族あたり", v: jp(per * 4), s: "1人あたり × 4人" },
      { k: `あなたの時給（${yen(w)}円）だと`, v: hrsText(hrs), s: hrs >= 8 ? `1日8時間で約${Math.round(hrs / 8).toLocaleString()}日ぶん` : "1人ぶんをかせぐ時間" },
    ];
    if (b && b.kind === "stock") cells.push({ k: "国の予算の何年分？", v: `約${(v / D.BIG[0].value).toFixed(1)}年分`, s: "一般会計122.3兆円の何倍か" });
    else cells.push({ k: "1人・1日あたり", v: jp(per / 365), s: "1年を365日でわると" });
    cells.push({ k: "1万円札を積み上げると", v: len(heightM(v)), s: "100万円の札たば ≒ 約1cm" });
    $("bigGrid").innerHTML = cells.map((c) => `<div><span class="k">${esc(c.k)}</span><span class="v">${esc(c.v)}</span><span class="s">${esc(c.s)}</span></div>`).join("");
    $("bigCopied").textContent = "";
    drawStack(v, b ? b.name : "入れた金額");
  }
  $("bigCopy").addEventListener("click", () => {
    const v = value(); if (!v) return;
    const b = D.BIG.find((x) => x.id === sel), name = b ? `${b.name}${b.short}` : jp(v);
    const per = v / POP, hrs = per / D.OK.wage();
    D.OK.copy(`${name}は、日本に住む1人あたり${jp(per)}。時給${yen(D.OK.wage())}円ではたらくと${hrsText(hrs)}ぶんです。\n#おかねの物差し ${SITE}#big`, $("bigCopied"));
  });

  // 高さくらべ（横棒）。ほかのものと一緒に並べる
  function drawStack(v, name) {
    const items = [
      { n: "富士山", m: 3776, ref: 1 },
      { n: "国際宇宙ステーションまで", m: 400000, ref: 1 },
      { n: "国の予算 122.3兆円", m: heightM(D.BIG[0].value) },
      { n: "日本のGDP 663.5兆円", m: heightM(D.BIG[4].value) },
      { n: "国の借金 1,145兆円", m: heightM(D.BIG[3].value) },
      { n: "地球の直径", m: 12742000, ref: 1 },
    ];
    const mine = heightM(v);
    if (v && !D.BIG.some((x) => Math.abs(x.value - v) < 1 && [0, 3, 4].includes(D.BIG.indexOf(x)))) items.push({ n: name.length > 14 ? "入れた金額" : name, m: mine, me: 1 });
    items.sort((a, b) => a.m - b.m);
    const W = 760, rowH = 32, top = 8, L = 200, R = 120, H = top + items.length * rowH + 8;
    const max = Math.max(...items.map((i) => i.m));
    const X = (m) => Math.max(3, (m / max) * (W - L - R));
    let s = "";
    items.forEach((it, i) => {
      const y = top + i * rowH, isSel = it.me || (!it.ref && Math.abs(it.m - mine) < 1e-6);
      const fill = it.ref ? "var(--soft)" : isSel ? "var(--ruler)" : "var(--cool)";
      s += `<text class="lb" x="${L - 10}" y="${y + 20}" text-anchor="end">${esc(it.n)}</text>`;
      s += `<rect x="${L}" y="${y + 6}" width="${X(it.m)}" height="20" rx="4" fill="${fill}" ${it.ref ? 'stroke="var(--line)"' : ""}/>`;
      s += `<text class="vl" x="${L + X(it.m) + 8}" y="${y + 20}">${len(it.m)}</text>`;
    });
    const svg = $("stackChart"); svg.setAttribute("viewBox", `0 0 ${W} ${H}`); svg.innerHTML = s;
    const debt = heightM(D.BIG[3].value);
    $("stackNote").textContent = `国の借金1,145兆円を1万円札で積み上げると${len(debt)}。地球の直径（約12,742km）の約${Math.round(debt / 12742000 * 100)}%、富士山の約${Math.round(debt / 3776).toLocaleString()}倍の高さです。`;
  }

  // 予算の使い道
  const bud = D.BIG[0].value, soc = D.BIG[1].value, dp = D.BIG[2].value, oth = bud - soc - dp;
  $("budgetBar").innerHTML = [[soc, "var(--seg1)", "社会保障"], [dp, "var(--seg3)", "国債費"], [oth, "var(--muted)", "それ以外"]].map(([x, c, t]) => `<div style="flex:${x};background:${c}" title="${t} ${jp(x)}"></div>`).join("");
  $("budgetText").innerHTML = `社会保障が<b>${Math.round(soc / bud * 100)}%</b>（1人あたり${jp(soc / POP)}）、借金の返済と利息が<b>${Math.round(dp / bud * 100)}%</b>（1人あたり${jp(dp / POP)}）。残りの<b>${Math.round(oth / bud * 100)}%</b>で、地方へのお金、公共事業、教育、防衛などをまかなっています。`;

  // 1兆の大きさ
  const yrs = 1e12 / (60 * 60 * 24 * 365);
  $("trillionFact").textContent = `1秒に1円ずつ数えても、1兆円を数え終わるには約${Math.round(yrs).toLocaleString()}年かかります。今から約${Math.round(yrs).toLocaleString()}年前は、まだ氷河期のころです。`;

  // ホームの換算機にもコピーボタン
  const conv = document.querySelector(".converter");
  if (conv) {
    const row = document.createElement("div"); row.className = "share-row conv-share";
    row.innerHTML = `<button type="button" class="btn ghost" id="heroCopy">結果をコピーする</button><span class="hint" id="heroCopied" aria-live="polite"></span>`;
    conv.appendChild(row);
    $("heroCopy").addEventListener("click", () => {
      const p = parseFloat($("heroPrice").value) || 0; if (!p) return;
      const w = D.OK.wage();
      D.OK.copy(`${yen(p)}円は、時給${yen(w)}円ではたらくと${hmText(p / w)}ぶん。おこづかい月${yen(D.OK.allow())}円なら${(p / D.OK.allow()).toFixed(1)}か月ぶんです。\n#おかねの物差し ${SITE}`, $("heroCopied"));
    });
    $("heroPrice").addEventListener("input", () => { $("heroCopied").textContent = ""; });
  }

  D.OK.onUnit(render);
  render();
})();

;

/* ===== okane-me.js ===== */
// おかねの物差し：あなたの物差しカード・自由研究ワークシート
(() => {
  const D = window, { $, yen, esc, store, hmText, cpiAt } = D.OK;
  const SITE = "https://azakeiten.github.io/okane-monosashi/";
  const item = (id) => D.ITEMS.find((i) => i.id === id);

  // ===== あなたの物差しカード =====
  const mcPref = $("mcPref"), mcBirth = $("mcBirth"), mcName = $("mcName");
  D.PREFS.forEach((p, i) => { const o = document.createElement("option"); o.value = i; o.textContent = `${D.OK.prefName(i)}（${yen(D.PREF_WAGE[i])}円）`; mcPref.appendChild(o); });
  mcBirth.value = store.get("birth", ""); mcName.value = store.get("cardName", "");
  mcPref.addEventListener("change", () => {
    if (mcPref.value !== "") D.OK.setPref(+mcPref.value);
    else { $("prefSel").value = ""; $("wageIn").value = 1177; $("wageIn").dispatchEvent(new Event("input")); }
  });
  mcBirth.addEventListener("input", () => { store.set("birth", mcBirth.value); renderAll(); });
  mcName.addEventListener("input", () => { store.set("cardName", mcName.value); renderCard(); });

  const birth = () => { const y = parseInt(mcBirth.value, 10); return y >= D.CPI_FIRST_YEAR && y <= 2025 ? y : null; };
  // 選んだ県の県庁所在地の値段（なければ東京23区）
  function cityPrice(id) { const p = D.OK.pref(); const v = p >= 0 && D.CITY[id] ? D.CITY[id][p] : null; return v != null ? { v, where: D.PREFS[p].city } : { v: item(id).p25, where: "東京23区" }; }
  function facts() {
    const w = D.OK.wage(), p = D.OK.pref(), y = birth();
    const oni = cityPrice("onigiri"), rice = cityPrice("rice");
    const per = D.BIG[0].value / D.POPULATION.value;
    const r = {
      wage: { k: "あなたの時給", v: `${yen(w)}<small>円</small>`, s: p >= 0 && D.PREF_WAGE[p] === w ? `${D.OK.prefName(p)}の最低賃金（2026年度）` : w === 1177 ? "全国平均の最低賃金（2026年度）" : "自分で入れた時給", t: `時給：${yen(w)}円` },
      oni: { k: "おにぎり1個を買うには", v: hmText(oni.v / w).replace("約", ""), s: `${esc(oni.where)}の値段 ${yen(oni.v)}円（2025年平均）`, t: `おにぎり1個（${oni.where}・${yen(oni.v)}円）：${hmText(oni.v / w)}` },
      rice: { k: "お米5kgを買うには", v: hmText(rice.v / w).replace("約", ""), s: `${esc(rice.where)}の値段 ${yen(rice.v)}円（2025年平均）`, t: `お米5kg（${rice.where}・${yen(rice.v)}円）：${hmText(rice.v / w)}` },
      budget: { k: "国の予算、1人あたり", v: `${(per / 1e4).toFixed(1)}<small>万円</small>`, s: `時給${yen(w)}円で約${Math.round(per / w).toLocaleString()}時間ぶん`, t: `国の予算の1人あたり：約${(per / 1e4).toFixed(1)}万円（約${Math.round(per / w).toLocaleString()}時間ぶん）` },
    };
    if (y) {
      const now = 1000 * 100 / cpiAt("総合", y), up = (100 / cpiAt("総合", y) - 1) * 100;
      r.birth = { k: `生まれた${y}年の1,000円の買い物`, v: `${yen(now)}<small>円</small>`, s: `今はこれくらいかかる（物価は${up >= 0 ? "+" : ""}${up.toFixed(1)}%）`, t: `${y}年の1,000円の買い物は、今は約${yen(now)}円（物価${up >= 0 ? "+" : ""}${up.toFixed(1)}%）` };
      if (D.MINWAGE[y]) r.mw = { k: `${y}年度の最低賃金（全国平均）`, v: `${yen(D.MINWAGE[y])}<small>円</small>`, s: `今は${yen(D.MINWAGE[2026])}円。${(D.MINWAGE[2026] / D.MINWAGE[y]).toFixed(2)}倍になった`, t: `${y}年度の最低賃金：${yen(D.MINWAGE[y])}円 → 2026年度は${yen(D.MINWAGE[2026])}円` };
    }
    return r;
  }
  function renderCard() {
    const f = facts(), p = D.OK.pref(), y = birth(), name = mcName.value.trim();
    mcPref.value = p >= 0 ? String(p) : "";
    let rows = [f.wage, f.oni, f.rice, f.birth, f.mw, f.budget].filter(Boolean);
    if (rows.length % 2) rows = rows.slice(0, -1); // 2列できれいにならぶよう、偶数にする
    $("mcCard").innerHTML = `<div class="mc-top"><span class="mc-name">${esc(name || "あなた")}の物差しカード</span><span class="mc-sub">${p >= 0 ? esc(D.OK.prefName(p)) : "全国"}${y ? `・${y}年生まれ` : ""}</span></div>
      <div class="mc-rows">${rows.map((r) => `<div class="mc-row"><span class="k">${r.k}</span><span class="v">${r.v}</span><span class="s">${r.s}</span></div>`).join("")}</div>
      ${y ? "" : '<p class="mc-empty">生まれた年を入れると、「生まれた年の1,000円は今いくら？」も出ます。</p>'}`;
    $("mcCopied").textContent = "";
  }
  $("mcCopy").addEventListener("click", () => {
    const f = facts(), name = mcName.value.trim();
    const lines = [f.wage, f.oni, f.rice, f.birth, f.mw, f.budget].filter(Boolean).map((r) => "・" + r.t);
    D.OK.copy(`【${name || "わたし"}の物差しカード】\n${lines.join("\n")}\n#おかねの物差し ${SITE}`, $("mcCopied"));
  });

  // ===== カードを画像にする（1080×1350）。GitHub版のふつうのページでだけ使える =====
  function cardRows() { const f = facts(); let rows = [f.wage, f.oni, f.rice, f.birth, f.mw, f.budget].filter(Boolean); if (rows.length % 2) rows = rows.slice(0, -1); return rows; }
  const strip = (h) => String(h).replace(/<[^>]+>/g, "");
  async function drawCard() {
    try { await document.fonts.ready; } catch (e) {}
    const W = 1080, H = 1350, c = document.createElement("canvas"); c.width = W; c.height = H;
    const g = c.getContext("2d"), NAVY = "#191f45", PAPER = "#f2f3f7", YEL = "#f4b400", DISP = '"Dela Gothic One", "Hiragino Sans", "Yu Gothic", sans-serif', BODY = '"Zen Kaku Gothic New", "Hiragino Sans", "Yu Gothic", sans-serif', NUM = '"DM Mono", monospace';
    g.fillStyle = NAVY; g.fillRect(0, 0, W, H);
    // 上：ロゴと名前
    g.fillStyle = YEL; g.fillRect(72, 72, 64, 64);
    g.fillStyle = NAVY; g.font = `40px ${DISP}`; g.textBaseline = "middle"; g.textAlign = "center"; g.fillText("円", 104, 106);
    g.textAlign = "left"; g.fillStyle = PAPER; g.font = `34px ${DISP}`; g.fillText("おかねの物差し", 160, 106);
    const p = D.OK.pref(), y = birth(), name = mcName.value.trim() || "あなた";
    g.font = `66px ${DISP}`; g.fillStyle = PAPER; g.textBaseline = "alphabetic";
    g.fillText(`${name}の物差しカード`.slice(0, 15), 72, 250);
    g.font = `32px ${BODY}`; g.fillStyle = "rgba(242,243,247,.75)";
    g.fillText(`${p >= 0 ? D.OK.prefName(p) : "全国"}${y ? `・${y}年生まれ` : ""}`, 72, 306);
    // まん中：数字のマス（2列）
    const rows = cardRows(), colW = (W - 72 * 2 - 24) / 2, rowH = 230, top = 360;
    rows.forEach((r, i) => {
      const x = 72 + (i % 2) * (colW + 24), yy = top + Math.floor(i / 2) * (rowH + 24);
      g.fillStyle = "rgba(242,243,247,.09)"; roundRect(g, x, yy, colW, rowH, 24); g.fill();
      g.fillStyle = "rgba(242,243,247,.75)"; g.font = `26px ${BODY}`; g.fillText(strip(r.k).slice(0, 18), x + 28, yy + 56);
      const v = String(r.v).replace(/<small>(.*?)<\/small>/, "\u0001$1").split("\u0001");
      g.fillStyle = YEL; g.font = `64px ${DISP}`; g.fillText(strip(v[0]), x + 28, yy + 140);
      if (v[1]) { const wv = g.measureText(strip(v[0])).width; g.fillStyle = PAPER; g.font = `32px ${DISP}`; g.fillText(strip(v[1]), x + 34 + wv, yy + 140); }
      g.fillStyle = "rgba(242,243,247,.7)"; g.font = `22px ${BODY}`; wrap(g, strip(r.s), x + 28, yy + 186, colW - 56, 30, 2);
    });
    // 下：物差しの帯とURL
    g.fillStyle = YEL; g.fillRect(0, H - 150, W, 150);
    g.strokeStyle = NAVY; g.lineWidth = 3;
    for (let i = 0; i <= 54; i++) { const x = 30 + i * 19; const h = i % 10 === 0 ? 50 : i % 5 === 0 ? 34 : 20; g.beginPath(); g.moveTo(x, H - 150); g.lineTo(x, H - 150 + h); g.stroke(); }
    g.fillStyle = NAVY; g.font = `30px ${NUM}`; g.fillText("azakeiten.github.io/okane-monosashi", 72, H - 44);
    g.font = `24px ${BODY}`; g.textAlign = "right"; g.fillText("数字は国の統計から", W - 72, H - 44);
    return new Promise((ok) => c.toBlob((b) => ok(b), "image/png"));
  }
  function roundRect(g, x, y, w, h, r) { g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r); g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath(); }
  function wrap(g, text, x, y, maxW, lh, maxLines) { let line = "", n = 0; for (const ch of text) { if (g.measureText(line + ch).width > maxW) { g.fillText(line, x, y + n * lh); line = ch; if (++n >= maxLines) return; } else line += ch; } if (line) g.fillText(line, x, y + n * lh); }
  const framedPage = (() => { try { return window.self !== window.top; } catch (e) { return true; } })();
  if (framedPage) {
    $("mcImgNote").innerHTML = `画像で保存するときは、<a href="${SITE}#mycard" target="_blank" rel="noopener">GitHub版のサイト</a>を開いてください。`;
  } else {
    $("mcSave").hidden = false;
    $("mcSave").addEventListener("click", async () => {
      const b = await drawCard(); if (!b) return;
      const a = document.createElement("a"); a.href = URL.createObjectURL(b); a.download = "monosashi-card.png";
      document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 4000);
      $("mcCopied").textContent = "画像を保存しました。";
    });
    // スマホで「送る」（使える端末だけ）
    try {
      const test = new File([new Blob(["x"])], "t.png", { type: "image/png" });
      if (navigator.canShare && navigator.canShare({ files: [test] })) {
        $("mcShare").hidden = false;
        $("mcShare").addEventListener("click", async () => {
          const b = await drawCard(); if (!b) return;
          try { await navigator.share({ files: [new File([b], "monosashi-card.png", { type: "image/png" })], title: "わたしの物差しカード", text: `#おかねの物差し ${SITE}` }); } catch (e) {}
        });
      }
    } catch (e) {}
  }
  D.OK.drawCard = drawCard;

  // ===== 自由研究ワークシート =====
  // 章の番号と見出し（ページから読むので、章がふえても番号がずれない）
  function chLabel(id) { const s = $(id); if (!s) return id; const n = s.querySelector(".rule-band span"), h = s.querySelector(".ch-head h2"); const c = h ? h.cloneNode(true) : null; if (c) c.querySelectorAll("rt").forEach((r) => r.remove()); return `${n ? n.textContent + " " : ""}${c ? c.textContent.trim() : id}`; }
  let showAns = false;
  function renderSheet() {
    const f = facts(), y = birth(), r = D.OK.calcPay(262300, 1);
    const top = D.ITEMS.map((i) => ({ ...i, c: (i.p25 / i.p15 - 1) * 100 })).sort((a, b) => b.c - a.c)[0];
    const p = D.OK.pref();
    const QS = [
      { q: "あなたの住んでいる都道府県の、2026年度の最低賃金はいくら？", u: "円", a: p >= 0 ? `${yen(D.PREF_WAGE[p])}（${D.OK.prefName(p)}）` : "（都道府県をえらぶと表示）", h: "map", hn: "02 日本地図" },
      { q: "おにぎり1個を買うには、あなたの県の最低賃金で何分はたらく？", u: "分", a: f.oni.t.split("：")[1].replace("約", "").replace("分", ""), h: "map", hn: "02 日本地図" },
      { q: "2015年から2025年までに、いちばん値上がりした品物は何？ 何％上がった？", u: "", a: `${top.name}（+${Math.round(top.c)}%）`, h: "rank", hn: "03 値上がりランキング" },
      { q: "あなたが生まれた年に、今の1,000円の買い物はいくらだった？", u: "円", a: y ? `${yen(1000 * cpiAt("総合", y) / 100)}（${y}年）` : "（生まれた年を入れると表示）", h: "time", hn: "04 物価タイムマシン" },
      { q: "国の予算（一般会計）は、日本に住む1人あたりいくら？", u: "円", a: `約${yen(D.BIG[0].value / D.POPULATION.value)}`, h: "big", hn: "09 1人あたりいくら？" },
      { q: "大学卒の初任給（額面）262,300円のとき、手取り（1年目）はおよそいくら？", u: "円", a: `約${yen(r.net)}`, h: "pay", hn: "08 手取りのひみつ" },
      { q: "国の1年のお金を1万円にちぢめると、社会保障に使われるのはいくら？", u: "円", a: D.BUDGET ? yen((D.BUDGET.out.find((x) => x.id === "social").v / D.BUDGET.total) * 10000) : "", h: "big", hn: "12 国の家計簿" },
      { q: "幼稚園から高校まで、ぜんぶ公立に通うと、学校にかかるお金（学習費）は合計いくら？", u: "万円", a: `約${yen(D.SCHOOL.filter((s) => /-pub$/.test(s.id)).reduce((t, s) => t + s.total * s.y, 0) / 1e4)}`, h: "agewage", hn: "11 一生のお金すごろく" },
    ];
    $("sheetQs").innerHTML = QS.map((x) => `<li><span class="qt">${x.q}</span><span class="blank"><i>${showAns ? esc(x.a) : ""}</i>${x.u}</span><span class="qh hint">ヒント：<a href="#${x.h}">${chLabel(x.h)}</a></span></li>`).join("");
  }
  $("sheetFill").addEventListener("click", () => { showAns = !showAns; $("sheetFill").setAttribute("aria-pressed", String(showAns)); $("sheetFill").textContent = showAns ? "答えの例をかくす" : "答えの例を表示する"; renderSheet(); });
  // 印刷は、GitHub版のふつうのページでだけ使える（Claudeのプレビューの中では印刷できない）
  const framed = (() => { try { return window.self !== window.top; } catch (e) { return true; } })();
  if (framed) {
    $("sheetPrint").hidden = true;
    $("sheetNote").innerHTML = `印刷は、<a href="${SITE}#sheet" target="_blank" rel="noopener">GitHub版のサイト</a>で使えます。`;
  } else {
    $("sheetNote").textContent = "A4の紙1〜2枚に、ワークシートだけが印刷されます。";
    $("sheetPrint").addEventListener("click", () => { document.body.classList.add("print-sheet"); window.print(); });
    window.addEventListener("afterprint", () => document.body.classList.remove("print-sheet"));
  }

  function renderAll() { renderCard(); renderSheet(); }
  D.OK.onUnit(renderAll);
  renderAll();
})();

;

/* ===== okane-tax.js ===== */
// おかねの物差し：消費税（レシート）・ほしい物までの貯金計画・数字の動き
(() => {
  const D = window, { $, yen, esc, store, hmText } = D.OK;
  const SITE = "https://azakeiten.github.io/okane-monosashi/";
  const item = (id) => D.ITEMS.find((i) => i.id === id);

  // ===== 10 消費税 =====
  let eat = store.get("taxEat", "in");
  let basket = store.get("basket", { onigiri: 1, choco: 1, burger: 1, notebook: 1 });
  const rateOf = (it) => (it.g === "food" || it.g === "snack") ? 8 : it.g === "eatout" ? (eat === "out" ? 8 : 10) : 10;
  const CHIP_IDS = ["onigiri", "rice", "milk", "chips", "choco", "ice", "water", "burger", "gyudon", "coffee", "notebook", "pen", "battery", "shoes"];
  CHIP_IDS.forEach((id) => {
    const it = item(id); if (!it) return;
    const b = document.createElement("button");
    b.type = "button"; b.className = "chip"; b.dataset.id = id;
    b.innerHTML = `${esc(it.name)}<span class="num">${yen(it.p25)}円</span>`;
    b.addEventListener("click", () => { basket[id] = (basket[id] || 0) + 1; save(); renderReceipt(); });
    $("taxChips").appendChild(b);
  });
  $("taxEat").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; eat = b.dataset.v; store.set("taxEat", eat); renderReceipt(); });
  $("taxClear").addEventListener("click", () => { basket = {}; save(); renderReceipt(); });
  const save = () => store.set("basket", basket);
  const today = (() => { const d = new Date(); return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`; })();

  function renderReceipt() {
    [...$("taxEat").children].forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.v === eat)));
    [...$("taxChips").children].forEach((c) => c.setAttribute("aria-pressed", String(!!basket[c.dataset.id])));
    const lines = Object.entries(basket).filter(([, n]) => n > 0).map(([id, n]) => ({ it: item(id), n })).filter((l) => l.it);
    let html = `<div class="shop">ものさしマート</div><div class="date">${today}　レシート</div><hr>`;
    if (!lines.length) {
      html += `<div class="empty">左の品物を押して、かごに入れよう</div>`;
      $("receipt").innerHTML = html; return;
    }
    const sum = { 8: 0, 10: 0 };
    lines.forEach((l) => {
      const r = rateOf(l.it), amt = l.it.p25 * l.n; sum[r] += amt;
      html += `<div class="ln"><span class="nm">${r === 8 ? "※" : "　"}${esc(l.it.name)}${l.n > 1 ? ` ×${l.n}` : ""}</span><span>¥${yen(amt)}</span></div>`;
    });
    // 値段は消費税こみなので、中にふくまれる税は「値段 × 税率 ÷ (100 + 税率)」（1円未満は切りすて）
    const tax8 = Math.floor(sum[8] * 8 / 108), tax10 = Math.floor(sum[10] * 10 / 110), total = sum[8] + sum[10];
    html += `<hr><div class="ln tot"><span>合計</span><span>¥${yen(total)}</span></div>`;
    if (sum[8]) html += `<div class="ln"><span>（8%対象 ¥${yen(sum[8])}）</span><span class="tax">内税 ¥${yen(tax8)}</span></div>`;
    if (sum[10]) html += `<div class="ln"><span>（10%対象 ¥${yen(sum[10])}）</span><span class="tax">内税 ¥${yen(tax10)}</span></div>`;
    html += `<div class="note">※は軽減税率（8%）の対象です。値段は東京23区の2025年平均。</div>`;
    const t = tax8 + tax10, w = D.OK.wage();
    html += `<div class="big-tax">この買い物で払った消費税は <b>¥${yen(t)}</b>。合計の約${Math.round(t / total * 1000) / 10}%で、あなたの時給（${yen(w)}円）なら${hmText(t / w)}ぶんです。</div>`;
    $("receipt").innerHTML = html;
  }

  const taxAllow = $("taxAllow"), taxMix = $("taxMix");
  taxAllow.value = store.get("allow", 3000);
  [taxAllow, taxMix].forEach((el) => el.addEventListener("input", renderYear));
  function renderYear() {
    const a = Math.max(0, parseFloat(taxAllow.value) || 0), m = +taxMix.value / 100;
    $("taxMixL").textContent = taxMix.value;
    const y8 = a * 12 * m, y10 = a * 12 * (1 - m);
    const t8 = y8 * 8 / 108, t10 = y10 * 10 / 110, tax = t8 + t10;
    const nat = t8 * D.TAXRATE.reducedNational / 8 + t10 * D.TAXRATE.stdNational / 10;
    $("taxYear").innerHTML = `${yen(tax)}<span class="u">円</span>`;
    $("taxYearSub").innerHTML = a ? `1年で使う${yen(a * 12)}円のうち、約<b>${yen(tax)}円</b>が消費税です。そのうち約${yen(nat)}円が国へ、約${yen(tax - nat)}円が都道府県と市区町村へ行きます。` : "金額を入れてください。";
  }

  const R = D.TAXREV, other = R.total - R.consumption - R.income - R.corporate;
  $("taxBar").innerHTML = [[R.consumption, "var(--seg3)", "消費税"], [R.income, "var(--seg1)", "所得税"], [R.corporate, "var(--seg6)", "法人税"], [other, "var(--muted)", "その他"]].map(([v, c, t]) => `<div style="flex:${v};background:${c}" title="${t} ${(v / 1e12).toFixed(1)}兆円"></div>`).join("");
  $("taxBarText").innerHTML = `いちばん多いのは<b>消費税 ${(R.consumption / 1e12).toFixed(1)}兆円</b>（${Math.round(R.consumption / R.total * 100)}%）。次が所得税 ${(R.income / 1e12).toFixed(1)}兆円、法人税 ${(R.corporate / 1e12).toFixed(1)}兆円です。消費税は、日本に住む1人あたり約${Math.round(R.consumption / D.POPULATION.value / 1e4 * 10) / 10}万円になります。`;

  // ===== 06 ほしい物まで、あと何か月？ =====
  const gP = $("goalPrice"), gS = $("goalSave"), gB = $("goalStart"), gI = $("goalInf");
  [["スニーカー", item("shoes").p25], ["自転車", item("bike").p25], ["ゲーム機（例）", 49980]].forEach(([n, v]) => {
    const b = document.createElement("button"); b.type = "button"; b.className = "chip"; b.dataset.v = v;
    b.innerHTML = `${n}<span class="num">${yen(v)}円</span>`;
    b.addEventListener("click", () => { gP.value = v; renderGoal(); });
    $("goalChips").appendChild(b);
  });
  [gP, gS, gB, gI].forEach((el) => el.addEventListener("input", renderGoal));
  function months(P, S, B, inf) {
    for (let n = 0; n <= 600; n++) { if (B + S * n >= P * (inf ? Math.pow(1.02, n / 12) : 1)) return n; }
    return null;
  }
  const ym = (n) => n < 12 ? `${n}か月` : `${Math.floor(n / 12)}年${n % 12 ? n % 12 + "か月" : ""}`;
  function renderGoal() {
    const P = Math.max(1, parseFloat(gP.value) || 1), S = Math.max(0, parseFloat(gS.value) || 0), B = Math.max(0, parseFloat(gB.value) || 0), inf = gI.checked;
    [...$("goalChips").children].forEach((c) => c.setAttribute("aria-pressed", String(+c.dataset.v === P)));
    const a = D.OK.allow();
    $("goalSaveHint").textContent = `おこづかい（月${yen(a)}円）の約${Math.round(S / a * 100)}%`;
    const n = months(P, S, B, inf), n0 = months(P, S, B, false);
    const d = new Date(); if (n != null) d.setMonth(d.getMonth() + n);
    if (n === 0) { $("goalValue").innerHTML = `今すぐ<span class="u">買える！</span>`; $("goalSub").textContent = "今ある貯金で、もう足りています。"; }
    else if (n == null) { $("goalValue").innerHTML = `とどかない`; $("goalSub").textContent = S ? "物の値段が上がる速さに、貯金が追いつきません。毎月ためる金額をふやしてみよう。" : "毎月ためる金額を入れてください。"; }
    else {
      $("goalValue").innerHTML = ym(n).replace(/(\d+)/g, "$1").replace("年", '<span class="u">年</span>').replace("か月", '<span class="u">か月</span>');
      let t = `${d.getFullYear()}年${d.getMonth() + 1}月ごろに買えます（あと${yen(Math.max(0, P - B))}円）。`;
      if (inf && n > n0) t += ` 物の値段が毎年2%上がると、そのころは約${yen(P * Math.pow(1.02, n / 12))}円になるので、上がらない場合より${n - n0}か月長くかかります。`;
      $("goalSub").textContent = t;
    }
    const f = Math.min(1, B / P);
    $("goalTrack").innerHTML = `<div class="fill" style="width:${f * 100}%"></div><div class="lbl"><span>今 ${yen(B)}円（${Math.round(f * 100)}%）</span><span>ゴール ${yen(P)}円</span></div>`;
    $("goalCopied").textContent = "";
  }
  $("goalCopy").addEventListener("click", () => {
    const P = parseFloat(gP.value) || 0, S = parseFloat(gS.value) || 0, B = parseFloat(gB.value) || 0, n = months(P, S, B, gI.checked);
    D.OK.copy(`【貯金計画】${yen(P)}円のほしい物まで、毎月${yen(S)}円ためて${n == null ? "とどかない" : n === 0 ? "今すぐ買える" : "あと" + ym(n)}！\n#おかねの物差し ${SITE}#save`, $("goalCopied"));
  });

  // ===== 数字が変わったら、ふわっと出す =====
  if (!matchMedia("(prefers-reduced-motion: reduce)").matches && "MutationObserver" in window) {
    const mo = new MutationObserver((ms) => ms.forEach((m) => {
      const el = m.target.nodeType === 1 ? m.target : m.target.parentElement;
      const v = el && el.closest(".answer .value, .conv-cell .v, .mc-row .v");
      if (!v) return; v.classList.remove("bump"); void v.offsetWidth; v.classList.add("bump");
    }));
    document.querySelectorAll(".answer .value, .conv-cell .v").forEach((el) => mo.observe(el, { childList: true, characterData: true, subtree: true }));
    const card = $("mcCard"); if (card) mo.observe(card, { childList: true, subtree: true });
  }

  D.OK.onUnit(() => { renderReceipt(); renderGoal(); });
  renderReceipt(); renderYear(); renderGoal();
})();

;

/* ===== okane-fx.js ===== */
// おかねの物差し：円安・円高（ドル円）・サイト内をさがす
(() => {
  const D = window, { $, yen, esc, store, sgn } = D.OK;
  const Y0 = D.FX_FIRST_YEAR, FX = D.FX, Y1 = Y0 + FX.length - 1;
  const rate = (y) => y === "now" ? D.FX_LATEST.value : FX[y - Y0];
  const yName = (y) => y === "now" ? `今（${D.FX_LATEST.label}）` : `${y}年`;
  const minI = FX.indexOf(Math.min(...FX)), maxI = FX.indexOf(Math.max(...FX.slice(10))); // 2000年以降で最も円安

  // ===== 07 1ドルは何円？ =====
  let sel = store.get("fxYear", Y1);
  const yIn = $("fxYear"), usdIn = $("fxUsd");
  usdIn.value = store.get("fxUsd", 100);
  const YCH = [[1990, "1990年"], [Y0 + minI, `${Y0 + minI}年（円高）`], [2015, "2015年"], [Y1, `${Y1}年`], ["now", `今（${D.FX_LATEST.label}）`]];
  YCH.forEach(([y, t]) => {
    const b = document.createElement("button"); b.type = "button"; b.className = "chip"; b.dataset.y = y; b.textContent = t;
    b.addEventListener("click", () => { sel = y === "now" ? "now" : +y; store.set("fxYear", sel); if (sel !== "now") yIn.value = sel; render(); });
    $("fxYears").appendChild(b);
  });
  [[100, "100ドル"], [499, "499ドル（ゲーム機の例）"], [1000, "1,000ドル（海外旅行の例）"]].forEach(([v, t]) => {
    const b = document.createElement("button"); b.type = "button"; b.className = "chip"; b.dataset.v = v; b.textContent = t;
    b.addEventListener("click", () => { usdIn.value = v; store.set("fxUsd", v); render(); });
    $("fxChips").appendChild(b);
  });
  yIn.addEventListener("input", () => { sel = +yIn.value; store.set("fxYear", sel); render(); });
  usdIn.addEventListener("input", () => { store.set("fxUsd", usdIn.value); render(); });

  function render() {
    if (sel !== "now") yIn.value = sel;
    $("fxYearL").textContent = sel === "now" ? D.FX_LATEST.label : sel;
    [...$("fxYears").children].forEach((c) => c.setAttribute("aria-pressed", String(String(sel) === c.dataset.y)));
    const usd = Math.max(0, parseFloat(usdIn.value) || 0);
    [...$("fxChips").children].forEach((c) => c.setAttribute("aria-pressed", String(+c.dataset.v === usd)));
    const r = rate(sel), jp = usd * r;
    $("fxLabel").textContent = `${yName(sel)}（1ドル＝${r.toFixed(1)}円）なら、${usd.toLocaleString()}ドルは`;
    $("fxValue").innerHTML = `${yen(jp)}<span class="u">円</span>`;
    const r25 = rate(Y1), d = usd * (r - r25);
    $("fxSub").innerHTML = `1万円は約<b>${(10000 / r).toFixed(1)}ドル</b>。` + (sel === Y1 ? "" : `${Y1}年とくらべると${Math.abs(d) < 1 ? "ほぼ同じ" : `<b>${yen(Math.abs(d))}円${d > 0 ? "高い" : "安い"}</b>`}です。`);
    const rows = [Y0 + minI, 2015, 2020, Y1, "now"];
    const mx = Math.max(...rows.map(rate));
    $("fxCompare").innerHTML = `<div class="label">同じ${usd.toLocaleString()}ドルの物が、日本の円だと</div>` + rows.map((y) => `<div class="fx-row${String(y) === String(sel) ? " on" : ""}"><span class="y">${yName(y)}</span><span class="bar"><i style="width:${rate(y) / mx * 100}%"></i></span><span class="v">${yen(usd * rate(y))}円</span></div>`).join("");
    drawChart();
  }
  function drawChart() {
    const xs = FX.map((_, i) => Y0 + i), si = sel === "now" ? xs.length - 1 : sel - Y0;
    D.OK.lineChart($("fxChart"), {
      W: 760, H: 300, M: { l: 40, r: 96, t: 22, b: 28 }, xs, yMin: 60, yMax: 160, yTicks: [60, 80, 100, 120, 140, 160],
      series: [{ v: FX, c: "var(--cool)", label: `${Y1}年`, end: `${FX[FX.length - 1].toFixed(1)}円` }],
      xTicks: (x) => x % 5 === 0 || x === Y1, fmtX: (x) => x, tip: $("fxTip"),
      marks: [
        (X, Y) => `<line x1="${X(si)}" x2="${X(si)}" y1="22" y2="272" stroke="var(--ruler)" stroke-width="3" opacity=".8"/>`,
        (X, Y) => `<circle cx="${X(minI)}" cy="${Y(FX[minI])}" r="4" fill="var(--ruler)" stroke="var(--ink)" stroke-width="1.5"/><text class="ev" x="${X(minI)}" y="${Y(FX[minI]) + 20}" text-anchor="middle">いちばん円高 ${FX[minI].toFixed(1)}円</text>` +
          `<circle cx="${X(maxI)}" cy="${Y(FX[maxI])}" r="4" fill="var(--ruler)" stroke="var(--ink)" stroke-width="1.5"/><text class="ev" x="${X(maxI) - 6}" y="${Y(FX[maxI]) - 10}" text-anchor="end">円安 ${FX[maxI].toFixed(1)}円</text>`,
      ],
      onHover: (i) => `<b>${xs[i]}年</b><br>1ドル＝<b>${FX[i].toFixed(1)}円</b><br>100ドルは <b>${yen(100 * FX[i])}円</b>`,
    });
  }
  // できごとカード（すべてデータから）
  const r21 = rate(2021), r24 = rate(2024);
  $("fxCards").innerHTML = [
    { yr: `${Y0 + minI}年`, t: "円高の時代", d: `1ドル＝約${FX[minI].toFixed(0)}円。100ドルの物が約${yen(100 * FX[minI])}円で買えました。海外旅行はお得でしたが、日本の物を外国に売る会社は苦しみました。` },
    { yr: `2021→2024年 ${sgn((r24 / r21 - 1) * 100)}`, t: "急な円安", d: `1ドル＝${r21.toFixed(1)}円から${r24.toFixed(1)}円へ。外国から買うガソリンや小麦が高くなり、日本の物価が上がった理由のひとつになりました。` },
    { yr: D.FX_LATEST.label, t: "今の1ドル", d: `月平均で1ドル＝${D.FX_LATEST.value.toFixed(1)}円。1万円は約${(10000 / D.FX_LATEST.value).toFixed(1)}ドル、100ドルの物は約${yen(100 * D.FX_LATEST.value)}円です。` },
  ].map((c) => `<div class="event"><span class="yr">${c.yr}</span><b>${c.t}</b><p>${c.d}</p></div>`).join("");

  // ===== サイトの中をさがす =====
  const dlg = $("findDlg"), inp = $("findIn"), res = $("findRes");
  // カタカナをひらがなに、全角英数を半角に（「オニギリ」でも「おにぎり」でも見つかるように）
  const norm = (s) => String(s).toLowerCase().replace(/[ァ-ヶ]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0x60)).replace(/[Ａ-Ｚａ-ｚ０-９]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xfee0)).replace(/\s+/g, "");
  const plain = (el) => { if (!el) return ""; const c = el.cloneNode(true); c.querySelectorAll("rt").forEach((r) => r.remove()); return c.textContent.trim(); };
  let index = null;
  function build() {
    const out = [];
    document.querySelectorAll("section.ch").forEach((s) => {
      const h = s.querySelector(".ch-head h2") || s.querySelector("h2"); if (!h) return;
      const n = s.querySelector(".rule-band span"), tk = s.querySelector(".takeaway p");
      out.push({ type: "章", label: `${n ? n.textContent + " " : ""}${plain(h)}`, sub: tk ? tk.textContent : "", href: "#" + s.id, key: norm(plain(h) + " " + plain(s.querySelector(".ch-head p")) + " " + (tk ? tk.textContent : "")) });
    });
    D.ITEMS.forEach((it) => out.push({ type: "品物", label: it.name, sub: `${it.unit}・${yen(it.p25)}円（東京23区・2025年）→ はたらく時間で見る`, href: "#hours", act: () => D.OK.selectItem(it.id), key: norm(it.name + it.unit) }));
    D.PREFS.forEach((p, i) => out.push({ type: "都道府県", label: D.OK.prefName(i), sub: `最低賃金 ${yen(D.PREF_WAGE[i])}円・${p.city} → 日本地図で見る`, href: "#map", act: () => D.OK.selectPrefOnMap && D.OK.selectPrefOnMap(i), key: norm(D.OK.prefName(i) + p.city) }));
    // 章の中の「やってみよう」（買い物かご・ゲーム・すごろくなど）、相談室の質問、歴史の年表
    const goTo = (el, open) => () => setTimeout(() => { if (open) open(); el.classList.add("flash"); setTimeout(() => el.classList.remove("flash"), 2400); el.scrollIntoView({ block: "start", behavior: "instant" }); scrollBy({ top: -90, behavior: "instant" }); }, 80);
    document.querySelectorAll("section.ch .bk-head").forEach((h) => {
      const blk = h.parentElement, s = blk.closest("section.ch"), t = h.querySelector("h3"), b = h.querySelector(".bk-badge"), p = h.querySelector("p");
      if (!t || !s) return;
      out.push({ type: b ? b.textContent : "やってみよう", label: plain(t), sub: plain(p).slice(0, 50) + "…", href: "#" + s.id, act: goTo(blk), key: norm(plain(t) + (b ? b.textContent : "") + plain(p)) });
    });
    document.querySelectorAll(".faq").forEach((f) => { const q = f.querySelector(".fq-q"); if (!q) return;
      out.push({ type: "なぜなに", label: q.textContent, sub: plain(f.querySelector(".fq-bub p")).slice(0, 48) + "…", href: "#words", act: goTo(f, () => { f.open = true; }), key: norm(q.textContent + plain(f.querySelector(".fq-bub"))) }); });
    document.querySelectorAll(".hl-card").forEach((c) => { const t = c.querySelector(".hl-top b"), e = c.querySelector(".hl-era");
      out.push({ type: "歴史", label: t.textContent, sub: e.textContent, href: "#money", act: goTo(c), key: norm(t.textContent + e.textContent + plain(c.querySelector("p"))) }); });
    document.querySelectorAll(".word").forEach((w) => { const t = w.querySelector(".w").textContent, r = w.querySelector(".r"); out.push({ type: "ことば", label: t, sub: w.querySelector("p").textContent.slice(0, 48) + "…", href: "#words", act: () => { w.classList.add("flash"); setTimeout(() => w.classList.remove("flash"), 2400); setTimeout(() => w.scrollIntoView({ block: "center", behavior: "instant" }), 50); }, key: norm(t + (r ? r.textContent : "")) }); });
    return out;
  }
  function search() {
    if (!index) index = build();
    const q = norm(inp.value);
    if (!q) {
      const SUG = ["ゲーム", "お米", "円安", "税金", "すごろく", "歴史", "東京", "インフレ"];
      res.innerHTML = `<li class="find-hint">言葉を入れると、章・品物・都道府県・ことば・ゲームや体験・なぜなに・歴史から見つけます。<div class="find-sug">${SUG.map((s) => `<button type="button" class="chip" data-s="${s}">${s}</button>`).join("")}</div></li>`;
      res.querySelectorAll("[data-s]").forEach((b) => b.addEventListener("click", () => { inp.value = b.dataset.s; search(); inp.focus(); }));
      return;
    }
    const hit = index.filter((x) => x.key.includes(q)).sort((a, b) => (norm(a.label).startsWith(q) ? 0 : 1) - (norm(b.label).startsWith(q) ? 0 : 1)).slice(0, 14);
    res.innerHTML = hit.length ? hit.map((x, k) => `<li><a href="${x.href}" data-k="${index.indexOf(x)}"><span class="ft">${x.type}</span><span class="fl">${esc(x.label)}</span><span class="fs">${esc(x.sub)}</span></a></li>`).join("") : `<li class="find-hint">「${esc(inp.value)}」は見つかりませんでした。ちがう言葉でためしてみよう。</li>`;
    res.querySelectorAll("a").forEach((a) => a.addEventListener("click", () => { const x = index[+a.dataset.k]; if (x.act) x.act(); dlg.close(); }));
  }
  $("findBtn").addEventListener("click", () => { index = null; inp.value = ""; search(); if (dlg.showModal) dlg.showModal(); else dlg.setAttribute("open", ""); setTimeout(() => inp.focus(), 30); });
  $("findClose").addEventListener("click", () => dlg.close());
  dlg.addEventListener("click", (e) => { if (e.target === dlg) dlg.close(); });
  inp.addEventListener("input", search);
  inp.addEventListener("keydown", (e) => { if (e.key === "Enter") { const a = res.querySelector("a"); if (a) { e.preventDefault(); a.click(); } } });

  render();
})();

;

/* ===== okane-now.js ===== */
// おかねの物差し：今の物価（いちばん新しい月）・データの新しさの表
(() => {
  const D = window, { $, yen, esc } = D.OK;
  const L = D.CPI_LATEST;

  // ホームの「今の物価」
  $("nowCpi").innerHTML = `<span class="nk">今の物価</span><span class="nv">+${L.yoy}<small>%</small></span>
    <span class="nt">${L.label}の物価は、1年前より<b>${L.yoy}%</b>上がりました。1年前に1,000円だった買い物は、今は約<b>${yen(1000 * (1 + L.yoy / 100))}円</b>です。</span>
    <span class="ns">全国・総合。総務省統計局「消費者物価指数」${L.published}発表。押すと物価タイムマシンへ。</span><span class="spark" id="nowSpark"></span>`;
  // 画面の幅に合わせて描く（文字の大きさがいつも同じになるように）
  let lastW = 0;
  const drawSpark = () => {
    const cw = $("nowCpi").clientWidth; if (!cw) return;
    const w = Math.round(Math.min(1100, Math.max(280, cw - 40))); if (w === lastW) return;
    lastW = w; $("nowSpark").innerHTML = spark(w);
  };
  drawSpark();
  addEventListener("resize", drawSpark);
  addEventListener("hashchange", () => setTimeout(drawSpark, 50));
  addEventListener("popstate", () => setTimeout(drawSpark, 50));
  document.addEventListener("click", () => setTimeout(drawSpark, 80));

  // 最近2年の上がり方（月ごとの棒）。いちばん高い月と、最新の月に数字をつける
  function spark(W) {
    const M = D.CPI_MONTHLY; if (!M) return "";
    const v = M.yoy, n = v.length, [fy, fm] = M.from.split("-").map(Number);
    const lab = (i) => { const d = new Date(fy, fm - 1 + i, 1); return `${d.getFullYear()}年${d.getMonth() + 1}月`; };
    const H = 92, top = 22, base = 70, max = Math.max(...v, 1), bw = (W - 20) / n;
    const pk = v.indexOf(Math.max(...v));
    let s = `<line x1="0" x2="${W}" y1="${base}" y2="${base}" stroke="var(--line)"/>`;
    v.forEach((x, i) => {
      const h = Math.max(1, (x / max) * (base - top)), X = 10 + i * bw;
      s += `<rect x="${X + 1}" y="${base - h}" width="${bw - 3}" height="${h}" rx="2" fill="${i === n - 1 ? "var(--hot)" : "color-mix(in srgb, var(--hot) 45%, var(--card))"}"><title>${lab(i)}：${x}%</title></rect>`;
    });
    const tx = (i) => 10 + i * bw + bw / 2;
    s += `<text x="${tx(pk)}" y="${base - (v[pk] / max) * (base - top) - 6}" text-anchor="middle" class="sp-l">${lab(pk)} ${v[pk]}%</text>`;
    s += `<text x="${tx(0)}" y="${H - 4}" class="sp-a">${lab(0)}</text><text x="${tx(n - 1)}" y="${H - 4}" text-anchor="end" class="sp-a">${lab(n - 1)}</text>`;
    const trend = v[n - 1] < v[pk] ? `いちばん高かった${lab(pk)}の${v[pk]}%から、上がり方はゆっくりになっています。` : "";
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="最近2年の物価の上がり方">${s}</svg><span class="sp-t">最近2年の物価の上がり方（前の年の同じ月とくらべて）。${trend}</span>`;
  }

  // データの新しさ
  $("freshTable").innerHTML = `<thead><tr><th>データ</th><th>今の数字</th><th>次に新しくなる時期（目安）</th><th>更新</th></tr></thead><tbody>` +
    D.DATA_FRESH.map((r) => `<tr><td>${esc(r.what)}</td><td>${esc(r.has)}</td><td>${esc(r.next)}</td><td><span class="fq ${r.freq === "月" ? "m" : ""}">${r.freq === "月" ? "毎月" : "年1回"}</span></td></tr>`).join("") + `</tbody>`;
  const f = document.querySelector("footer .wrap span:last-child");
  $("freshUpdated").textContent = f ? f.textContent.replace("最終更新：", "") : "";
})();

;

/* ===== okane-diary.js ===== */
// おかねの物差し：わたしのおこづかい帳（記録はこのブラウザの中だけに保存）
(() => {
  const D = window, { $, yen, esc, store, hmText } = D.OK;
  const SITE = "https://azakeiten.github.io/okane-monosashi/";
  const CATS = [
    { k: "snack", t: "おやつ・食べ物", c: "var(--seg3)", r: 8 },
    { k: "fun", t: "あそび・ゲーム", c: "var(--seg5)", r: 10 },
    { k: "study", t: "文ぼう具・本", c: "var(--seg1)", r: 10 },
    { k: "wear", t: "ふく・身の回り", c: "var(--seg4)", r: 10 },
    { k: "other", t: "そのほか", c: "var(--muted)", r: 10 },
    { k: "save", t: "ちょきん", c: "var(--good)", r: 0 },
  ];
  const cat = (k) => CATS.find((c) => c.k === k) || CATS[4];
  const pad = (n) => String(n).padStart(2, "0");
  const ymd = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const today = new Date(), thisMonth = ymd(today).slice(0, 7);

  // はじめて開いたときは、使い方がわかるように「例」を表示する（自分の記録を入れると消える）
  function sample() {
    const m = thisMonth;
    return [
      { d: `${m}-02`, n: "おにぎり", a: 176, c: "snack" }, { d: `${m}-03`, n: "ノート", a: 207, c: "study" },
      { d: `${m}-05`, n: "ガチャガチャ", a: 300, c: "fun" }, { d: `${m}-06`, n: "ポテトチップス", a: 150, c: "snack" },
      { d: `${m}-08`, n: "マンガ", a: 594, c: "study" }, { d: `${m}-09`, n: "ちょきん箱へ", a: 1000, c: "save" },
    ].map((e, i) => ({ ...e, id: "ex" + i, ex: true }));
  }
  let list = store.get("diary", null);
  if (!Array.isArray(list)) list = sample();
  let view = thisMonth, curCat = "snack";
  const save = () => store.set("diary", list);

  CATS.forEach((c) => {
    const b = document.createElement("button");
    b.type = "button"; b.dataset.k = c.k; b.innerHTML = `${c.t}<span class="num">${c.r ? "消費税" + c.r + "%" : "使わずにためる"}</span>`;
    b.addEventListener("click", () => { curCat = c.k; paintCats(); });
    $("dyCat").appendChild(b);
  });
  const paintCats = () => [...$("dyCat").children].forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.k === curCat)));
  $("dyDate").value = ymd(today);

  $("dyForm").addEventListener("submit", (e) => {
    e.preventDefault();
    const n = $("dyName").value.trim(), a = Math.round(parseFloat($("dyAmt").value));
    if (!n || !(a > 0)) { $("dyMsg").textContent = "買ったものと金額を入れてください。"; return; }
    list = list.filter((x) => !x.ex); // 自分の記録をはじめたら、例は消す
    const d = $("dyDate").value || ymd(today);
    list.push({ id: Date.now().toString(36), d, n, a, c: curCat });
    save(); view = d.slice(0, 7);
    $("dyMsg").textContent = `「${n}」${yen(a)}円を記録しました。`;
    $("dyName").value = ""; $("dyAmt").value = ""; $("dyName").focus();
    render();
  });
  $("dySample").addEventListener("click", () => { list = list.filter((x) => !x.ex); save(); render(); });
  const shift = (k) => { const [y, m] = view.split("-").map(Number); const d = new Date(y, m - 1 + k, 1); view = `${d.getFullYear()}-${pad(d.getMonth() + 1)}`; render(); };
  $("dyPrev").addEventListener("click", () => shift(-1));
  $("dyNext").addEventListener("click", () => shift(1));

  function month() { return list.filter((x) => x.d.slice(0, 7) === view).sort((a, b) => b.d.localeCompare(a.d)); }
  function stats(items) {
    const by = {}; CATS.forEach((c) => (by[c.k] = 0));
    items.forEach((x) => (by[x.c] = (by[x.c] || 0) + x.a));
    const spend = items.filter((x) => x.c !== "save").reduce((s, x) => s + x.a, 0);
    const tax = items.reduce((s, x) => { const r = cat(x.c).r; return s + (r ? x.a * r / (100 + r) : 0); }, 0);
    return { by, spend, saved: by.save || 0, tax: Math.floor(tax) };
  }
  function render() {
    const [y, m] = view.split("-").map(Number), items = month(), s = stats(items), w = D.OK.wage(), allow = D.OK.allow();
    const ex = list.some((x) => x.ex);
    $("dyMonthL").textContent = `${y}年${m}月${view === thisMonth ? "（今月）" : ""}に使ったお金${ex ? "（例）" : ""}`;
    $("dyTotal").innerHTML = `${yen(s.spend)}<span class="u">円</span>`;
    $("dySub").innerHTML = items.length ? `おこづかい（月${yen(allow)}円）の<b>${Math.round(s.spend / allow * 100)}%</b>。のこりは<b>${yen(Math.max(0, allow - s.spend - s.saved))}円</b>${s.saved ? `、ちょきんは${yen(s.saved)}円` : ""}です。` : "この月の記録はまだありません。";
    const spendCats = CATS.filter((c) => c.k !== "save" && s.by[c.k] > 0);
    $("dyBar").innerHTML = spendCats.map((c) => `<div style="flex:${s.by[c.k]};background:${c.c}" title="${c.t} ${yen(s.by[c.k])}円"></div>`).join("");
    $("dyLegend").innerHTML = spendCats.map((c) => `<span class="box" style="--c:${c.c}">${c.t} ${Math.round(s.by[c.k] / (s.spend || 1) * 100)}%</span>`).join("");
    const food = s.spend ? s.by.snack / s.spend * 100 : 0;
    const K = D.KAKEI, ky = K["食料"].length - 1, fam = K["食料"][ky] / K["消費支出"][ky] * 100;
    $("dyFacts").innerHTML = items.length ? [
      { k: "払った消費税", v: `約${yen(s.tax)}円`, s: "食べ物8%、それ以外10%で計算" },
      { k: "はたらく時間にすると", v: hmText(s.spend / w), s: `時給${yen(w)}円の場合` },
      { k: "食べ物の割合", v: `${Math.round(food)}%`, s: `家族の家計では約${Math.round(fam)}%（家計調査）` },
      { k: "いちばん多い使い道", v: spendCats.length ? spendCats.slice().sort((a, b) => s.by[b.k] - s.by[a.k])[0].t : "—", s: spendCats.length ? `${yen(Math.max(...spendCats.map((c) => s.by[c.k])))}円` : "" },
    ].map((f) => `<div><span class="k">${f.k}</span><span class="v">${esc(f.v)}</span><span class="s">${esc(f.s)}</span></div>`).join("") : "";
    $("dyList").innerHTML = items.length ? items.map((x) => { const c = cat(x.c); return `<li class="${x.ex ? "ex" : ""}"><span class="sw" style="background:${c.c}"></span><span class="d">${+x.d.slice(5, 7)}/${+x.d.slice(8)}</span><span class="n">${esc(x.n)}<small>${c.t}${x.ex ? "・例" : ""}</small></span><span class="a">${x.c === "save" ? "ちょきん " : ""}${yen(x.a)}円</span><button type="button" class="x" data-id="${x.id}" aria-label="${esc(x.n)}を消す">×</button></li>`; }).join("") : `<li class="none">左のフォームから記録してみよう</li>`;
    $("dyList").querySelectorAll(".x").forEach((b) => b.addEventListener("click", () => { list = list.filter((x) => x.id !== b.dataset.id); save(); render(); }));
    $("dySample").hidden = !ex;
    $("dyCopied").textContent = "";
  }
  $("dyCopy").addEventListener("click", () => {
    const [y, m] = view.split("-").map(Number), items = month(), s = stats(items);
    const lines = CATS.filter((c) => s.by[c.k] > 0).map((c) => `・${c.t}：${yen(s.by[c.k])}円`);
    D.OK.copy(`【${y}年${m}月のおこづかい帳】\n使ったお金：${yen(s.spend)}円（消費税 約${yen(s.tax)}円）\n${lines.join("\n")}\n#おかねの物差し ${SITE}#diary`, $("dyCopied"));
  });

  paintCats();
  D.OK.onUnit(render);
  render();
})();

;

/* ===== okane-age.js ===== */
// おかねの物差し：大人になったら、給料はどう変わる？・読んでいる位置のバー
(() => {
  const D = window, { $, yen, esc, store, hmText } = D.OK;
  const A = D.AGEWAGE, N = A.ages.length;
  const ONI = D.ITEMS.find((i) => i.id === "onigiri").p25;
  const short = (s) => s.replace("歳", "");

  // ===== 10 年れいと給料 =====
  const ageIn = $("awAge");
  ageIn.value = store.get("awAge", 1);
  let show = store.get("awShow", "all");
  ageIn.addEventListener("input", () => { store.set("awAge", +ageIn.value); render(); });
  $("awShow").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; show = b.dataset.v; store.set("awShow", show); render(); });

  function render() {
    const i = +ageIn.value, m = A.all[i] * 1000, w = D.OK.wage();
    [...$("awShow").children].forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.v === show)));
    $("awAgeL").textContent = A.ages[i];
    $("awLabel").textContent = `${A.ages[i]}の人の、1か月の給料（平均）`;
    $("awValue").innerHTML = `${yen(m)}<span class="u">円</span>`;
    const base = A.all[1];
    $("awSub").innerHTML = i === 1 ? `ここを1として、ほかの年れいとくらべます。` : `20〜24歳（${yen(base * 1000)}円）の<b>${(A.all[i] / base).toFixed(2)}倍</b>です。`;
    const net = D.OK.calcPay(m, 2).net;
    $("awGrid").innerHTML = [
      { k: "手取り（目安）", v: `約${yen(Math.round(net / 1000) * 1000)}円`, s: "税金・保険料を引いたあと" },
      { k: "おにぎりにすると", v: `${yen(m / ONI)}個`, s: `1個${ONI}円で` },
      { k: "あなたの時給だと", v: hmText(m / w).replace(/約(\d+)時間\d+分/, "約$1時間"), s: `時給${yen(w)}円で何時間ぶんか` },
      { k: "男女べつ", v: `${yen(A.men[i] * 1000)}円／${yen(A.women[i] * 1000)}円`, s: "男性／女性の平均" },
    ].map((c) => `<div><span class="k">${c.k}</span><span class="v">${esc(c.v)}</span><span class="s">${esc(c.s)}</span></div>`).join("");
    draw(i);
  }
  function draw(sel) {
    const xs = A.ages.map((_, i) => i);
    const series = [{ v: A.all, c: "var(--cool)", label: "男女あわせて", end: `${A.all[N - 1]}`, dy: 14 }];
    if (show === "split") {
      series.push({ v: A.men, c: "var(--seg5)", label: "男性", end: `${A.men[N - 1]}`, dy: -14 });
      series.push({ v: A.women, c: "var(--seg6)", label: "女性", end: `${A.women[N - 1]}`, dy: 14 });
    }
    $("awLegend").innerHTML = series.map((s) => `<span style="--c:${s.c}">${s.label}</span>`).join("");
    D.OK.lineChart($("awChart"), {
      W: 760, H: 300, M: { l: 46, r: 110, t: 20, b: 30 }, xs, yMin: 150, yMax: 500, yTicks: [200, 300, 400, 500],
      series, xTicks: () => true, fmtX: (i) => short(A.ages[i]), tip: $("awTip"),
      marks: [(X) => `<line x1="${X(sel)}" x2="${X(sel)}" y1="20" y2="270" stroke="var(--ruler)" stroke-width="3" opacity=".8"/>`],
      onHover: (i) => `<b>${A.ages[i]}</b><br>男女あわせて <b>${yen(A.all[i] * 1000)}円</b>` + (show === "split" ? `<br>男性 <b>${yen(A.men[i] * 1000)}円</b><br>女性 <b>${yen(A.women[i] * 1000)}円</b>` : ""),
    });
    const pk = A.all.indexOf(Math.max(...A.all));
    $("awText").innerHTML = `いちばん多いのは<b>${A.ages[pk]}の${yen(A.all[pk] * 1000)}円</b>で、20〜24歳の約${(A.all[pk] / A.all[1]).toFixed(1)}倍。60歳をすぎると下がり、60〜64歳は${yen(A.all[9] * 1000)}円です。単位は千円（グラフのたての数字）。`;
  }
  D.OK.onUnit(render);
  render();

  // ===== 読んでいる位置のバー（上のバーの下に、黄色い物差しの線） =====
  const bar = document.createElement("div"); bar.className = "readbar"; bar.setAttribute("aria-hidden", "true");
  document.querySelector(".top").appendChild(bar);
  let ticking = false;
  const update = () => { const h = document.documentElement.scrollHeight - innerHeight; bar.style.transform = `scaleX(${h > 0 ? Math.min(1, scrollY / h) : 0})`; ticking = false; };
  addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
  addEventListener("resize", update); update();
  // 画面を切りかえたあとも正しく出るように
  document.addEventListener("click", () => setTimeout(update, 60));
})();

;

/* ===== okane-pwa.js ===== */
// おかねの物差し：アプリとしてホーム画面に追加・オフラインで使う（GitHub版のページでだけ動く）
(() => {
  const framed = (() => { try { return window.self !== window.top; } catch (e) { return true; } })();
  const secure = location.protocol === "https:";
  if (framed || !secure) return;
  if ("serviceWorker" in navigator) {
    window.addEventListener("load", () => { navigator.serviceWorker.register("sw.js").catch(() => {}); });
  }
  const standalone = matchMedia("(display-mode: standalone)").matches || navigator.standalone === true;
  if (standalone) return;
  const box = document.getElementById("installBox"), btn = document.getElementById("installBtn"), txt = document.getElementById("installText");
  if (!box) return;
  const ua = navigator.userAgent, ios = /iPhone|iPad|iPod/.test(ua) || (/Macintosh/.test(ua) && "ontouchend" in document);
  if (ios) {
    txt.innerHTML = "Safariの下にある<b>共有ボタン</b>（四角から矢印が出ているマーク）を押して、<b>「ホーム画面に追加」</b>をえらんでください。全画面で使えて、電波がないところでも動きます。";
    box.hidden = false;
  }
  // Android・パソコンのChromeなど：追加できるときだけボタンを出す
  let deferred = null;
  window.addEventListener("beforeinstallprompt", (e) => { e.preventDefault(); deferred = e; box.hidden = false; btn.hidden = false; });
  btn.addEventListener("click", async () => {
    if (!deferred) return;
    deferred.prompt();
    try { await deferred.userChoice; } catch (e) {}
    deferred = null; box.hidden = true;
  });
  window.addEventListener("appinstalled", () => { box.hidden = true; });
})();

;

