/* ===== okane-ux.js ===== */
// おかねの物差し：見やすさの道具（もくじ・この章のポイント・かんたん表示・次の章へ・上へもどる）
(() => {
  const D = window, { $, yen, esc, store, sgn, cpiAt, hmText, AVG10 } = D.OK;

  // ===== かんたん表示 =====
  const easyBtn = $("easyToggle");
  const setSimple = (on) => { document.body.classList.toggle("simple", on); easyBtn.setAttribute("aria-pressed", String(on)); store.set("simple", on); };
  setSimple(store.get("simple", false));
  easyBtn.addEventListener("click", () => setSimple(!document.body.classList.contains("simple")));

  // ===== あなたの物差し（バーの文字と、ヘッダーから開く） =====
  const wrap = $("unitWrap");
  function unitSummary() {
    const p = D.OK.pref();
    $("unitSummary").textContent = `${p >= 0 ? D.OK.prefName(p) + "・" : ""}時給${yen(D.OK.wage())}円・おこづかい月${yen(D.OK.allow())}円`;
  }
  $("unitPill").addEventListener("click", () => { wrap.open = true; });
  D.OK.onUnit(unitSummary); unitSummary();

  // ===== 各章の答え（数字はすべてデータから） =====
  const item = (id) => D.ITEMS.find((i) => i.id === id);
  const pmin = D.CITY.onigiri.map((p, i) => p == null ? null : p / D.PREF_WAGE[i] * 60).filter((v) => v != null);
  const top = D.ITEMS.map((i) => ({ ...i, c: (i.p25 / i.p15 - 1) * 100 })).sort((a, b) => b.c - a.c)[0];
  const K = D.KAKEI, KY = D.KAKEI_FIRST_YEAR, ky1 = KY + K["消費支出"].length - 1;
  const ANSWERS = {
    money: () => { const r = item("rice"), n = item("notebook"); return `お金には<b>とりかえる・はかる・ためる</b>の3つの役割があります。「円」という物差しがあるから、お米5kgはノート<b>約${Math.round(r.p25 / n.p25)}冊分</b>、とくらべられます。`; },
    hours: () => `時給${yen(D.OK.wage())}円なら、おにぎり1個は<b>${hmText(item("onigiri").p25 / D.OK.wage())}</b>、お米5kgは<b>${hmText(item("rice").p25 / D.OK.wage())}</b>はたらくと買えます。`,
    map: () => `おにぎり1個を買うのにはたらく時間は、県によって<b>${hmText(Math.min(...pmin) / 60)}</b>から<b>${hmText(Math.max(...pmin) / 60)}</b>までちがいます。`,
    rank: () => `10年でいちばん値上がりしたのは<b>${esc(top.name)}（${sgn(top.c)}）</b>。物価全体の上がり方は<b>${sgn(AVG10, 1)}</b>でした。`,
    time: () => `1990年の物価は今の<b>約${Math.round(cpiAt("総合", 1990) / 10)}割</b>。今の1,000円の買い物は、1990年なら<b>約${yen(1000 * cpiAt("総合", 1990) / 100)}円</b>です。`,
    race: () => { const w = D.MINWAGE[2025] / D.MINWAGE[2002], c = cpiAt("総合", 2025) / cpiAt("総合", 2002); return `2002年から2025年で、最低賃金は<b>${w.toFixed(2)}倍</b>、物価は<b>${c.toFixed(2)}倍</b>。最低賃金で買えるものは増えました。`; },
    kakei: () => `家族は1か月に平均<b>${yen(K["消費支出"][ky1 - KY] / 12)}円</b>を使い、そのうち<b>約${Math.round(K["食料"][ky1 - KY] / K["消費支出"][ky1 - KY] * 10)}割</b>が食べ物です。`,
    save: () => `物価が毎年2%上がると、1万円で買えるものは10年後に<b>約${yen(Math.round(10000 / Math.pow(1.02, 10) / 100) * 100)}円ぶん</b>に減ります。`,
    pay: () => { const r = D.OK.calcPay(262300, 1); return `大学卒の初任給<b>262,300円</b>でも、口座に入るのは<b>約${Math.round(r.net / 10000)}万円</b>。約<b>${Math.round((1 - r.net / 262300) * 100)}%</b>が税金と保険料です。`; },
    school: () => { const g = (id) => D.SCHOOL.find((s) => s.id === id).total; return `1年の学習費は、公立小学校で<b>約${Math.round(g("es-pub") / 1e4)}万円</b>、私立小学校で<b>約${Math.round(g("es-pri") / 1e4)}万円</b>。公立小学校では、塾や習いごとのお金がいちばん多くなっています。`; },
    agewage: () => { const A = D.AGEWAGE, pk = A.all.indexOf(Math.max(...A.all)); return `20〜24歳の給料は平均<b>月${yen(A.all[1] * 1000)}円</b>。いちばん多いのは${A.ages[pk]}の<b>月${yen(A.all[pk] * 1000)}円</b>（約${(A.all[pk] / A.all[1]).toFixed(1)}倍）で、60歳をすぎると下がります。`; },
    big: () => { const P = D.POPULATION.value, m = (v) => (v / P / 1e4).toLocaleString("ja-JP", { maximumFractionDigits: 1 }); return `国の予算122.3兆円は、1人あたり<b>約${m(D.BIG[0].value)}万円</b>。国の借金1,145兆円は、1人あたり<b>約${Math.round(D.BIG[3].value / P / 1e4).toLocaleString()}万円</b>です。`; },
    fx: () => { const F = D.FX, y1 = D.FX_FIRST_YEAR + F.length - 1, lo = Math.min(...F), ly = D.FX_FIRST_YEAR + F.indexOf(lo), now = F[F.length - 1]; return `${y1}年の1ドルは平均<b>${now.toFixed(1)}円</b>。いちばん円高だった${ly}年（${lo.toFixed(1)}円）の約${(now / lo).toFixed(1)}倍で、100ドルの物は<b>約${yen(100 * lo)}円→約${yen(100 * now)}円</b>になりました。`; },
    tax: () => { const p = item("onigiri").p25, t = Math.floor(p * 8 / 108); return `おにぎり${p}円の中に、消費税は<b>約${t}円</b>（8%）。国の税金でいちばん多いのが<b>消費税 ${(D.TAXREV.consumption / 1e12).toFixed(1)}兆円</b>です。`; },
    diary: () => `使ったお金を記録すると、<b>使い道の割合</b>・<b>払った消費税</b>・<b>はたらく時間</b>が自動でわかる、自分だけの家計簿です。`,
    quiz: () => `<b>5つのモード</b>（値上がり・何時間・日本地図・昔の値段・しくみ）で力だめし。出てくる数字はぜんぶ本物の統計です。`,
    words: () => `ニュースでよく聞く<b>${document.querySelectorAll(".word").length}</b>のことばを、このサイトの数字で説明します。`,
    sheet: () => `サイトで答えをさがす<b>8問</b>と、近くのお店の値段しらべ。自由研究や授業に使えます。`,
  };
  const IDS = Object.keys(ANSWERS);
  const secs = IDS.map((id) => $(id)).filter(Boolean);
  secs.forEach((s) => {
    const head = s.querySelector(".ch-head"); if (!head) return;
    const t = document.createElement("div"); t.className = "takeaway"; t.innerHTML = `<span class="tk-m">${D.OK.mascot("smile", 52)}</span><div class="tk-b"><span class="tk">ものさしくんの、この章のポイント</span><p data-ans="${s.id}"></p></div>`;
    head.appendChild(t);
    const note = document.createElement("p"); note.className = "easy-note"; note.textContent = "かんたん表示中：くわしい説明はたたんであります。上の「かんたん表示」をもう一度押すと全部見られます。";
    s.querySelector(".wrap").appendChild(note);
  });
  function renderAnswers() { document.querySelectorAll("[data-ans]").forEach((p) => { p.innerHTML = ANSWERS[p.dataset.ans](); }); renderToc(); }

  // ふりがな（rt）を除いた見出しの文字
  function plain(el) { if (!el) return ""; const c = el.cloneNode(true); c.querySelectorAll("rt").forEach((r) => r.remove()); return c.textContent.trim(); }

  // ===== 4つのパート =====
  const PARTS = [
    { t: "自分の時間で、くらべる", d: "お金の役割を知り、値段を「はたらく時間」に直して、品物や都道府県をくらべます。", ids: ["money", "hours", "map", "rank"] },
    { t: "昔と今を、さかのぼる", d: "物価・給料・貯金の価値・円の値打ちが、時代とともにどう変わったかを見ます。", ids: ["time", "race", "save", "fx"] },
    { t: "くらしの、しくみを知る", d: "家族と自分のお金の使い道、学校にかかるお金、給料から引かれるお金、国の大きなお金、消費税のしくみ。", ids: ["kakei", "school", "pay", "agewage", "big", "tax", "diary"] },
    { t: "わかったことを、たしかめる", d: "クイズ、ことば辞典、自由研究ワークシート、スタンプラリーで、ふりかえりましょう。", ids: ["quiz", "words", "sheet"] },
  ];
  const chNo = (id) => { const s = $(id), b = s && s.querySelector(".rule-band span"); return b ? +b.textContent : ""; };
  const chTitle = (id) => plain($(id).querySelector(".ch-head h2"));
  // 本文の中に、パートの帯を入れる
  PARTS.forEach((p, i) => {
    const first = $(p.ids[0]); if (!first) return;
    const band = document.createElement("div");
    band.className = "part-band"; band.id = "part" + (i + 1);
    band.innerHTML = `<div class="wrap"><span class="pn">PART ${i + 1}</span><div><h2>${p.t}</h2><p>${p.d}</p></div><nav class="chs" aria-label="パート${i + 1}の章">${p.ids.map((id) => `<a href="#${id}">${D.OK.icon ? D.OK.icon(id, 15) : ""}${String(chNo(id)).padStart(2, "0")} ${esc(chTitle(id).replace(/[？?].*$/, "？"))}</a>`).join("")}</nav></div>`;
    first.parentNode.insertBefore(band, first);
  });

  // ===== もくじ =====
  function card(id, no, title, ans, done) {
    const ic = D.OK.icon ? D.OK.icon(id, 24) : "";
    // 章の中にある「やってみよう」（ゲーム・すごろくなど）を、小さなタグで見せる
    const tags = $(id) ? [...$(id).querySelectorAll(".bk-head h3")].map((h) => h.dataset.tag || h.textContent.split("：")[0].replace(/[？?]$/, "")) : [];
    return `<a class="toc-card" href="#${id}"><span class="no">${ic || no}</span><span class="tq">${ic && typeof no === "number" ? `<small class="tn">${String(no).padStart(2, "0")}</small>` : ""}${esc(title)}</span><span class="ta">${ans}</span>${tags.length ? `<span class="tt">${tags.map((t) => `<i>${esc(t)}</i>`).join("")}</span>` : ""}${done ? '<span class="done">読んだ</span>' : ""}</a>`;
  }
  function renderToc() {
    const got = new Set(store.get("stamps", []));
    $("tocGrid").innerHTML = PARTS.map((p, i) => {
      const cards = p.ids.map((id) => card(id, chNo(id), chTitle(id), ANSWERS[id](), got.has(id)));
      if (i === PARTS.length - 1) cards.push(card("stamps", "★", "物差しスタンプラリー", `章を読むとスタンプ。<b>${got.size}/17</b>こ集めると「物差しはかせ」に認定。`, false));
      return `<div class="toc-part"><div class="toc-part-h"><span class="pn">PART ${i + 1}</span><b>${p.t}</b><span class="d">${p.d}</span></div><div class="toc-grid" style="--cols:${cards.length}">${cards.join("")}</div></div>`;
    }).join("") + `<p class="hint" style="margin-top:14px">数字はぜんぶ、国や公的機関の統計です。くわしくは<a href="#sources">データの出どころ</a>へ。</p>`;
  }

  // ===== たとえば、こんなことがわかります =====
  function renderExamples() {
    const w = D.OK.wage(), tot = K["消費支出"][ky1 - KY] / 12;
    const ex = [
      { id: "hours", q: "お米5kgを買うには、何時間はたらく？", a: hmText(item("rice").p25 / w).replace("約", ""), s: `時給${yen(w)}円・東京23区の値段で` },
      { id: "map", q: "おにぎり1個、県によってはたらく時間は？", a: `${Math.round(Math.min(...pmin))}〜${Math.round(Math.max(...pmin))}<small>分</small>`, s: "47都道府県の最低賃金と値段で" },
      { id: "time", q: "今の1,000円の買い物、1990年ならいくら？", a: `${yen(1000 * cpiAt("総合", 1990) / 100)}<small>円</small>`, s: "消費者物価指数で計算" },
      { id: "kakei", q: "家族が1か月に使うお金は？", a: `${(tot / 10000).toFixed(1)}<small>万円</small>`, s: "2人以上の世帯・2025年平均" },
    ];
    $("exGrid").innerHTML = ex.map((e) => `<a class="ex-card" href="#${e.id}"><span class="q">${e.q}</span><span class="a">${e.a}</span><span class="s">${e.s}</span></a>`).join("");
  }
  D.OK.onUnit(renderExamples);
  renderExamples();
  document.addEventListener("okane:stamp", renderToc);

  // ===== 次の章へ =====
  const all = [...document.querySelectorAll("section.ch")];
  all.forEach((s, i) => {
    const nx = all[i + 1]; if (!nx) return;
    const h = nx.querySelector(".ch-head h2, h2"), num = nx.querySelector(".rule-band span");
    const div = document.createElement("div"); div.className = "next-ch";
    div.innerHTML = `<a href="#${nx.id}"><span><small>次の章${num ? " " + num.textContent : ""}</small>${esc(plain(h))}</span><span class="arw" aria-hidden="true">↓</span></a>`;
    s.querySelector(".wrap").appendChild(div);
  });

  // ===== 上へもどる =====
  const tt = $("toTop");
  const onScroll = () => { tt.hidden = window.scrollY < 900; };
  window.addEventListener("scroll", onScroll, { passive: true }); onScroll();

  D.OK.onUnit(renderAnswers);
  renderAnswers();

  // ===== アプリのような画面切りかえ（ホーム＋4つのパート） =====
  const home = document.querySelector("main > .wrap");
  const VIEWS = { home: { els: [home], t: "ホーム", s: "ホーム", i: "円" } };
  PARTS.forEach((p, i) => {
    const els = [$("part" + (i + 1)), ...p.ids.map((id) => $(id))];
    if (i === PARTS.length - 1) els.push($("stamps"), $("sources"));
    VIEWS["part" + (i + 1)] = { els: els.filter(Boolean), t: p.t, s: ["くらべる", "さかのぼる", "しくみ", "たしかめる"][i], i: String(i + 1) };
  });
  const ORDER = Object.keys(VIEWS);
  // パートの最後の章の「次の章へ」は、下の「次のパートへ」と重なるので消す
  PARTS.forEach((p) => { const last = $(p.ids[p.ids.length - 1]); const n = last && last.querySelector(".next-ch"); if (n) n.remove(); });
  // 画面の下の「前へ・次へ」
  ORDER.forEach((v, k) => {
    const els = VIEWS[v].els, lastEl = els[els.length - 1];
    const prev = ORDER[k - 1], next = ORDER[k + 1];
    const foot = document.createElement("div"); foot.className = "wrap view-foot";
    foot.innerHTML = (prev ? `<a href="#${prev}"><span>←</span><span><small>前へ</small>${esc(VIEWS[prev].t)}</span></a>` : "") +
      (next ? `<a class="nx" href="#${next}"><span><small>${v === "home" ? "さあ、はじめよう" : "次のパートへ"}</small>${next === "home" ? "ホーム" : "PART " + VIEWS[next].i + " " + esc(VIEWS[next].t)}</span><span>→</span></a>` : `<a class="nx" href="#home"><span><small>さいしょにもどる</small>ホーム</span><span>→</span></a>`);
    lastEl.after(foot); els.push(foot);
  });
  // タブバー
  const tabbar = document.createElement("nav");
  tabbar.className = "tabbar"; tabbar.setAttribute("aria-label", "画面の切りかえ");
  tabbar.innerHTML = ORDER.map((v) => `<a href="#${v}" data-v="${v}"><span class="ti">${VIEWS[v].i}</span><span class="tl">${v === "home" ? "ホーム" : "PART " + VIEWS[v].i + "　" + esc(VIEWS[v].t)}</span><span class="tl-s">${VIEWS[v].s}</span></a>`).join("");
  // パソコンでは上のバーの中、スマホでは画面の下（ヘッダーのぼかし効果の外に出す）
  const mq = matchMedia("(max-width: 760px)");
  const placeTabbar = () => { (mq.matches ? document.body : document.querySelector(".top .wrap")).appendChild(tabbar); };
  placeTabbar();
  mq.addEventListener ? mq.addEventListener("change", placeTabbar) : mq.addListener(placeTabbar);
  document.body.classList.add("app");

  const viewOf = (el) => ORDER.find((v) => VIEWS[v].els.some((e) => e === el || e.contains(el)));
  let cur = null;
  function go(v, targetId, push) {
    if (!VIEWS[v]) v = "home";
    if (v !== cur) {
      ORDER.forEach((k) => VIEWS[k].els.forEach((e) => { e.hidden = k !== v; }));
      VIEWS[v].els.forEach((e) => { e.classList.remove("view-in"); void e.offsetWidth; e.classList.add("view-in"); });
      tabbar.querySelectorAll("a").forEach((a) => { if (a.dataset.v === v) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current"); });
      cur = v; store.set("view", v);
    }
    // 画面のいちばん上の要素なら先頭へ、それ以外はその場所へ
    const t = targetId && $(targetId);
    if (t && VIEWS[v].els[0] !== t) t.scrollIntoView({ block: "start", behavior: "instant" });
    else window.scrollTo({ top: 0, behavior: "instant" });
    if (push !== false) { try { history.pushState({ v, t: targetId || null }, "", "#" + (targetId || v)); } catch (e) {} }
  }
  document.addEventListener("click", (e) => {
    const a = e.target.closest('a[href^="#"]'); if (!a) return;
    let id = a.getAttribute("href").slice(1); if (!id) return;
    if (id === "top") id = "home";
    if (VIEWS[id]) { e.preventDefault(); go(id); return; }
    const el = $(id); if (!el) return;
    const v = viewOf(el); if (!v) return;
    e.preventDefault(); go(v, id === "myunit" ? "unitWrap" : id);
  });
  window.addEventListener("popstate", (e) => { const s = e.state; if (s && s.v) go(s.v, s.t, false); else route(false); });
  function route(push) {
    const h = decodeURIComponent(location.hash.slice(1));
    if (VIEWS[h]) return go(h, null, push);
    const el = h && $(h);
    if (el && viewOf(el)) return go(viewOf(el), h, push);
    go("home", null, push);
  }
  route(false);
})();

;

/* ===== okane-course.js ===== */
// おかねの物差し：おすすめコース（順番に読む道案内）・文字の大きさ
(() => {
  const D = window, { $, esc, store } = D.OK;

  // ===== 文字の大きさ =====
  const setSize = (v) => { document.body.classList.toggle("bigtext", v === "big"); [...$("sizeSeg").children].forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.v === v))); store.set("size", v); };
  $("sizeSeg").addEventListener("click", (e) => { const b = e.target.closest("button"); if (b) setSize(b.dataset.v); });
  setSize(store.get("size", "normal"));

  // ===== おすすめコース =====
  const COURSES = [
    { id: "first", t: "はじめての10分コース", who: "小学生・はじめての人", c: "var(--ruler)", why: "値段を「自分がはたらく時間」ではかる、いちばん大事なところだけ。", steps: ["money", "try", "hours", "map", "rank", "quiz"] },
    { id: "news", t: "ニュースがわかるコース", who: "中学生・高校生", c: "var(--seg1)", why: "物価・円安・国の予算・消費税。ニュースによく出る言葉の意味がわかります。", steps: ["time", "race", "fx", "big", "tax", "words"] },
    { id: "future", t: "将来のお金コース", who: "中学生・高校生・大人", c: "var(--seg6)", why: "はたらいたら給料はいくら？ 何が引かれる？ どうやって貯める？", steps: ["agewage", "pay", "kakei", "save", "diary"] },
    { id: "study", t: "自由研究コース", who: "夏休みの宿題・授業の調べ学習", c: "var(--seg3)", why: "自分の数字を集めて、印刷できるワークシートにまとめます。", steps: ["mycard", "hours", "time", "diary", "sheet"] },
  ];
  const HOME_LABEL = { try: "ためしてみよう（換算機）", mycard: "あなたの物差しカード" };
  const plain = (el) => { if (!el) return ""; const c = el.cloneNode(true); c.querySelectorAll("rt").forEach((r) => r.remove()); return c.textContent.trim(); };
  function label(id) {
    if (HOME_LABEL[id]) return HOME_LABEL[id];
    const s = $(id); if (!s) return id;
    const n = s.querySelector(".rule-band span");
    return `${n ? n.textContent + " " : ""}${plain(s.querySelector(".ch-head h2"))}`;
  }
  // 短い名前は、上の章メニュー（はたらく時間・日本地図…）の名前を使う
  const SHORT_HOME = { try: "換算機", mycard: "物差しカード" };
  function shortLabel(id) {
    if (SHORT_HOME[id]) return SHORT_HOME[id];
    const a = document.querySelector(`#chapters a[href="#${id}"]`);
    if (!a) return id;
    const c = a.cloneNode(true); c.querySelectorAll(".n").forEach((n) => n.remove());
    return c.textContent.trim();
  }

  // 移動は、ページの切りかえのしくみ（リンクを押したとき）にまかせる
  const navA = document.createElement("a"); navA.hidden = true; document.body.appendChild(navA);
  const nav = (id) => { navA.href = "#" + id; navA.click(); };

  let state = store.get("course", null); // { id, i }
  const seen = () => store.get("courseSeen", {});
  function markSeen(cid, sid) { const s = seen(); s[cid] = Array.from(new Set([...(s[cid] || []), sid])); store.set("courseSeen", s); }

  function renderCards() {
    const s = seen();
    $("courseGrid").innerHTML = COURSES.map((c) => {
      const done = s[c.id] || [], active = state && state.id === c.id;
      return `<div class="course" style="--cc:${c.c}"><div class="ch-k"><span class="ttl">${c.t}</span><span class="who">${c.who}</span></div>
        <p class="why">${c.why}</p>
        <ol>${c.steps.map((st, k) => `<li class="${done.includes(st) ? "done" : ""}">${D.OK.icon ? D.OK.icon(st, 13) : ""}${k + 1}. ${esc(shortLabel(st))}</li>`).join("")}</ol>
        <div class="go"><span class="hint">${c.steps.length}つの章・約${c.steps.length * 2}分${done.length ? `・${done.length}つ読んだ` : ""}</span><button type="button" class="btn${active ? " ghost" : ""}" data-c="${c.id}">${active ? "つづきから" : done.length === c.steps.length ? "もう一度" : "はじめる"}</button></div></div>`;
    }).join("");
    $("courseGrid").querySelectorAll("button[data-c]").forEach((b) => b.addEventListener("click", () => {
      const c = COURSES.find((x) => x.id === b.dataset.c);
      if (!(state && state.id === c.id)) state = { id: c.id, i: 0 };
      store.set("course", state); go();
    }));
  }

  const bar = document.createElement("div"); bar.className = "course-bar"; bar.setAttribute("role", "navigation"); bar.setAttribute("aria-label", "コースの道案内"); bar.hidden = true;
  document.body.appendChild(bar);
  function renderBar() {
    if (!state) { bar.hidden = true; document.body.classList.remove("in-course"); return; }
    const c = COURSES.find((x) => x.id === state.id); if (!c) { state = null; return renderBar(); }
    const i = state.i, last = i === c.steps.length - 1;
    bar.hidden = false; document.body.classList.add("in-course");
    bar.innerHTML = `<div><div class="cb-t">${c.t}　${i + 1} / ${c.steps.length}</div><div class="cb-n">${esc(label(c.steps[i]))}</div><div class="cb-dots">${c.steps.map((_, k) => `<i class="${k <= i ? "on" : ""}"></i>`).join("")}</div></div>
      <div class="cb-b"><button type="button" class="pv" ${i === 0 ? "disabled" : ""}>← 前へ</button><button type="button" class="nx">${last ? "おわり" : "次へ →"}</button><button type="button" class="qt" aria-label="コースをやめる">×</button></div>`;
    bar.querySelector(".pv").addEventListener("click", () => { if (state.i > 0) { state.i--; store.set("course", state); go(); } });
    bar.querySelector(".nx").addEventListener("click", () => {
      if (last) { const name = c.t; state = null; store.set("course", null); renderBar(); renderCards(); nav("courses"); setTimeout(() => { const g = $("courseGrid"); g.insertAdjacentHTML("afterbegin", `<p class="easy" style="grid-column:1/-1"><span class="tag">コースかんりょう</span>「${esc(name)}」を最後まで読みました。おつかれさま！ ほかのコースもためしてみよう。</p>`); }, 50); return; }
      state.i++; store.set("course", state); go();
    });
    bar.querySelector(".qt").addEventListener("click", () => { state = null; store.set("course", null); renderBar(); renderCards(); });
  }
  function go() {
    const c = COURSES.find((x) => x.id === state.id), id = c.steps[state.i];
    markSeen(c.id, id); renderBar(); renderCards(); nav(id);
  }

  renderCards(); renderBar();
})();

;

/* ===== okane-quiz.js ===== */
// おかねの物差し：クイズ（5つのモード・いちばんよかった点数を記録）
(() => {
  const D = window, { $, yen, esc, store, sgn, cpiAt, hmText } = D.OK;
  const box = $("quizBox");
  const rnd = (n) => Math.floor(Math.random() * n);
  const pick = (arr) => arr[rnd(arr.length)];
  const shuffle = (a) => { for (let i = a.length - 1; i > 0; i--) { const j = rnd(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const pct = (a, b) => (b / a - 1) * 100;
  const N = 5;

  // それぞれのモードは「問題を1つ作る」関数。{ q, opts:[{t,s}], ans, why }
  const MODES = {
    rise: { t: "値上がりはどっち？", d: "10年間で、値上がりの割合が大きいのは？", make(used) {
      const pool = D.ITEMS.filter((i) => !i.n && !used.has(i.id)).map((i) => ({ ...i, c: pct(i.p15, i.p25) }));
      for (let g = 0; g < 300; g++) {
        const a = pick(pool), b = pick(pool);
        if (a.id === b.id || Math.abs(a.c - b.c) < 12) continue;
        used.add(a.id); used.add(b.id);
        return { q: "2015年から2025年までに、値上がりの割合が大きいのはどっち？", opts: [a, b].map((x) => ({ t: x.name, s: x.unit, r: `${yen(x.p15)}円 → ${yen(x.p25)}円（${sgn(x.c)}）` })), ans: a.c > b.c ? 0 : 1, why: `${(a.c > b.c ? a : b).name}のほうが大きく値上がりしました。` };
      }
    } },
    hours: { t: "何時間はたらく？", d: "あなたの時給で、買うのにかかる時間は？", make(used) {
      const pool = D.ITEMS.filter((i) => !used.has(i.id) && i.p25 >= 400);
      const it = pick(pool); used.add(it.id);
      const w = D.OK.wage(), h = it.p25 / w;
      const fmt = (x) => x >= 10 ? `約${Math.round(x)}時間` : hmText(x);
      const wrong = shuffle([0.4, 0.6, 1.7, 2.5]).slice(0, 2).map((k) => h * k);
      const all = shuffle([h, ...wrong]);
      return { q: `時給${yen(w)}円ではたらくと、「${it.name}（${it.unit}・${yen(it.p25)}円）」を買うには、何時間かかる？`, opts: all.map((x) => ({ t: fmt(x) })), ans: all.indexOf(h), why: `${yen(it.p25)}円 ÷ 時給${yen(w)}円 ＝ ${fmt(h)}です。` };
    } },
    map: { t: "日本地図クイズ", d: "最低賃金や物価が高いのはどっちの県？", make(used) {
      const kind = pick(["wage", "rpi"]);
      const v = kind === "wage" ? D.PREF_WAGE : D.RPI_TOTAL, min = kind === "wage" ? 25 : 1.5;
      for (let g = 0; g < 300; g++) {
        const a = rnd(47), b = rnd(47);
        if (a === b || used.has(a) || used.has(b) || Math.abs(v[a] - v[b]) < min) continue;
        used.add(a); used.add(b);
        const f = (i) => kind === "wage" ? `${yen(v[i])}円` : `${v[i].toFixed(1)}`;
        return { q: kind === "wage" ? "2026年度の最低賃金が高いのは、どっちの県？" : "くらし全体の物価（全国平均＝100）が高いのは、どっちの県？", opts: [a, b].map((i) => ({ t: D.OK.prefName(i), r: f(i) })), ans: v[a] > v[b] ? 0 : 1, why: `${D.OK.prefName(v[a] > v[b] ? a : b)}のほうが高くなっています。` };
      }
    } },
    past: { t: "昔の値段クイズ", d: "今の1,000円の買い物、昔ならいくら？", make(used) {
      let y; do { y = 1975 + rnd(36); } while (used.has(y)); used.add(y);
      const p = Math.round(1000 * cpiAt("総合", y) / 100 / 10) * 10;
      const w = shuffle([0.6, 0.75, 1.25, 1.45]).slice(0, 2).map((k) => Math.round(p * k / 10) * 10);
      const all = shuffle([p, ...w.filter((x) => x !== p && x !== 1000)]);
      while (all.length < 3) all.push(Math.round(p * 0.5 / 10) * 10);
      return { q: `今（2025年）なら1,000円の買い物は、${y}年ならだいたいいくら？`, opts: all.map((x) => ({ t: `${yen(x)}円` })), ans: all.indexOf(p), why: `${y}年の物価指数は${cpiAt("総合", y).toFixed(1)}（2025年＝100）なので、約${yen(p)}円です。` };
    } },
    idea: { t: "しくみクイズ", d: "税金・円安・給料のしくみ、わかるかな？", make(used) {
      const pool = IDEAS.map((x, k) => k).filter((k) => !used.has("i" + k)); if (!pool.length) return null;
      const k = pick(pool), x = IDEAS[k]; used.add("i" + k);
      const all = shuffle(x.o.map((t, j) => ({ t, ok: j === 0 })));
      return { q: x.q, opts: all.map((o) => ({ t: o.t })), ans: all.findIndex((o) => o.ok), why: x.why, link: x.ch };
    } },
  };
  // しくみクイズの問題（答えは o の1つめ）。数字は okane-data.js から
  const T = D.TAXREV, cho = (v) => (v / 1e12).toFixed(1) + "兆円", big = (id) => D.BIG.find((b) => b.id === id);
  const IDEAS = [
    { q: "おにぎりをお店で買って、持ち帰るときの消費税は？", o: ["8%", "10%", "5%"], why: "食べ物や飲み物（お酒と外食をのぞく）は「軽減税率」で8%です。", ch: "tax" },
    { q: "ハンバーガーを、お店の中で食べるときの消費税は？", o: ["10%", "8%", "0%"], why: "お店の中で食べると「外食」になるので10%。持ち帰れば8%です。", ch: "tax" },
    { q: "消費税10%のうち、国の分はどれだけ？", o: ["7.8%", "2.2%", "10%ぜんぶ"], why: "7.8%が国、2.2%が都道府県と市区町村の分です。", ch: "tax" },
    { q: `国の税金の収入（${T.note}）で、いちばん多いのは？`, o: ["消費税", "所得税", "法人税"], why: `消費税${cho(T.consumption)}、所得税${cho(T.income)}、法人税${cho(T.corporate)}。消費税がいちばん多くなっています。`, ch: "tax" },
    { q: "家計・会社・国のあいだを、お金が回っていくことを何という？", o: ["経済の循環", "物価", "為替"], why: "買い物の代金は会社へ、給料は家計へ、税金は国へ。お金はぐるぐるめぐっています。", ch: "tax" },
    { q: "給料が3%増えて、物価が4%上がった。買える物は？", o: ["少しへる", "少しふえる", "変わらない"], why: "金額（名目）は増えても、物価の上がり方のほうが大きいので、買える量（実質）はへります。", ch: "race" },
    { q: "物価が上がり続けることを何という？", o: ["インフレ", "デフレ", "円高"], why: "上がり続けるのがインフレ、下がり続けるのがデフレです。", ch: "words" },
    { q: "1ドル100円が、1ドル150円になった。これは？", o: ["円安", "円高", "どちらでもない"], why: "1ドルを買うのに、前より多くの円が必要になりました。円の値打ちが下がったので「円安」です。", ch: "fx" },
    { q: "円安になると、外国から買う物（輸入品）の値段は？", o: ["上がりやすい", "下がりやすい", "変わらない"], why: "同じ1ドルの品物を買うのに、より多くの円を払うことになるからです。", ch: "fx" },
    { q: "給料から、税金や保険料が引かれたあとの金額を何という？", o: ["手取り", "額面", "時給"], why: "会社が決めた金額が額面、引かれたあと口座に入るのが手取りです。", ch: "pay" },
    { q: `国の予算（${big("budget").short}）で、いちばん多い使い道は？`, o: ["社会保障（年金・医療など）", "国債費（借金の返済）", "公共事業（道路など）"], why: `社会保障が${big("social").short}でいちばん多く、次が国債費の${big("debtpay").short}です。`, ch: "big" },
    { q: "物価が毎年2%上がると、値段が2倍になるのは約何年後？", o: ["約36年後", "約72年後", "約10年後"], why: "72の法則で、72÷2＝36年。2%は日本銀行が目標にしている上がり方です。", ch: "save" },
    { q: "最低賃金は、どこごとに決まっている？", o: ["都道府県ごと", "市区町村ごと", "全国で1つ"], why: `都道府県ごとに毎年決まります。2026年度は${yen(D.MINWAGE_2026.min)}円から${yen(D.MINWAGE_2026.max)}円まで差があります。`, ch: "map" },
    { q: "使ったお金のうち、食べ物に使った割合を何という？", o: ["エンゲル係数", "消費者物価指数", "相関係数"], why: "食べ物は節約しにくいので、物価が上がると高くなりやすい数字です。", ch: "kakei" },
    { q: "お金の単位「円」が生まれたのは、いつ？", o: ["明治時代（1871年）", "江戸時代（1601年）", "昭和時代（1950年）"], why: "1871年の新貨条例で「円・銭・厘」が決まりました。江戸時代は小判などの「両」が使われていました。", ch: "money" },
    { q: "お札（日本銀行券）を発行しているのは？", o: ["日本銀行", "造幣局", "銀行ならどこでも"], why: "お札は日本銀行が発行し、国立印刷局が印刷します。硬貨は国が発行し、造幣局が作っています。", ch: "money" },
    { q: "「貨」「財」「買」など、お金に関係する漢字に入っている部分は？", o: ["貝", "金", "米"], why: "大昔、貝がらがお金の代わりに使われていたなごりです。", ch: "money" },
    { q: `国に入ってくるお金（${D.BUDGET ? D.BUDGET.label : "令和8年度予算"}）のうち、借金（公債金）はどれくらい？`, o: ["約4分の1", "約10分の1", "約半分"], why: "1万円にちぢめると2,419円が借金です。税金だけでは足りない分を、国債でおぎなっています。", ch: "big" },
    { q: "国から都道府県や市町村に配る「地方交付税」は、何のため？", o: ["どこに住んでも同じくらいのサービスを受けられるように", "国の借金を返すため", "外国を助けるため"], why: "税金が集まりやすい地域と、そうでない地域の差をならすためのお金です。", ch: "big" },
    { q: "お店やさんで「売り上げ − 材料代」がマイナスになることを何という？", o: ["赤字", "黒字", "利息"], why: "もうけが出るのが黒字、材料代などのほうが多いのが赤字です。", ch: "time" },
  ];

  let mode = store.get("quizMode", "rise"), qs = [], qi = 0, res = [], best = store.get("quizBest", {});
  function start(m) {
    mode = m; store.set("quizMode", m);
    const used = new Set(); qs = [];
    for (let k = 0; k < N; k++) { const q = MODES[m].make(used); if (q) qs.push(q); }
    qi = 0; res = []; render();
  }
  const dots = () => `<div class="dots" aria-hidden="true">${qs.map((_, i) => `<i class="${res[i] || ""}${i === qi && !res[i] ? " now" : ""}"></i>`).join("")}</div>`;
  const modeBar = () => `<div class="quiz-modes" role="tablist" aria-label="クイズのしゅるい">${Object.entries(MODES).map(([k, m]) => `<button type="button" role="tab" class="qm" data-m="${k}" aria-selected="${k === mode}"><b>${m.t}</b><span>${best[k] != null ? `ベスト ${best[k]}/${N}` : "まだ"}</span></button>`).join("")}</div>`;
  function bindModes() { box.querySelectorAll(".qm").forEach((b) => b.addEventListener("click", () => start(b.dataset.m))); }

  function render() {
    if (qi >= qs.length) {
      const ok = res.filter((r) => r === "ok").length, prev = best[mode];
      const rec = prev == null || ok > prev;
      if (rec) { best[mode] = ok; store.set("quizBest", best); }
      const msg = ok === N ? "全問正解！ 物差しはかせです。" : ok >= 3 ? "よくできました。答えの章で、もう一度たしかめてみよう。" : "意外な答えもありましたね。ほかのモードもためしてみよう。";
      box.innerHTML = `${modeBar()}<div class="quiz-top"><span class="hint">${MODES[mode].t}・けっか</span>${dots()}</div><div class="quiz-q">${N}問中 ${ok}問 正解${rec && ok > 0 ? '<span class="newrec">新記録！</span>' : ""}</div><p>${msg}</p><div class="share-row"><button type="button" class="btn" id="qAgain">もう一回（問題が変わります）</button></div>`;
      bindModes(); $("qAgain").addEventListener("click", () => start(mode)); $("qAgain").focus(); return;
    }
    const q = qs[qi];
    box.innerHTML = `${modeBar()}<div class="quiz-top"><span class="hint">${MODES[mode].t}・第${qi + 1}問 / ${N}問</span>${dots()}</div>
      <div class="quiz-q" id="qText">${esc(q.q)}</div>
      <div class="quiz-opts${q.opts.length === 3 ? " three" : ""}" role="group" aria-labelledby="qText">${q.opts.map((o, k) => `<button type="button" class="qopt" data-k="${k}"><span class="nm">${esc(o.t)}</span>${o.s ? `<span class="ut">${esc(o.s)}</span>` : ""}<span class="rv" hidden></span></button>`).join("")}</div>
      <div id="qAfter" aria-live="polite"></div>`;
    bindModes();
    box.querySelectorAll(".qopt").forEach((el) => el.addEventListener("click", () => answer(+el.dataset.k)));
  }
  function answer(k) {
    const q = qs[qi]; res[qi] = k === q.ans ? "ok" : "ng";
    box.querySelectorAll(".qopt").forEach((el, i) => {
      el.disabled = true; el.classList.add(i === q.ans ? "win" : "lose");
      const o = q.opts[i], rv = el.querySelector(".rv"); if (o.r) { rv.hidden = false; rv.textContent = o.r; }
    });
    box.querySelector(".dots").outerHTML = dots();
    const after = $("qAfter");
    const ln = q.link && $(q.link) ? ` <a class="q-link" href="#${q.link}">→ ${esc(($(q.link).querySelector(".ch-head h2") || {}).textContent || "答えの章")}</a>` : "";
    after.innerHTML = `<div class="q-say">${D.OK.mascot(k === q.ans ? "wow" : "think", 44)}<p><b>${k === q.ans ? "正解！" : "ざんねん！"}</b> ${esc(q.why)}${ln}</p></div>`;
    const nb = document.createElement("button"); nb.type = "button"; nb.className = "btn"; nb.textContent = qi < qs.length - 1 ? "次の問題" : "けっかを見る";
    nb.addEventListener("click", () => { qi++; render(); }); after.appendChild(nb); nb.focus();
  }
  start(MODES[mode] ? mode : "rise");

  // ===== みんなでクイズ（教室の大きな画面用）=====
  // 1問ずつ大きく出して、みんなで考えてから答えを見せる。キーボード：1〜3で選ぶ／Enterで答え／→で次へ／Escでとじる
  const bigEl = document.createElement("div"); bigEl.className = "bigq"; bigEl.hidden = true; bigEl.setAttribute("role", "dialog"); bigEl.setAttribute("aria-modal", "true"); bigEl.setAttribute("aria-label", "みんなでクイズ");
  document.body.appendChild(bigEl);
  let bm = "mix", bq = null, bn = 0, shown = false, picked = -1, bUsed = new Set();
  const L = ["A", "B", "C", "D"];
  function bNext() {
    const keys = Object.keys(MODES), m = bm === "mix" ? keys[rnd(keys.length)] : bm;
    bq = MODES[m].make(bUsed) || (bUsed = new Set(), MODES[m].make(bUsed)); bq.mt = MODES[m].t;
    bn++; shown = false; picked = -1; bRender();
  }
  function bRender() {
    const q = bq;
    bigEl.innerHTML = `<div class="bq-top"><div class="bq-modes">${[["mix", "ぜんぶまぜる"], ...Object.entries(MODES).map(([k, x]) => [k, x.t])].map(([k, t]) => `<button type="button" data-bm="${k}" aria-pressed="${k === bm}">${t}</button>`).join("")}</div>
        <div class="bq-tools"><button type="button" data-a="fs">全画面</button><button type="button" data-a="close" aria-label="とじる">✕ とじる</button></div></div>
      <div class="bq-body"><div class="bq-k">第${bn}問・${esc(q.mt)}</div><div class="bq-q">${esc(q.q)}</div>
        <div class="bq-opts n${q.opts.length}">${q.opts.map((o, i) => `<button type="button" class="bq-o${shown ? (i === q.ans ? " win" : " lose") : ""}${picked === i ? " pk" : ""}" data-i="${i}"><span class="bq-l">${L[i]}</span><span class="bq-t">${esc(o.t)}${o.s ? `<small>${esc(o.s)}</small>` : ""}</span>${shown && o.r ? `<span class="bq-r">${esc(o.r)}</span>` : ""}</button>`).join("")}</div>
        <div class="bq-foot">${shown ? `<div class="bq-why">${D.OK.mascot ? D.OK.mascot("wow", 56) : ""}<p><b>答え：${L[q.ans]}</b>　${esc(q.why)}</p></div><button type="button" class="btn" data-a="next">次の問題 →</button>` : `<span class="bq-hint">みんなで考えてから…</span><button type="button" class="btn" data-a="show">答えを見る</button>`}</div>
        <p class="bq-keys">キーボード：1〜${q.opts.length}で選ぶ ／ Enterで答え ／ →で次へ ／ Escでとじる</p></div>`;
  }
  function bOpen() { bn = 0; bUsed = new Set(); bigEl.hidden = false; document.body.classList.add("bigq-open"); bNext(); }
  function bClose() { bigEl.hidden = true; document.body.classList.remove("bigq-open"); if (document.fullscreenElement) document.exitFullscreen().catch(() => {}); }
  bigEl.addEventListener("click", (e) => {
    const b = e.target.closest("button"); if (!b) return;
    if (b.dataset.bm) { bm = b.dataset.bm; bn = 0; bNext(); return; }
    if (b.dataset.i != null && !shown) { picked = +b.dataset.i; bRender(); return; }
    const a = b.dataset.a;
    if (a === "show") { shown = true; bRender(); }
    else if (a === "next") bNext();
    else if (a === "close") bClose();
    else if (a === "fs") { if (document.fullscreenElement) document.exitFullscreen().catch(() => {}); else if (bigEl.requestFullscreen) bigEl.requestFullscreen().catch(() => {}); }
  });
  addEventListener("keydown", (e) => {
    if (bigEl.hidden) return;
    if (e.key === "Escape" && !document.fullscreenElement) { bClose(); return; }
    const n = parseInt(e.key, 10);
    if (n >= 1 && n <= bq.opts.length && !shown) { picked = n - 1; bRender(); }
    else if (e.key === "Enter" && !shown) { e.preventDefault(); shown = true; bRender(); }
    else if ((e.key === "ArrowRight" || e.key === " ") && shown) { e.preventDefault(); bNext(); }
  });
  const openBtn = $("bigQuizBtn"); if (openBtn) openBtn.addEventListener("click", bOpen);
})();

;

/* ===== okane-tour.js ===== */
// おかねの物差し：はじめての人への道案内ツアー（3ステップ）。最初に開いたときだけ自動で出る
(() => {
  const D = window, { $, store } = D.OK;
  const STEPS = [
    { sel: ".converter", t: "1. 値段を入れてみよう", d: "ここに値段を入れると、「はたらく時間」「おこづかい何か月」「おにぎり何個」に直ります。ためしに数字を変えてみてください。" },
    { sel: ".tabbar", t: "2. 画面を切りかえる", d: "ホームと、4つのパート（くらべる・さかのぼる・しくみ・たしかめる）を切りかえます。スマホでは画面の下、パソコンでは上にあります。" },
    { sel: "#courses", t: "3. 迷ったらコースから", d: "どこから読めばいいか迷ったら、おすすめコースを選ぶと、順番に案内します。はじめてなら「はじめての10分コース」がおすすめです。" },
  ];
  const veil = document.createElement("div"); veil.className = "tour-veil"; veil.hidden = true;
  const ring = document.createElement("div"); ring.className = "tour-ring"; ring.hidden = true;
  const tip = document.createElement("div"); tip.className = "tour-tip"; tip.hidden = true;
  tip.setAttribute("role", "dialog"); tip.setAttribute("aria-modal", "false"); tip.setAttribute("aria-labelledby", "tourTitle");
  document.body.append(veil, ring, tip);
  let i = 0, open = false;

  function place() {
    const s = STEPS[i], el = document.querySelector(s.sel); if (!el) return;
    // スマホでは下にタブバーがあるので、その上までを「見える場所」とする
    const bar = document.querySelector(".tabbar"), isBar = s.sel.includes("tabbar");
    const br = bar && !isBar ? bar.getBoundingClientRect() : null;
    const bottomLimit = br && br.top > innerHeight / 2 ? br.top - 8 : innerHeight - 8, pad = 8;
    const r = el.getBoundingClientRect(), top = Math.max(r.top, 8), bot = Math.min(r.bottom, bottomLimit);
    Object.assign(ring.style, { left: r.left - pad + "px", top: top - pad + "px", width: r.width + pad * 2 + "px", height: Math.max(0, bot - top) + pad * 2 + "px" });
    const tw = Math.min(360, innerWidth - 24), th = tip.offsetHeight;
    tip.style.width = tw + "px"; tip.style.left = Math.min(Math.max(12, r.left), innerWidth - tw - 12) + "px";
    // 下に入れば下、だめなら上、どちらも足りなければ画面の下のほうに重ねる
    let y;
    if (bot + pad + 12 + th <= bottomLimit) y = bot + pad + 12;
    else if (top - pad - 12 - th >= 8) y = top - pad - 12 - th;
    else y = bottomLimit - th - 4;
    tip.style.top = y + "px";
  }
  function show() {
    const s = STEPS[i], el = document.querySelector(s.sel);
    if (el && !s.sel.includes("tabbar")) {
      const tall = el.offsetHeight > innerHeight * 0.55;
      el.scrollIntoView({ block: tall ? "start" : "center", behavior: "instant" });
      // 上の見出しバーに隠れないように、少し下げる
      const hd = document.querySelector("header");
      if (tall && hd) scrollBy({ top: -(hd.getBoundingClientRect().bottom + 16), behavior: "instant" });
    }
    tip.innerHTML = `<div class="tt-k">${D.OK.mascot(i === STEPS.length - 1 ? "wow" : "smile", 34)}使い方 ${i + 1} / ${STEPS.length}</div><b id="tourTitle">${s.t}</b><p>${s.d}</p>
      <div class="tt-b"><button type="button" class="btn ghost" data-a="skip">とじる</button><button type="button" class="btn" data-a="next">${i === STEPS.length - 1 ? "はじめる" : "次へ"}</button></div>`;
    veil.hidden = ring.hidden = tip.hidden = false;
    requestAnimationFrame(() => { place(); tip.querySelector('[data-a="next"]').focus(); });
  }
  function start() {
    // ホームの画面で案内する
    const a = document.createElement("a"); a.href = "#home"; a.hidden = true; document.body.appendChild(a); a.click(); a.remove();
    i = 0; open = true; setTimeout(show, 80);
  }
  function close() { open = false; veil.hidden = ring.hidden = tip.hidden = true; store.set("toured", true); }
  tip.addEventListener("click", (e) => {
    const b = e.target.closest("button"); if (!b) return;
    if (b.dataset.a === "skip") return close();
    if (i < STEPS.length - 1) { i++; show(); } else close();
  });
  veil.addEventListener("click", close);
  addEventListener("keydown", (e) => { if (open && e.key === "Escape") close(); });
  addEventListener("resize", () => { if (open) place(); });
  addEventListener("scroll", () => { if (open) place(); }, { passive: true });

  // ホームの「使い方を見る」ボタン
  const btn = $("tourBtn"); if (btn) btn.addEventListener("click", start);
  // はじめて開いたとき（そして、ほかの章へのリンクから来たのではないとき）だけ自動で出す
  const h = location.hash.slice(1);
  const framed = (() => { try { return window.self !== window.top; } catch (e) { return true; } })();
  if (!framed && !store.get("toured", false) && (!h || h === "home")) setTimeout(start, 600);
})();

;

/* ===== okane-basket.js ===== */
// おかねの物差し：買い物かご。同じかごを買うのに、10年前と今で何分はたらく必要があるか
(() => {
  const D = window, { $, yen, esc, store, hmText, hmHTML, sgn } = D.OK;
  const W15 = D.MINWAGE[2015], W25 = D.MINWAGE[2025], WR = W25 / W15;
  const BY = Object.fromEntries(D.ITEMS.map((i) => [i.id, i]));
  const PRESETS = [
    { t: "朝ごはん", c: { bread: 1, egg: 1, milk: 1, banana: 1 } },
    { t: "おやつ", c: { choco: 1, chips: 1, gum: 1, pudding: 1 } },
    { t: "家族の買い物", c: { rice: 1, egg: 2, milk: 2, onion: 1, natto: 2, bread: 1 } },
    { t: "外食の日", c: { gyudon: 1, burger: 1, coffee: 2 } },
    { t: "あそびの日", c: { karaoke: 2, bowling: 2, water: 1 } },
  ];
  let cart = store.get("basket", null) || { ...PRESETS[0].c };

  const presets = $("bkPresets"), shelf = $("bkShelf"), out = $("bkResult");
  presets.innerHTML = PRESETS.map((p, i) => `<button type="button" class="chip" data-p="${i}">${p.t}</button>`).join("") +
    `<button type="button" class="chip" data-p="clear">からにする</button>`;
  shelf.innerHTML = Object.entries(D.GROUPS).map(([g, gt]) => `<div class="bk-g"><div class="bk-gt">${gt}</div><div class="bk-items">` +
    D.ITEMS.filter((i) => i.g === g).map((i) => `<button type="button" class="bk-it" data-id="${i.id}" title="${esc(i.unit)}"><span class="bk-n">${esc(i.name)}</span><span class="bk-p">${yen(i.p25)}円</span><span class="bk-c" aria-hidden="true"></span></button>`).join("") +
    `</div></div>`).join("");

  const add = (id, d) => { const n = (cart[id] || 0) + d; if (n <= 0) delete cart[id]; else cart[id] = Math.min(n, 20); save(); };
  const save = () => { store.set("basket", cart); render(); };
  presets.addEventListener("click", (e) => {
    const b = e.target.closest("button"); if (!b) return;
    cart = b.dataset.p === "clear" ? {} : { ...PRESETS[+b.dataset.p].c }; save();
  });
  shelf.addEventListener("click", (e) => { const b = e.target.closest(".bk-it"); if (b) add(b.dataset.id, 1); });
  out.addEventListener("click", (e) => { const b = e.target.closest("[data-d]"); if (b) add(b.dataset.id, +b.dataset.d); });

  function render() {
    const ids = Object.keys(cart).filter((id) => BY[id]);
    [...shelf.querySelectorAll(".bk-it")].forEach((b) => {
      const n = cart[b.dataset.id] || 0;
      b.classList.toggle("on", n > 0); b.querySelector(".bk-c").textContent = n ? "×" + n : "";
      b.setAttribute("aria-label", `${BY[b.dataset.id].name}をかごに入れる${n ? `（今${n}個）` : ""}`);
    });
    const now = JSON.stringify(cart);
    [...presets.children].forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.p !== "clear" && JSON.stringify(PRESETS[+b.dataset.p].c) === now)));
    if (!ids.length) { out.innerHTML = `<div class="bk-empty">${D.OK.mascot("think", 56)}かごは、からっぽです。<br>棚の品物を押して、かごに入れてみよう。</div>`; return; }

    const t15 = ids.reduce((s, id) => s + BY[id].p15 * cart[id], 0), t25 = ids.reduce((s, id) => s + BY[id].p25 * cart[id], 0);
    const h15 = t15 / W15, h25 = t25 / W25, diff = (h25 - h15) * 60, max = Math.max(h15, h25);
    const pr = (t25 / t15 - 1) * 100, wr = (WR - 1) * 100;
    const kind = diff > 0.5 ? "hard" : diff < -0.5 ? "easy" : "even";
    const verdict = kind === "hard"
      ? `今のほうが<b>${hmText(diff / 60)}長く</b>はたらかないと買えません。`
      : kind === "easy" ? `今のほうが<b>${hmText(-diff / 60)}短く</b>はたらけば買えます。` : `10年前と今で、はたらく時間はほとんど同じです。`;
    const why = kind === "hard"
      ? `かごの値段の上がり方（${sgn(pr)}）が、最低賃金の上がり方（${sgn(wr)}）より大きかったからです。`
      : kind === "easy" ? `最低賃金の上がり方（${sgn(wr)}）が、かごの値段の上がり方（${sgn(pr)}）より大きかったからです。` : `値段と最低賃金が、同じくらい上がりました。`;
    const bar = (y, t, h, w, cls) => `<div class="bk-row ${cls}"><div class="bk-y">${y}年<small>時給${yen(w)}円</small></div>
      <div class="bk-track"><i style="width:${(h / max) * 100}%"></i></div><div class="bk-v"><b>${hmHTML(h)}</b><small>${yen(t)}円</small></div></div>`;
    const rows = ids.map((id) => {
      const it = BY[id], r = it.p25 / it.p15, harder = r > WR;
      return `<li><span class="bk-ln"><span>${esc(it.name)}${it.n ? "<sup>※</sup>" : ""}</span><small>${esc(it.unit)}</small></span>
        <span class="bk-lp">${yen(it.p15)}→${yen(it.p25)}円</span>
        <span class="bk-tag ${harder ? "hard" : "easy"}">${harder ? "きつくなった" : "楽になった"}</span>
        <span class="bk-q"><button type="button" data-id="${id}" data-d="-1" aria-label="${esc(it.name)}を1つへらす">−</button><b>${cart[id]}</b><button type="button" data-id="${id}" data-d="1" aria-label="${esc(it.name)}を1つふやす">＋</button></span></li>`;
    }).join("");
    out.innerHTML = `<div class="bk-sum ${kind}">
        <div class="bk-k">このかごを買うのに、最低賃金ではたらく時間</div>
        ${bar(2015, t15, h15, W15, "old")}${bar(2025, t25, h25, W25, "new")}
        <p class="bk-verdict">${verdict}<br><span>${why}</span></p>
      </div>
      <ul class="bk-list" aria-label="かごの中身">${rows}</ul>
      <p class="bk-hint">「きつくなった」は、その品物の値段が最低賃金（${(WR).toFixed(2)}倍）より大きく上がったもの。何を買うかで、答えが変わります。</p>`;
  }
  render();
})();

;

/* ===== okane-flow.js ===== */
// おかねの物差し：お金のめぐり図（経済の循環）。家計・会社・国のあいだを、お金がどう回るかを順番に見る
(() => {
  const D = window, { $, yen } = D.OK;
  const box = $("flowBox"); if (!box) return;
  const K = D.KAKEI["消費支出"], KY = D.KAKEI_FIRST_YEAR + K.length - 1, T = D.TAXREV;
  const cho = (v) => (v / 1e12).toFixed(1) + "兆円";
  const big = (id) => D.BIG.find((b) => b.id === id);
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

  // 3つの登場人物
  const NODES = {
    home: { x: 130, y: 336, t: "家計", s: "わたしたちの家", c: "var(--seg1)" },
    firm: { x: 590, y: 336, t: "会社", s: "お店・会社", c: "var(--seg3)" },
    gov: { x: 360, y: 74, t: "国など", s: "国・都道府県・市区町村", c: "var(--good)" },
  };
  // お金の流れ（線の形・ラベルの位置）
  const FLOWS = {
    buy: { d: "M190 372 Q360 446 530 372", from: "home", to: "firm", t: "代金（買い物）", lx: 360, ly: 432 },
    wage: { d: "M530 300 Q360 232 190 300", from: "firm", to: "home", t: "給料", lx: 360, ly: 262 },
    taxH: { d: "M84 290 Q92 130 278 64", from: "home", to: "gov", t: "税金（所得税など）", lx: 96, ly: 168, a: "start" },
    taxF: { d: "M636 290 Q628 130 442 64", from: "firm", to: "gov", t: "税金（法人税・消費税）", lx: 624, ly: 168, a: "end" },
    pubH: { d: "M318 118 Q250 200 196 282", from: "gov", to: "home", t: "学校・道路・年金など", lx: 236, ly: 212, a: "end" },
    pubF: { d: "M402 118 Q470 200 524 282", from: "gov", to: "firm", t: "道路・港・安全など", lx: 484, ly: 212, a: "start" },
  };
  const STEPS = [
    { on: Object.keys(FLOWS), t: "お金は、ぐるぐるめぐっている",
      d: "わたしたちの家（家計）、お店や会社、国や市区町村。お金は、この3つのあいだを回っています。「次へ」で、あなたが払った1,100円の旅を追いかけてみよう。" },
    { on: ["buy"], t: "1. お店で買い物をする",
      d: "あなたがお店で1,100円のノートを買うと、そのお金はお店（会社）の売り上げになります。1,100円の中には、消費税100円が入っています。",
      f: [`${yen(K[K.length - 1] / 10000)}万円`, `1つの家（2人以上）が1年間に使うお金の平均（${KY}年・家計調査）`] },
    { on: ["taxF"], t: "2. お店が税金を納める",
      d: "お店は、あずかった消費税100円を、国などに納めます。会社のもうけには、法人税という税金もかかります。",
      f: [cho(T.consumption), `国に入る消費税（法人税は${cho(T.corporate)}）・${T.note}`] },
    { on: ["wage"], t: "3. はたらく人に給料をはらう",
      d: "お店は、売り上げの中から、品物の仕入れや家賃をはらい、はたらく人に給料をはらいます。お金が、また家計にもどってきました。",
      f: [`${yen(D.MINWAGE_2026.avg)}円`, "最低賃金（全国平均の時給）。これより安い時給で、人をやとってはいけません"] },
    { on: ["taxH"], t: "4. 給料から税金を納める",
      d: "給料をもらった人は、所得税や住民税を納めます。お店で買い物をするたびに、消費税も払います。",
      f: [cho(T.income), `国に入る所得税・${T.note}`] },
    { on: ["pubH", "pubF"], t: "5. 国が、みんなのために使う",
      d: "国や市区町村は、集めたお金で、学校・道路・警察・消防・病院・年金・子育ての手当などをまかないます。税金だけでは足りない分は、国債という借金でおぎなっています。",
      f: [big("budget").short, `国が1年間に使うお金。そのうち社会保障（年金・医療・介護・子育て）は${big("social").short}・${big("budget").note.split("（")[0]}`] },
    { on: ["buy", "wage"], t: "6. そして、また買い物へ",
      d: "給料や年金を受け取った人が、また買い物をします。こうしてお金がめぐることを「経済の循環（じゅんかん）」と言います。どこかで流れが止まると、ほかの所にも影響が出ます。" },
  ];
  let i = 0;

  const arrow = (k) => { const f = FLOWS[k], c = NODES[f.from].c;
    return `<g class="fl" data-k="${k}" style="--c:${c}"><path id="fp-${k}" d="${f.d}" class="fl-p" marker-end="url(#fl-ar-${f.from})"/>
      <text x="${f.lx}" y="${f.ly}" text-anchor="${f.a || "middle"}" class="fl-t">${f.t}</text>
      ${reduce ? "" : [0, 1, 2].map((j) => `<circle r="5" class="fl-dot"><animateMotion dur="2.4s" begin="${j * 0.8}s" repeatCount="indefinite"><mpath href="#fp-${k}"/></animateMotion></circle>`).join("")}</g>`; };
  const node = (k) => { const n = NODES[k], w = k === "gov" ? 196 : 150;
    return `<g class="fn" data-n="${k}" style="--c:${n.c}"><rect x="${n.x - w / 2}" y="${n.y - 34}" width="${w}" height="68" rx="18"/>
      <text x="${n.x}" y="${n.y - 2}" text-anchor="middle" class="fn-t">${n.t}</text><text x="${n.x}" y="${n.y + 20}" text-anchor="middle" class="fn-s">${n.s}</text></g>`; };
  const markers = Object.entries(NODES).map(([k, n]) => `<marker id="fl-ar-${k}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="${n.c}"/></marker>`).join("");

  box.innerHTML = `<div class="fl-stage"><svg viewBox="0 0 720 460" role="img" aria-labelledby="flowTitle" class="fl-svg"><defs>${markers}</defs>
      ${Object.keys(FLOWS).map(arrow).join("")}${Object.keys(NODES).map(node).join("")}</svg></div>
    <div class="fl-side"><div class="fl-k" id="flowK"></div><h4 id="flowH"></h4><p id="flowD"></p><div class="fl-fact" id="flowF"></div>
      <div class="fl-nav"><button type="button" class="btn ghost" id="flowPrev">前へ</button><div class="fl-dots" id="flowDots"></div><button type="button" class="btn" id="flowNext">次へ</button></div></div>`;

  function render() {
    const s = STEPS[i], all = i === 0;
    box.querySelectorAll(".fl").forEach((g) => { const on = s.on.includes(g.dataset.k); g.classList.toggle("on", on && !all); g.classList.toggle("dim", !on); g.classList.toggle("all", all); });
    const used = new Set(s.on.flatMap((k) => [FLOWS[k].from, FLOWS[k].to]));
    box.querySelectorAll(".fn").forEach((g) => g.classList.toggle("on", all || used.has(g.dataset.n)));
    $("flowK").textContent = all ? "お金のめぐり図" : `1,100円の旅 ${i} / ${STEPS.length - 1}`;
    $("flowH").textContent = s.t; $("flowD").textContent = s.d;
    $("flowF").innerHTML = s.f ? `<b>${s.f[0]}</b><span>${s.f[1]}</span>` : ""; $("flowF").hidden = !s.f;
    $("flowPrev").disabled = i === 0;
    $("flowNext").textContent = i === 0 ? "旅をはじめる" : i === STEPS.length - 1 ? "最初から" : "次へ";
    $("flowDots").innerHTML = STEPS.map((_, j) => `<button type="button" data-j="${j}" aria-label="${j === 0 ? "全体" : j + "番目"}を見る"${j === i ? ' aria-current="step"' : ""}></button>`).join("");
  }
  $("flowNext").addEventListener("click", () => { i = (i + 1) % STEPS.length; render(); });
  $("flowPrev").addEventListener("click", () => { if (i > 0) { i--; render(); } });
  $("flowDots").addEventListener("click", (e) => { const b = e.target.closest("[data-j]"); if (b) { i = +b.dataset.j; render(); } });
  const STEP_OF = { buy: 1, taxF: 2, wage: 3, taxH: 4, pubH: 5, pubF: 5 };
  box.addEventListener("click", (e) => { const g = e.target.closest(".fl"); if (g) { i = STEP_OF[g.dataset.k]; render(); } });
  render();
})();

;

/* ===== okane-badges.js ===== */
// おかねの物差し：チャレンジバッジ。読むだけでなく「やってみた」ことで、もらえるバッジ
(() => {
  const D = window, { $, store, icon } = D.OK;
  const box = $("badgeGrid"); if (!box) return;
  const B = [
    { id: "first", ic: "hours", t: "はじめの一歩", d: "ホームで、値段を入れてみた", go: "home" },
    { id: "map", ic: "map", t: "地図たんけん", d: "日本地図で、都道府県を選んだ", go: "map" },
    { id: "detective", ic: "race", t: "値上がりたんてい", d: "10年前より、はたらく時間が長くなる買い物かごを見つけた", go: "race" },
    { id: "journey", ic: "tax", t: "1,100円の旅人", d: "お金のめぐり図で、1,100円の旅を最後まで見た", go: "tax" },
    { id: "perfect", ic: "quiz", t: "クイズ名人", d: "どれかのクイズで、5問ぜんぶ正解した", go: "quiz" },
    { id: "allmodes", ic: "words", t: "全モード制覇", d: "クイズを、5つのモードぜんぶで遊んだ", go: "quiz" },
    { id: "card", ic: "save", t: "わたしの物差し", d: "物差しカードを、画像か文章で保存した", go: "mycard" },
    { id: "course", ic: "sheet", t: "コース完走", d: "おすすめコースを、1つ最後まで進んだ", go: "courses" },
    { id: "shop", ic: "pay", t: "ジュース屋の店長", d: "お店やさんゲームで、5日間のもうけが1万円をこえた", go: "time" },
    { id: "hakase", ic: "stamps", t: "物差しはかせ", d: "スタンプを、ぜんぶあつめた", go: "stamps" },
  ];
  let got = new Set(store.get("badges", []));

  // バッジをもらったときのお知らせ
  const toast = document.createElement("div"); toast.className = "badge-toast"; toast.setAttribute("role", "status"); toast.hidden = true;
  document.body.appendChild(toast);
  let tt;
  function give(id) {
    if (got.has(id)) return;
    const b = B.find((x) => x.id === id); if (!b) return;
    got.add(id); store.set("badges", [...got]); render(id);
    toast.innerHTML = `<span class="bt-ic">${icon(b.ic, 22)}</span><span><small>バッジをゲット！</small><b>${b.t}</b></span>`;
    toast.hidden = false; toast.classList.remove("show"); void toast.offsetWidth; toast.classList.add("show");
    clearTimeout(tt); tt = setTimeout(() => { toast.hidden = true; }, 3600);
  }
  D.OK.badge = give; D.OK.badgeTotal = B.length;

  function render(popId) {
    box.innerHTML = B.map((b) => { const on = got.has(b.id);
      return `<a class="badge${on ? " on" : ""}${popId === b.id ? " pop" : ""}" href="#${b.go}"><span class="bd-medal">${icon(b.ic, 30)}</span>
        <span class="bd-t">${on ? b.t : "？？？"}</span><span class="bd-d">${b.d}</span></a>`; }).join("");
    $("badgeCount").textContent = `${got.size} / ${B.length}`;
  }
  render();

  // 「やってみた」の見つけ方。ほかのプログラムには手を入れず、画面の変化を見て判断する
  const later = (fn) => setTimeout(fn, 60);
  $("heroPrice").addEventListener("input", () => give("first"));
  $("heroChips").addEventListener("click", (e) => { if (e.target.closest("button")) give("first"); });
  document.addEventListener("click", (e) => {
    const t = e.target;
    if (t.closest("#mapSvg .tile, #mapRank button")) give("map");
    if (t.closest("#basket")) later(() => { if (document.querySelector("#bkResult .bk-sum.hard")) give("detective"); });
    if (t.closest("#flowBox")) later(() => { if (/6 \/ 6/.test($("flowK").textContent)) give("journey"); });
    if (t.closest("#quizBox")) later(() => {
      const q = document.querySelector("#quizBox .quiz-q");
      if (q && /5問中 5問/.test(q.textContent)) give("perfect");
      if (Object.keys(store.get("quizBest", {})).length >= 5) give("allmodes");
    });
    if (t.closest("#mcSave, #mcCopy, #mcShare")) give("card");
    const nx = t.closest(".nx"); if (nx && nx.textContent.trim() === "おわり") give("course");
  }, true);
  const stampsDone = () => { const all = document.querySelectorAll("#stampGrid .stamp").length; if (all && document.querySelectorAll("#stampGrid .stamp.got").length === all) give("hakase"); };
  document.addEventListener("okane:stamp", stampsDone); stampsDone();
  if (Object.keys(store.get("quizBest", {})).length >= 5) give("allmodes");
})();

;

/* ===== okane-resume.js ===== */
// おかねの物差し：ホームの「つづきから」。前に読んでいた章・進みぐあい・次のおすすめ
(() => {
  const D = window, { $, store, esc } = D.OK;
  const box = $("resume"); if (!box) return;
  const title = (id) => { const h = $(id) && $(id).querySelector(".ch-head h2"); if (!h) return ""; const c = h.cloneNode(true); c.querySelectorAll("rt").forEach((r) => r.remove()); return c.textContent.trim(); };
  const num = (id) => { const b = $(id) && $(id).querySelector(".rule-band span"); return b ? b.textContent : ""; };
  // スタンプの章の順番（スタンプラリーの並びと同じ）
  const order = () => [...document.querySelectorAll("#stampGrid .stamp")].map((a) => a.getAttribute("href").slice(1));

  // 読んでいる章を覚える（画面のまん中に1.2秒あったら）
  if ("IntersectionObserver" in window) {
    const timers = {};
    const io = new IntersectionObserver((ents) => ents.forEach((e) => {
      const id = e.target.id;
      if (e.isIntersecting) timers[id] = setTimeout(() => { if (store.get("lastCh") !== id) { store.set("lastCh", id); } }, 1200);
      else clearTimeout(timers[id]);
    }), { rootMargin: "-45% 0px -45% 0px", threshold: 0 });
    order().forEach((id) => { const el = $(id); if (el) io.observe(el); });
  }

  function ring(n, all) {
    const r = 30, c = 2 * Math.PI * r, f = all ? n / all : 0;
    return `<svg class="rs-ring" viewBox="0 0 76 76" aria-hidden="true"><circle cx="38" cy="38" r="${r}" class="bg"/><circle cx="38" cy="38" r="${r}" class="fg" stroke-dasharray="${(c * f).toFixed(1)} ${c.toFixed(1)}" transform="rotate(-90 38 38)"/></svg>`;
  }
  function render() {
    const ids = order(), stamps = new Set(store.get("stamps", [])), badges = store.get("badges", []).length;
    const last = store.get("lastCh", null), got = ids.filter((id) => stamps.has(id)).length;
    // はじめての人には出さない
    if (!last && !got) { box.hidden = true; return; }
    box.hidden = false;
    const next = ids.find((id) => !stamps.has(id) && id !== last);
    const card = (id, k, btn, cls) => `<a class="rs-card ${cls}" href="#${id}"><span class="rs-k">${k}</span>
      <span class="rs-t"><span class="rs-n">${esc(num(id))}</span>${esc(title(id))}</span><span class="rs-go">${btn} →</span></a>`;
    box.innerHTML = `<div class="rs-prog"><div class="rs-ringwrap">${ring(got, ids.length)}<span class="rs-pct"><b>${got}</b>/${ids.length}</span></div>
        <div><span class="rs-hi">おかえりなさい</span><span class="rs-sub">スタンプ ${got}/${ids.length}・バッジ ${badges}/${D.OK.badgeTotal || 10}</span></div></div>
      ${last && $(last) ? card(last, "つづきから", "つづきを読む", "last") : ""}
      ${next ? card(next, "まだ読んでいない章", "読んでみる", "next") : `<a class="rs-card next" href="#stamps"><span class="rs-k">ぜんぶ読みました！</span><span class="rs-t">チャレンジバッジをあつめよう</span><span class="rs-go">バッジを見る →</span></a>`}`;
  }
  render();
  document.addEventListener("okane:stamp", render);
  // ホームにもどったときに、新しい内容にする
  addEventListener("hashchange", () => { const h = location.hash.slice(1); if (!h || h === "home") render(); });
  addEventListener("popstate", render);
  document.addEventListener("click", (e) => { const a = e.target.closest('a[href="#home"]'); if (a) setTimeout(render, 30); });
})();

;

/* ===== okane-market.js ===== */
// おかねの物差し：値段の決まり方（需要と供給）。2本の線が交わる所で値段が決まる、しくみの模型
(() => {
  const D = window, { $, yen } = D.OK;
  const box = $("mkBox"); if (!box) return;
  const it = (id) => D.ITEMS.find((i) => i.id === id);
  const rice = it("rice"), pen = it("pen");
  // ほしい人：P = 200 − Q + 40d ／ 売りたい量：P = Q − 40s（いつも＝値段100・量100）
  const SC = [
    { t: "いつも", d: 0, s: 0, why: "ほしい人の線と、売りたい量の線が交わる所で、値段と売れる量が決まります。下の2つのつまみを動かしてみよう。" },
    { t: "不作でとれない", d: 0, s: -2, why: `天気が悪くて、とれる量がへると、売りたい量の線が左へ動き、値段が上がります。お米5kgは、2015年の${yen(rice.p15)}円から2025年は${yen(rice.p25)}円になりました（東京23区）。理由はいくつも重なっていますが、「売る量がへると値段が上がる」のが基本のしくみです。` },
    { t: "原料が高くなった", d: 0, s: -1, why: "円安などで、外国から買う原料や電気代が高くなると、同じ値段では売れなくなり、売りたい量の線が左へ動きます。値段は上がり、売れる量はへります。", link: "fx" },
    { t: "大人気になった", d: 2, s: 0, why: "テレビやSNSで話題になって、ほしい人がふえると、ほしい人の線が右へ動きます。値段が上がり、売れる量もふえます。" },
    { t: "たくさん作れる", d: 0, s: 2, why: `工場でたくさん作れるようになったり、売る店がふえて競争したりすると、売りたい量の線が右へ動き、値段は下がります。消せるボールペンは、2015年の${yen(pen.p15)}円から2025年は${yen(pen.p25)}円で、10年間ほとんど変わっていません。` },
    { t: "ブームが去った", d: -2, s: 0, why: "ほしい人がへると、ほしい人の線が左へ動きます。お店は売れ残らないように、値段を下げます。" },
  ];
  let d = 0, s = 0, sc = 0;
  const W = 520, H = 300, M = { l: 44, r: 16, t: 30, b: 40 }, QX = 200, PY = 260;
  const x = (q) => M.l + (q / QX) * (W - M.l - M.r), y = (p) => H - M.b - (p / PY) * (H - M.t - M.b);
  const eq = (d, s) => { const q = 100 + 20 * d + 20 * s; return { q, p: 200 - q + 40 * d }; };
  // 線をグラフのわくの中だけで描く
  const seg = (f) => { const pts = []; for (let q = 0; q <= QX; q += 2) { const p = f(q); if (p >= 0 && p <= PY) pts.push(`${x(q).toFixed(1)},${y(p).toFixed(1)}`); } return pts.join(" "); };

  box.innerHTML = `<div class="chips mk-sc" id="mkSc" aria-label="こんなとき、どうなる？">${SC.map((c, i) => `<button type="button" class="chip" data-i="${i}">${c.t}</button>`).join("")}</div>
    <div class="mk-body">
      <div class="mk-chart"><svg viewBox="0 0 ${W} ${H}" id="mkSvg" role="img" aria-label="ほしい人と売りたい量のグラフ"></svg></div>
      <div class="mk-side">
        <div class="mk-out"><span class="mk-k">値段</span><b id="mkP">—</b><span class="mk-k">売れる量</span><b id="mkQ">—</b></div>
        <label class="mk-sl"><span>ほしい人（需要）<em id="mkDl"></em></span><input type="range" id="mkD" min="-2" max="2" step="0.5" value="0"><span class="mk-ends"><i>へる</i><i>ふえる</i></span></label>
        <label class="mk-sl s"><span>売りたい量（供給）<em id="mkSl"></em></span><input type="range" id="mkS" min="-2" max="2" step="0.5" value="0"><span class="mk-ends"><i>へる</i><i>ふえる</i></span></label>
        <p class="mk-why" id="mkWhy" aria-live="polite"></p>
      </div>
    </div>`;

  const lvl = (v) => v === 0 ? "いつも" : v > 0 ? (v >= 1.5 ? "とてもふえる" : "ふえる") : (v <= -1.5 ? "とてもへる" : "へる");
  function render() {
    const e = eq(d, s), b = eq(0, 0);
    let g = "";
    [50, 100, 150, 200, 250].forEach((p) => { g += `<line x1="${M.l}" x2="${W - M.r}" y1="${y(p)}" y2="${y(p)}" class="mk-grid"/>`; });
    g += `<line x1="${M.l}" x2="${W - M.r}" y1="${y(100)}" y2="${y(100)}" class="mk-base"/><text x="${W - M.r}" y="${y(100) - 6}" text-anchor="end" class="mk-ax">いつもの値段</text>`;
    g += `<text x="${M.l}" y="22" class="mk-ax">値段 ↑</text><text x="${W - M.r}" y="${H - 10}" text-anchor="end" class="mk-ax">売れる量 →</text>`;
    // いつもの線（うすく）
    if (d !== 0) g += `<polyline points="${seg((q) => 200 - q)}" class="mk-ghost dm"/>`;
    if (s !== 0) g += `<polyline points="${seg((q) => q)}" class="mk-ghost sp"/>`;
    g += `<polyline points="${seg((q) => 200 - q + 40 * d)}" class="mk-line dm"/><polyline points="${seg((q) => q - 40 * s)}" class="mk-line sp"/>`;
    g += `<text x="${x(50)}" y="${y(150 + 40 * d) - 10}" class="mk-lb dm">ほしい人</text>`;
    const lq = Math.min(QX - 4, 230 + 40 * s); g += `<text x="${x(lq)}" y="${y(lq - 40 * s) - 8}" text-anchor="end" class="mk-lb sp">売りたい量</text>`;
    g += `<line x1="${M.l}" x2="${x(e.q)}" y1="${y(e.p)}" y2="${y(e.p)}" class="mk-guide"/><line x1="${x(e.q)}" x2="${x(e.q)}" y1="${y(e.p)}" y2="${H - M.b}" class="mk-guide"/>`;
    if (d || s) g += `<circle cx="${x(b.q)}" cy="${y(b.p)}" r="5" class="mk-dot0"/>`;
    g += `<circle cx="${x(e.q)}" cy="${y(e.p)}" r="9" class="mk-dot"/>`;
    $("mkSvg").innerHTML = g;
    const r = e.p / 100, qr = e.q / 100;
    $("mkP").innerHTML = r === 1 ? "いつも通り" : `いつもの<span class="${r > 1 ? "up" : "dn"}">${r.toFixed(1)}倍</span>`;
    $("mkQ").textContent = qr === 1 ? "いつも通り" : `いつもの${qr.toFixed(1)}倍`;
    $("mkDl").textContent = lvl(d); $("mkSl").textContent = lvl(s);
    const c = SC[sc], match = c && c.d === d && c.s === s;
    const gen = r > 1.001 ? "値段が上がりました。" : r < 0.999 ? "値段が下がりました。" : "値段は、いつもと同じです。";
    $("mkWhy").innerHTML = match ? c.why + (c.link ? ` <a href="#${c.link}">→ 円安の章へ</a>` : "") : `${gen}ほしい人が多いほど、また売りたい量が少ないほど、値段は上がります。`;
    [...$("mkSc").children].forEach((b, i) => b.setAttribute("aria-pressed", String(match && i === sc)));
  }
  $("mkSc").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; sc = +b.dataset.i; d = SC[sc].d; s = SC[sc].s; $("mkD").value = d; $("mkS").value = s; render(); });
  $("mkD").addEventListener("input", (e) => { d = +e.target.value; render(); });
  $("mkS").addEventListener("input", (e) => { s = +e.target.value; render(); });
  render();
})();

;

/* ===== okane-faq.js ===== */
// おかねの物差し：ものさしくんの なぜなに相談室（子どもがよく思うお金の疑問に、会話の形で答える）
(() => {
  const D = window, { $, yen, esc } = D.OK;
  const box = $("faqList"); if (!box) return;
  const kid = `<svg class="kid" width="40" height="40" viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="20" r="18" fill="var(--seg1)"/><path d="M5 16q4-12 15-12t15 12q-6-6-15-5t-15 5z" fill="var(--ruler-ink)" opacity=".85"/><circle cx="14.5" cy="21" r="2.2" fill="#fff"/><circle cx="25.5" cy="21" r="2.2" fill="#fff"/><path d="M15 28q5 3.5 10 0" stroke="#fff" stroke-width="2" fill="none" stroke-linecap="round"/></svg>`;
  const hm = (ch) => { const h = $(ch) && $(ch).querySelector(".ch-head h2"); if (!h) return ""; const c = h.cloneNode(true); c.querySelectorAll("rt").forEach((r) => r.remove()); return c.textContent.trim(); };
  const rice = D.ITEMS.find((i) => i.id === "rice");
  const QA = [
    { q: "お金をたくさん印刷すれば、みんなお金持ちになれる？", mood: "think",
      a: ["ざんねん、なれないんだ。お金がふえても、パンやお米の数はふえないよね。同じ数の品物を、たくさんのお金で取り合うことになるから、値段が上がっていくんだ（インフレ）。", "昔、お金を刷りすぎて、物の値段が何万倍にもなってしまった国もあるよ。だから日本では、お札を出す日本銀行が、世の中のお金の量を考えながら調整しているんだ。"], ch: "time" },
    { q: "銀行は、どうやってもうけているの？", mood: "smile",
      a: ["みんなが預けたお金を、家を建てたい人や、お店を広げたい会社に貸しているんだ。貸したお金には利息をつけて返してもらう。", "預けた人に払う利息より、借りた人からもらう利息を少し高くしていて、その差が銀行のもうけになるよ。"], ch: "save" },
    { q: "同じジュースなのに、コンビニとスーパーで値段がちがうのはなぜ？", mood: "smile",
      a: ["お店ごとに、かかるお金がちがうからなんだ。24時間開けておくための人の給料、駅前の高い家賃、一度にたくさん仕入れられるかどうか、などだね。", "コンビニで少し高く払うのは、「近くて、いつでも買える便利さ」にお金を払っているとも言えるよ。ほしい人と売りたい量のつり合いでも、値段は動くんだ。"], ch: "time", lb: "値段は、どうやって決まる？（第4章）" },
    { q: "税金がなかったら、どうなるの？", mood: "wow",
      a: ["学校、道路、信号、警察、消防、ごみの収集……。今は税金でまかなっているものに、使うたびに自分でお金を払うことになるかもしれない。", "たとえば日本では、救急車をよんでもお金はかからないよね。これも税金のおかげなんだ。みんなで少しずつ出しあって、だれでも使えるようにしているのが税金のしくみだよ。"], ch: "tax" },
    { q: "給料って、だれがどうやって決めているの？", mood: "smile",
      a: ["はたらく会社が決めているよ。仕事のむずかしさ、経験の長さ、そしてその仕事をする人が足りているかどうか（ここでも需要と供給！）で変わるんだ。", `ただし、どんな会社でも、最低賃金より安くしてはいけないという決まりがある。2026年度の全国平均は時給${yen(D.MINWAGE_2026.avg)}円だよ。`], ch: "agewage" },
    { q: "物価は「少しずつ上がるのがいい」って本当？", mood: "think",
      a: ["日本銀行は、物価が1年に2%くらいずつ上がるのを目標にしているよ。物がよく売れて会社がもうかり、給料も上がり、またみんなが買い物をする……という流れが回りやすいと考えられているからなんだ。", "反対に、物価が下がり続ける（デフレ）と、「待てばもっと安くなる」と買うのをひかえたり、会社のもうけがへって給料が上がりにくくなったりするよ。ただ、上がりすぎも困るし、給料が追いつかないとくらしは苦しくなる。ちょうどいい上がり方がむずかしいんだ。"], ch: "race" },
    { q: "円安って、いいこと？ わるいこと？", mood: "think",
      a: ["どちらとも言えないんだ。円安になると、外国から買うもの（ガソリンの原料や小麦など）が高くなって、買う人には苦しい。", "でも、外国に物を売る会社にとってはもうけがふえやすいし、日本に旅行に来る外国の人もふえやすい。だれの立場から見るかで、答えが変わるんだね。"], ch: "fx" },
    { q: "お米が急に高くなったのはどうして？", mood: "think",
      a: [`お米5kgは、2015年の平均${yen(rice.p15)}円から、2025年は${yen(rice.p25)}円になったよ（東京23区）。`, "夏の暑さで質のよいお米が少なかったことや、お米が店にとどくまでの流れの変化など、いくつもの理由が重なったと言われているんだ。どれか1つだけが原因、と決めつけないことが大切だよ。"], ch: "rank" },
  ];
  box.innerHTML = QA.map((x, i) => `<details class="faq"${i === 0 ? " open" : ""}><summary><span class="fq-kid">${kid}</span><span class="fq-q">${esc(x.q)}</span><span class="fq-pl" aria-hidden="true"></span></summary>
    <div class="fq-a"><span class="fq-m">${D.OK.mascot(x.mood, 44)}</span><div class="fq-bub">${x.a.map((p) => `<p>${p}</p>`).join("")}${x.ch && $(x.ch) ? `<a class="fq-go" href="#${x.ch}">→ ${esc(x.lb || hm(x.ch))}</a>` : ""}</div></div></details>`).join("");
})();

;

/* ===== okane-shop.js ===== */
// おかねの物差し：お店やさんゲーム。天気を見て、ジュースの値段と作る数を決める（5日間）
(() => {
  const D = window, { $, yen, store } = D.OK;
  const box = $("shopBox"); if (!box) return;
  const COST = 50, DAYS = 5;
  const WX = [
    { t: "暑い日", w: 1.7, ic: "☀︎", c: "var(--hot)" },
    { t: "晴れ", w: 1.3, ic: "☀︎", c: "var(--ruler)" },
    { t: "くもり", w: 1.0, ic: "☁︎", c: "var(--muted)" },
    { t: "雨", w: 0.5, ic: "☂︎", c: "var(--cool)" },
  ];
  let day, total, log, wx, price, make, phase;
  const pickWx = () => { const r = Math.random(); return r < 0.2 ? 0 : r < 0.5 ? 1 : r < 0.8 ? 2 : 3; };
  // お客さんの数：値段が安いほど、天気がよいほどふえる（しくみの模型）
  const demand = (p, w) => Math.max(0, Math.round(60 * w * Math.max(0, 1 - (p - 40) / 260) * (0.9 + Math.random() * 0.2)));

  function start() { day = 1; total = 0; log = []; price = store.get("shopPrice", 150); make = store.get("shopMake", 30); wx = pickWx(); phase = "plan"; render(); }
  const cups = (sold, left) => `<div class="sp-cups" aria-hidden="true">${"<i class=\"s\"></i>".repeat(Math.min(sold, 80))}${"<i class=\"l\"></i>".repeat(Math.min(left, 80))}</div>`;
  const hint = (r) => {
    if (r.lost >= 6 && r.left === 0) return ["wow", `${r.lost}人のお客さんが、買えずに帰ってしまったよ。もっと作るか、値段を少し上げてもよかったかも。`];
    if (r.left >= 8) return ["think", `${r.left}杯が売れ残って、材料代${yen(r.left * COST)}円がむだになったよ。天気を見て、作る数を考えよう。`];
    if (r.price >= 230 && r.sold < 15) return ["think", "値段が高すぎて、お客さんが少なかったみたい。"];
    if (r.price <= 80) return ["think", "安くしすぎると、たくさん売れても、もうけは少なくなるよ。材料代は1杯50円だからね。"];
    return ["smile", "いい感じ！ 売れる数と作る数が、だいたい合っていたね。"];
  };

  function render() {
    const W = WX[wx];
    const head = `<div class="sp-top"><div class="sp-day">${phase === "end" ? "けっか" : `${day}日目 <small>/ ${DAYS}日</small>`}</div><div class="sp-total"><span>今までのもうけ</span><b class="${total < 0 ? "neg" : ""}">${total < 0 ? "−" : ""}${yen(Math.abs(total))}円</b></div></div>`;
    if (phase === "end") {
      const best = store.get("shopBest", null), rec = best == null || total > best;
      if (rec) store.set("shopBest", total);
      if (total >= 10000 && D.OK.badge) D.OK.badge("shop");
      box.innerHTML = `${head}<div class="sp-end"><span class="sp-m">${D.OK.mascot(total > 0 ? "wow" : "think", 64)}</span><div>
        <p class="sp-big">5日間のもうけは <b>${total < 0 ? "−" : ""}${yen(Math.abs(total))}円</b>${rec ? '<span class="newrec">新記録！</span>' : ""}</p>
        <p>${total >= 10000 ? "すごい！ 天気と値段をよく考えた、りっぱな店長です。" : total > 0 ? "黒字（もうけが出た）です。天気が悪い日は作る数をへらすと、もっともうかるよ。" : "赤字（材料代のほうが多い）でした。作りすぎや、安くしすぎに気をつけよう。"}</p>
        <p class="sp-note">ベスト記録：${yen(Math.max(total, best ?? total))}円。1万円をこえると、バッジ「ジュース屋の店長」がもらえます。</p>
        <button type="button" class="btn" id="spAgain">もう一回あそぶ</button></div></div>
        <ol class="sp-log">${log.map((r, i) => `<li><b>${i + 1}日目</b>${WX[r.wx].t}・${r.price}円・${r.make}杯 → ${r.sold}杯売れた <span class="${r.profit < 0 ? "neg" : ""}">${r.profit < 0 ? "−" : "+"}${yen(Math.abs(r.profit))}円</span></li>`).join("")}</ol>`;
      $("spAgain").addEventListener("click", start); return;
    }
    if (phase === "plan") {
      box.innerHTML = `${head}<div class="sp-plan">
        <div class="sp-wx" style="--c:${W.c}"><span class="sp-ic" aria-hidden="true">${W.ic}</span><div><small>${day}日目の天気予報</small><b>${W.t}</b><span>${W.w > 1.2 ? "のどがかわく人が多そう！" : W.w < 0.8 ? "外を歩く人が少なそう…" : "ふつうの日"}</span></div></div>
        <label class="sp-sl"><span>1杯の値段 <b id="spPv">${price}円</b></span><input type="range" id="spP" min="50" max="300" step="10" value="${price}"></label>
        <label class="sp-sl"><span>作る数 <b id="spMv">${make}杯</b><em id="spCost">材料代 ${yen(make * COST)}円</em></span><input type="range" id="spM" min="0" max="100" step="5" value="${make}"></label>
        <button type="button" class="btn" id="spGo">お店をあける</button>
        <p class="sp-note">材料代は1杯${COST}円。売れ残っても、材料代はもどってきません。</p></div>`;
      const P = $("spP"), M = $("spM");
      P.addEventListener("input", () => { price = +P.value; $("spPv").textContent = price + "円"; });
      M.addEventListener("input", () => { make = +M.value; $("spMv").textContent = make + "杯"; $("spCost").textContent = `材料代 ${yen(make * COST)}円`; });
      $("spGo").addEventListener("click", () => {
        store.set("shopPrice", price); store.set("shopMake", make);
        const want = demand(price, W.w), sold = Math.min(want, make);
        const r = { wx, price, make, want, sold, left: make - sold, lost: Math.max(0, want - make), profit: sold * price - make * COST };
        total += r.profit; log.push(r); phase = "result"; render();
      });
      return;
    }
    const r = log[log.length - 1], [mood, msg] = hint(r);
    box.innerHTML = `${head}<div class="sp-res">
      <div class="sp-row"><div><small>来たお客さん</small><b>${r.want}人</b></div><div><small>売れた</small><b>${r.sold}杯</b></div><div><small>売れ残り</small><b>${r.left}杯</b></div><div><small>この日のもうけ</small><b class="${r.profit < 0 ? "neg" : "pos"}">${r.profit < 0 ? "−" : "+"}${yen(Math.abs(r.profit))}円</b></div></div>
      ${cups(r.sold, r.left)}
      <p class="sp-calc">売り上げ ${yen(r.sold * r.price)}円（${r.price}円×${r.sold}杯） − 材料代 ${yen(r.make * COST)}円（${COST}円×${r.make}杯）</p>
      <div class="q-say">${D.OK.mascot(mood, 44)}<p>${msg}</p></div>
      <button type="button" class="btn" id="spNext">${day < DAYS ? "次の日へ" : "けっかを見る"}</button></div>`;
    $("spNext").addEventListener("click", () => { if (day < DAYS) { day++; wx = pickWx(); phase = "plan"; } else phase = "end"; render(); });
  }
  start();
})();

;

/* ===== okane-news.js ===== */
// おかねの物差し：ホームの「あたらしくなったこと」。前に来たときにはなかったものに NEW をつける
(() => {
  const D = window, { $, store, esc, icon } = D.OK;
  const box = $("newsRow"); if (!box) return;
  // 新しい順。d は「YYYY-MM-DD」
  const NEWS = [
    { d: "2026-10-15", ic: "money", t: "おつりチャレンジ", p: "お札で払ったときのおつりを、硬貨をえらんで作ろう。少ない枚数で★3つ！", go: "money" },
    { d: "2026-10-14", ic: "sources", t: "数字にだまされない", p: "グラフの目もりと「平均のわな」。統計の読み方を、動かしてたしかめよう。", go: "sources" },
    { d: "2026-10-14", ic: "map", t: "2つの県をくらべっこ", p: "最低賃金・物価・おにぎりやお米の値段を、2つの県でならべてくらべよう。", go: "map" },
    { d: "2026-10-14", ic: "big", t: "国のお金メーター", p: "ページを見ているあいだに、国のお金が1秒ごとにどれだけ動くかを数えます。", go: "big" },
    { d: "2026-10-14", ic: "quiz", t: "みんなでクイズ", p: "教室の大きな画面に、1問ずつ大きく出せます。キーボードでも進められます。", go: "quiz" },
    { d: "2026-10-14", ic: "sheet", t: "ワークシートが8問に", p: "国の家計簿と、一生のお金すごろくの問題がふえました。印刷できます。", go: "sheet" },
    { d: "2026-10-14", ic: "quiz", t: "しくみクイズが20問に", p: "お金の歴史や国の予算の問題がふえました。", go: "quiz" },
    { d: "2026-10-14", ic: "big", t: "国の1年のお金を1万円に", p: "使い道と、入ってくるお金を100マスで。約4分の1は借金です。", go: "big" },
    { d: "2026-10-14", ic: "sources", t: "さがす・もくじがパワーアップ", p: "ゲームや相談室、歴史も「さがす」で見つかります。もくじに体験のタグも。", go: "toc" },
    { d: "2026-10-14", ic: "agewage", t: "一生のお金すごろく", p: "学校にかかるお金と、65歳まではたらいてもらう給料をならべよう。", go: "agewage" },
    { d: "2026-10-14", ic: "money", t: "お金の歴史", p: "貝がら・小判・お札・スマホ。お金はどう変わってきた？", go: "money" },
    { d: "2026-10-14", ic: "words", t: "よみあげボタン", p: "章のポイントや相談室の答えを、声で読み上げます。", go: "quiz" },
    { d: "2026-10-14", ic: "pay", t: "お店やさんゲーム", p: "ジュース屋さんを5日間。天気を見て、値段と作る数を決めよう。", go: "time" },
    { d: "2026-10-14", ic: "words", t: "なぜなに相談室", p: "「お金を刷ればお金持ち？」など、8つの疑問にものさしくんが答えます。", go: "words" },
    { d: "2026-10-14", ic: "mascot", t: "ものさしくん登場", p: "サイトの案内役。章のポイントやクイズで話しかけてきます。", go: "quiz" },
    { d: "2026-10-13", ic: "time", t: "値段の決まり方", p: "需要と供給のグラフを、つまみで動かしてみよう。", go: "time" },
    { d: "2026-10-12", ic: "stamps", t: "チャレンジバッジ", p: "やってみたことで、10このバッジがもらえます。", go: "stamps" },
    { d: "2026-10-12", ic: "quiz", t: "しくみクイズ", p: "税金・円安・給料のしくみを、5問で確かめよう。", go: "quiz" },
    { d: "2026-10-12", ic: "tax", t: "お金のめぐり図", p: "払った1,100円が、会社・国・家計をめぐる旅。", go: "tax" },
    { d: "2026-10-12", ic: "race", t: "買い物かご", p: "同じかごを買うのに、10年前と今で何分はたらく？", go: "race" },
  ];
  // 見たことのあるお知らせ（題名）を覚えておく。前の版の「最後に見た日付」も読みかえる
  const old = store.get("newsSeen", null);
  let seen = store.get("newsSeenIds", null);
  const V33 = ["おつりチャレンジ", "数字にだまされない", "2つの県をくらべっこ", "国のお金メーター", "みんなでクイズ", "ワークシートが8問に", "しくみクイズが20問に", "国の1年のお金を1万円に", "さがす・もくじがパワーアップ", "一生のお金すごろく", "お金の歴史", "よみあげボタン"]; // 日付だけで覚えていた版（v32）のあとに足したもの
  if (!seen && old) seen = NEWS.filter((n) => n.d <= old && !V33.includes(n.t)).map((n) => n.t);
  const visited = !!seen; seen = new Set(seen || []);
  const fresh = (n) => visited && !seen.has(n.t);
  const fmt = (d) => { const [, m, dd] = d.split("-").map(Number); return `${m}月${dd}日`; };
  box.innerHTML = NEWS.map((n) => { const isNew = fresh(n);
    return `<a class="nw-card${isNew ? " new" : ""}" href="#${n.go}"><span class="nw-top"><span class="nw-ic">${n.ic === "mascot" ? D.OK.mascot("smile", 30) : icon(n.ic, 20)}</span><span class="nw-d">${fmt(n.d)}</span>${isNew ? '<span class="nw-new">NEW</span>' : ""}</span>
      <b>${esc(n.t)}</b><span class="nw-p">${esc(n.p)}</span></a>`; }).join("");
  const cnt = NEWS.filter(fresh).length;
  $("newsCount").textContent = cnt ? `前に来たときから ${cnt}こ ふえました` : "";
  store.set("newsSeenIds", NEWS.map((n) => n.t));
})();

;

