/* ===== okane-life.js ===== */
// おかねの物差し：人生のお金すごろく。学校にかかるお金と、はたらいてもらう給料を、年れいの順にならべる
(() => {
  const D = window, { $, yen, store } = D.OK;
  const box = $("lifeBox"); if (!box) return;
  const S = Object.fromEntries(D.SCHOOL.map((s) => [s.id, s])), A = D.AGEWAGE;
  const ONI = D.ITEMS.find((i) => i.id === "onigiri").p25;
  // 年れいごとの毎月の給料（千円）。〜19歳は18・19歳に使う
  const bandOf = (age) => age < 20 ? 0 : Math.min(10, 1 + Math.floor((age - 20) / 5));
  const wageAt = (age) => A.all[bandOf(age)];
  const STAGES = [["kg", "幼稚園", 3, 3], ["es", "小学校", 6, 6], ["jh", "中学校", 12, 3], ["hs", "高校", 15, 3]];
  let pick = store.get("lifePick", { kg: "pub", es: "pub", jh: "pub", hs: "pub" }), start = store.get("lifeStart", 22);
  const man = (v) => v >= 1e8 ? `${(v / 1e8).toFixed(2)}億円` : `${Math.round(v / 1e4).toLocaleString()}万円`;

  box.innerHTML = `<div class="lf-ctl">
      ${STAGES.map(([k, t]) => `<div class="lf-sel"><span>${t}</span><div class="seg" data-k="${k}"><button type="button" data-v="pub">公立</button><button type="button" data-v="pri">私立</button></div></div>`).join("")}
      <div class="lf-sel"><span>はたらき始める年れい</span><div class="seg" id="lfStart"><button type="button" data-v="18">18歳</button><button type="button" data-v="22">22歳</button></div></div>
    </div>
    <ol class="lf-board" id="lfBoard"></ol>
    <div class="lf-sum" id="lfSum"></div>`;

  function render() {
    box.querySelectorAll(".seg[data-k]").forEach((g) => [...g.children].forEach((b) => b.setAttribute("aria-pressed", String(pick[g.dataset.k] === b.dataset.v))));
    [...$("lfStart").children].forEach((b) => b.setAttribute("aria-pressed", String(+b.dataset.v === start)));
    const cells = [{ age: 0, t: "生まれる", kind: "start" }];
    let school = 0;
    STAGES.forEach(([k, t, age, y]) => { const s = S[`${k}-${pick[k]}`], v = s.total * y; school += v; cells.push({ age, t: `${t}（${pick[k] === "pub" ? "公立" : "私立"}）`, kind: "cost", v, sub: `1年 ${man(s.total)} × ${y}年` }); });
    if (start === 22) cells.push({ age: 18, t: "大学・専門学校など", kind: "gap", sub: "このサイトのデータには入っていません" });
    let earn = 0; const work = [];
    const marks = [start, 30, 40, 50, 60]; marks.forEach((a, i) => {
      const to = i < marks.length - 1 ? marks[i + 1] : 65; let v = 0;
      for (let x = a; x < to; x++) v += wageAt(x) * 1000 * 12;
      earn += v; work.push({ age: a, t: `${a}〜${to - 1}歳ではたらく`, kind: "earn", v, sub: `毎月 約${Math.round(wageAt(a) * 1000 / 1e4).toLocaleString()}万円から` });
    });
    cells.push(...work, { age: 65, t: "ゴール！", kind: "goal" });
    $("lfBoard").innerHTML = cells.map((c, i) => `<li class="lf-c ${c.kind}"><span class="lf-n">${i + 1}</span><span class="lf-age">${c.age}歳</span><b>${c.t}</b>${c.v ? `<span class="lf-v">${c.kind === "cost" ? "かかる" : "もらう"} ${man(c.v)}</span>` : ""}${c.sub ? `<small>${c.sub}</small>` : ""}</li>`).join("");
    const first = wageAt(start) * 1000;
    $("lfSum").innerHTML = `<div class="lf-tot cost"><span>幼稚園から高校まで、学校にかかるお金</span><b>${man(school)}</b><small>はたらき始めたころの給料（毎月約${Math.round(first / 1e4)}万円）の、約${Math.round(school / first)}か月分</small></div>
      <div class="lf-tot earn"><span>${start}歳から64歳まで、毎月の給料を合計すると</span><b>${man(earn)}</b><small>おにぎり（${ONI}円）にすると、約${Math.round(earn / ONI / 1e4).toLocaleString()}万個</small></div>`;
  }
  box.addEventListener("click", (e) => {
    const b = e.target.closest(".seg button"); if (!b) return;
    const g = b.parentElement;
    if (g.id === "lfStart") { start = +b.dataset.v; store.set("lifeStart", start); }
    else { pick = { ...pick, [g.dataset.k]: b.dataset.v }; store.set("lifePick", pick); }
    render();
  });
  render();
})();

;

/* ===== okane-budget.js ===== */
// おかねの物差し：国の1年のお金を1万円にちぢめる（使い道と、入ってくるお金の100マス）
(() => {
  const D = window, { $, yen, esc } = D.OK;
  const box = $("budgetBox"); const B = D.BUDGET; if (!box || !B) return;
  const COL = { social: "var(--seg1)", debt: "var(--hot)", local: "var(--seg2)", defense: "var(--seg6)", works: "var(--seg4)", edu: "var(--good)", other: "var(--muted)",
    "tax-c": "var(--seg1)", "tax-i": "var(--seg2)", "tax-k": "var(--seg6)", "tax-o": "var(--seg5)", misc: "var(--muted)", bond: "var(--hot)" };
  // 1万円にしたときの金額と、100マス（1マス＝100円）。合計がぴったりになるよう、端数の大きい順に1マスずつ足す
  const shrink = (list) => {
    const yenOf = list.map((x) => ({ ...x, y: Math.round((x.v / B.total) * 10000) }));
    const raw = list.map((x) => (x.v / B.total) * 100), cells = raw.map(Math.floor);
    let rest = 100 - cells.reduce((a, b) => a + b, 0);
    raw.map((r, i) => [r - Math.floor(r), i]).sort((a, b) => b[0] - a[0]).forEach(([, i]) => { if (rest > 0) { cells[i]++; rest--; } });
    return yenOf.map((x, i) => ({ ...x, n: cells[i] }));
  };
  const OUT = shrink(B.out), IN = shrink(B.in);
  const cho = (v) => (v / 10000).toFixed(1) + "兆円";
  let sel = { out: "social", in: "bond" };

  const panel = (key, title, list) => `<div class="bu-p" data-key="${key}">
      <h4>${title}</h4>
      <div class="bu-waffle" role="img" aria-label="${title}の100マス">${list.map((x) => `<i data-id="${x.id}" style="--c:${COL[x.id]}"></i>`.repeat(x.n)).join("")}</div>
      <ul class="bu-leg">${list.map((x) => `<li><button type="button" data-id="${x.id}" style="--c:${COL[x.id]}"><span class="sw"></span><span class="nm">${esc(x.t)}</span><b>${yen(x.y)}円</b></button></li>`).join("")}</ul>
      <div class="bu-d" aria-live="polite"></div></div>`;
  box.innerHTML = `<div class="bu-grid">${panel("out", "使い道（歳出）", OUT)}${panel("in", "入ってくるお金（歳入）", IN)}</div>`;

  function render() {
    [["out", OUT], ["in", IN]].forEach(([k, list]) => {
      const p = box.querySelector(`.bu-p[data-key="${k}"]`), x = list.find((z) => z.id === sel[k]);
      p.querySelectorAll(".bu-waffle i").forEach((c) => c.classList.toggle("on", c.dataset.id === sel[k]));
      p.querySelectorAll(".bu-leg button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.id === sel[k])));
      p.querySelector(".bu-d").innerHTML = `<b style="color:${COL[x.id]}">${esc(x.t)}</b>　1万円のうち <b>${yen(x.y)}円</b>（本当は${cho(x.v)}）<p>${esc(x.d)}</p>`;
    });
  }
  box.addEventListener("click", (e) => {
    const t = e.target.closest("[data-id]"); if (!t) return;
    const k = t.closest(".bu-p").dataset.key; sel = { ...sel, [k]: t.dataset.id }; render();
  });
  render();
})();

;

/* ===== okane-meter.js ===== */
// おかねの物差し：国のお金メーター。ページを開いてからの時間で、国のお金がどれだけ動いたかを数える
(() => {
  const D = window, { $, yen } = D.OK;
  const box = $("meterBox"); const B = D.BUDGET; if (!box || !B) return;
  const YEAR = 365 * 86400, oku = 1e8;
  const get = (list, id) => list.find((x) => x.id === id).v * oku;
  const M = [
    { t: "国が使ったお金", s: "予算ぜんぶ", v: B.total * oku, c: "var(--seg1)" },
    { t: "社会保障に", s: "年金・医療・介護・子育て", v: get(B.out, "social"), c: "var(--seg2)" },
    { t: "借金の利息に", s: "国債の利払費など", v: 130672 * oku, c: "var(--hot)" },
    { t: "新しい借金", s: "公債金", v: get(B.in, "bond"), c: "var(--seg5)" },
  ].map((m) => ({ ...m, ps: m.v / YEAR }));
  const t0 = performance.now(); let lastSec = -1;
  box.innerHTML = `<div class="mt-time"><span>このページを開いてから</span><b id="mtSec">0</b><span>秒</span></div>
    <div class="mt-grid">${M.map((m, i) => `<div class="mt-c" style="--c:${m.c}"><span class="mt-t">${m.t}</span><b class="mt-v" id="mtV${i}">0円</b><span class="mt-s">${m.s}・1秒に約${yen(m.ps / 1e4)}万円</span></div>`).join("")}</div>`;
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  // 画面に見えているあいだだけ、数字を動かす（時間はずっと数えている）
  let on = false, raf = 0;
  function tick() {
    raf = 0; if (!on) return;
    const sec = (performance.now() - t0) / 1000;
    if (!reduce || Math.floor(sec) !== lastSec) {
      lastSec = Math.floor(sec);
      $("mtSec").textContent = lastSec.toLocaleString();
      M.forEach((m, i) => { $(`mtV${i}`).textContent = `${yen(m.ps * (reduce ? lastSec : sec))}円`; });
    }
    raf = requestAnimationFrame(tick);
  }
  const run = (v) => { on = v; if (on && !raf) raf = requestAnimationFrame(tick); };
  if ("IntersectionObserver" in D) new IntersectionObserver((es) => run(es[0].isIntersecting)).observe(box); else run(true);
})();

;

/* ===== okane-vs.js ===== */
// おかねの物差し：2つの県をくらべっこ（最低賃金・物価・おにぎり・お米を、ならべてくらべる）
(() => {
  const D = window, { $, yen, esc, store } = D.OK;
  const box = $("vsBox"); if (!box) return;
  const N = (i) => D.OK.prefName(i);
  const mine = D.OK.pref ? D.OK.pref() : -1;
  let a = store.get("vsA", mine >= 0 ? mine : 12), b = store.get("vsB", mine === 46 ? 12 : 46);
  const opt = (sel) => D.PREFS.map((p, i) => `<option value="${i}"${i === sel ? " selected" : ""}>${N(i)}</option>`).join("");
  // くらべる項目。hi：大きいほうが「うれしい」なら1、小さいほうがうれしいなら-1、どちらでもないなら0
  const ROWS = [
    { t: "最低賃金（2026年度）", f: (i) => D.PREF_WAGE[i], u: "円", hi: 1, fmt: (v) => yen(v) },
    { t: "くらし全体の物価", f: (i) => D.RPI_TOTAL[i], u: "", hi: -1, fmt: (v) => v.toFixed(1), note: "全国平均＝100" },
    { t: "食べ物の物価", f: (i) => D.RPI_FOOD[i], u: "", hi: -1, fmt: (v) => v.toFixed(1) },
    { t: "家賃など住まいの物価", f: (i) => D.RPI_HOUSING[i], u: "", hi: -1, fmt: (v) => v.toFixed(1) },
    { t: "電気・ガス・水道の物価", f: (i) => D.RPI_ENERGY[i], u: "", hi: -1, fmt: (v) => v.toFixed(1) },
    { t: "物価を考えた最低賃金", f: (i) => D.PREF_WAGE[i] / D.RPI_TOTAL[i] * 100, u: "円", hi: 1, fmt: (v) => yen(v), note: "全国と同じ物価だったら、いくら分か" },
    { t: "おにぎり1個（県庁のある市）", f: (i) => D.CITY.onigiri[i], u: "円", hi: -1, fmt: (v) => yen(v) },
    { t: "おにぎりを買うのにはたらく時間", f: (i) => D.CITY.onigiri[i] / D.PREF_WAGE[i] * 60, u: "分", hi: -1, fmt: (v) => v.toFixed(1) },
    { t: "お米5kg（県庁のある市）", f: (i) => D.CITY.rice[i], u: "円", hi: -1, fmt: (v) => yen(v) },
    { t: "お米5kgを買うのにはたらく時間", f: (i) => D.CITY.rice[i] / D.PREF_WAGE[i] * 60, u: "分", hi: -1, fmt: (v) => Math.round(v) },
  ];
  box.innerHTML = `<div class="vs-pick"><label class="vs-a"><span>くらべる県 A</span><select id="vsA">${opt(a)}</select></label>
      <button type="button" class="vs-swap" id="vsSwap" aria-label="AとBを入れかえる">⇄</button>
      <label class="vs-b"><span>くらべる県 B</span><select id="vsB">${opt(b)}</select></label></div>
    <div class="vs-head"><b class="vs-na" id="vsNa"></b><span>VS</span><b class="vs-nb" id="vsNb"></b></div>
    <div class="vs-rows" id="vsRows"></div><p class="vs-sum" id="vsSum"></p>`;

  function render() {
    $("vsNa").textContent = N(a); $("vsNb").textContent = N(b);
    let wa = 0, wb = 0;
    $("vsRows").innerHTML = ROWS.map((r) => {
      const va = r.f(a), vb = r.f(b);
      if (va == null || vb == null || isNaN(va) || isNaN(vb)) return "";
      const mx = Math.max(va, vb), d = va - vb, same = Math.abs(d) / mx < 0.002;
      const good = same || !r.hi ? 0 : (d > 0) === (r.hi > 0) ? 1 : -1; // 1ならAのほうがうれしい
      if (good > 0) wa++; else if (good < 0) wb++;
      const bar = (v, side, win) => `<span class="vs-bar ${side}${win ? " win" : ""}"><i style="width:${(v / mx) * 100}%"></i><em>${win ? "★ " : ""}${r.fmt(v)}${r.u}</em></span>`;
      return `<div class="vs-row"><span class="vs-t">${esc(r.t)}${r.note ? `<small>${esc(r.note)}</small>` : ""}</span>${bar(va, "a", good > 0)}${bar(vb, "b", good < 0)}</div>`;
    }).join("");
    const rw = (i) => D.PREF_WAGE[i] / D.RPI_TOTAL[i] * 100, diff = rw(a) - rw(b);
    $("vsSum").innerHTML = a === b ? "同じ県どうしです。ちがう県をえらんでみよう。"
      : `<b>${N(a)}</b>は${wa}項目、<b>${N(b)}</b>は${wb}項目で、くらす人にとって「うれしいほう」（給料が高い・物価が安い）でした。` +
        `最低賃金の差は${yen(Math.abs(D.PREF_WAGE[a] - D.PREF_WAGE[b]))}円ですが、物価を考えると差は${yen(Math.abs(diff))}円${Math.abs(diff) < Math.abs(D.PREF_WAGE[a] - D.PREF_WAGE[b]) ? "に縮まります" : "になります"}。`;
  }
  const set = () => { a = +$("vsA").value; b = +$("vsB").value; store.set("vsA", a); store.set("vsB", b); render(); };
  $("vsA").addEventListener("change", set); $("vsB").addEventListener("change", set);
  $("vsSwap").addEventListener("click", () => { [a, b] = [b, a]; $("vsA").value = a; $("vsB").value = b; store.set("vsA", a); store.set("vsB", b); render(); });
  render();
})();

;

/* ===== okane-lit.js ===== */
// おかねの物差し：数字にだまされない！統計の読み方（グラフの目もり・平均のわな）
(() => {
  const D = window, { $, yen, cpiAt } = D.OK;
  const box = $("litBox"); if (!box) return;

  // ===== 1. グラフの目もりのひみつ =====
  const YS = []; for (let y = 2016; y <= 2025; y++) YS.push(y);
  const V = YS.map((y) => cpiAt("総合", y));
  let zoom = true;
  const W = 520, H = 240, L = 44, R = 10, T = 14, Bm = 30;
  function chart() {
    const lo = zoom ? Math.floor(Math.min(...V) - 1) : 0, hi = zoom ? Math.ceil(Math.max(...V) + 0.5) : 110;
    const y = (v) => T + (1 - (v - lo) / (hi - lo)) * (H - T - Bm), bw = (W - L - R) / V.length;
    const ticks = zoom ? [lo, Math.round((lo + hi) / 2), hi] : [0, 50, 100];
    let s = ticks.map((t) => `<line x1="${L}" x2="${W - R}" y1="${y(t)}" y2="${y(t)}" class="lt-grid"/><text x="${L - 6}" y="${y(t) + 4}" text-anchor="end" class="lt-ax">${t}</text>`).join("");
    s += V.map((v, i) => `<rect x="${L + i * bw + 3}" y="${y(v)}" width="${bw - 6}" height="${y(lo) - y(v)}" rx="3" class="lt-bar${i === V.length - 1 ? " last" : ""}"/>` + (i % 3 === 0 || i === V.length - 1 ? `<text x="${L + i * bw + bw / 2}" y="${H - 10}" text-anchor="middle" class="lt-ax">${YS[i]}</text>` : "")).join("");
    if (zoom) s += `<path d="M${L - 14} ${H - Bm - 8}l8 -5l-8 -5l8 -5" class="lt-cut"/>`;
    $("ltSvg").innerHTML = s;
    const up = ((V[V.length - 1] / V[0] - 1) * 100).toFixed(1), look = (y(lo) - y(V[V.length - 1])) / (y(lo) - y(V[0]));
    $("ltMsg").innerHTML = zoom
      ? `目もりが<b>${lo}から</b>始まっています。最後の棒は最初の棒の<b>約${look.toFixed(1)}倍</b>の高さに見えますが、本当は<b>${up}%</b>しか上がっていません。`
      : `目もりを<b>0から</b>にすると、10年間の上がり方（<b>${up}%</b>）が、そのままの大きさで見えます。`;
    [...$("ltSeg").children].forEach((b) => b.setAttribute("aria-pressed", String((b.dataset.z === "1") === zoom)));
  }

  // ===== 2. 平均のわな =====
  const BASE = [600, 800, 1000, 1200];
  let x = 1500;
  function avg() {
    const all = [...BASE, x].sort((a, b) => a - b), mean = all.reduce((a, b) => a + b, 0) / all.length, med = all[2];
    const mx = Math.max(12000, x * 1.05), px = (v) => 4 + (v / mx) * 92;
    $("avLine").innerHTML = `<div class="av-axis"></div>` + [...BASE.map((v) => [v, ""]), [x, "e"]].map(([v, c]) => `<span class="av-kid ${c}" style="left:${px(v)}%">${D.OK.mascot ? D.OK.mascot(c ? "wow" : "smile", 26) : "●"}</span>`).join("") +
      `<span class="av-mk mean" style="left:${px(mean)}%"><b>平均</b>${yen(mean)}円</span><span class="av-mk med" style="left:${px(med)}%"><b>真ん中</b>${yen(med)}円</span>`;
    $("avX").textContent = yen(x) + "円";
    const gap = mean - med;
    $("avMsg").innerHTML = gap < 150
      ? `平均（${yen(mean)}円）と真ん中の人（${yen(med)}円）は、ほとんど同じです。`
      : `1人だけがたくさんもらうと、<b>平均は${yen(mean)}円</b>まで上がります。でも5人のうち4人は${yen(Math.max(...BASE))}円以下で、<b>真ん中の人は${yen(med)}円</b>のまま。「平均」は、ふつうの人の金額とはかぎりません。`;
  }

  box.innerHTML = `<div class="lt-grid2">
    <div class="lt-card"><h4>1. グラフの目もりのひみつ</h4><p class="lt-lead">同じ物価のグラフ（全国・総合、2025年＝100）です。目もりの始まりを変えてみよう。</p>
      <div class="seg" id="ltSeg"><button type="button" data-z="1">とちゅうから</button><button type="button" data-z="0">0から</button></div>
      <svg viewBox="0 0 ${W} ${H}" id="ltSvg" role="img" aria-label="2016年から2025年の物価の棒グラフ"></svg><p class="lt-msg" id="ltMsg"></p>
      <p class="lt-tip">ニュースやチラシのグラフを見たら、まず<b>目もりがいくつから始まっているか</b>をたしかめよう。</p></div>
    <div class="lt-card"><h4>2. 平均のわな</h4><p class="lt-lead">5人の1か月のおこづかい。1人だけの金額を変えると、平均と「真ん中の人」はどうなる？</p>
      <label class="lt-sl"><span>5人目のおこづかい <b id="avX"></b></span><input type="range" id="avIn" min="500" max="50000" step="500" value="${x}"></label>
      <div class="av-line" id="avLine"></div><p class="lt-msg" id="avMsg"></p>
      <p class="lt-tip">給料の「平均」も、たくさんもらう人に引っぱられて高めに出ます。だから国の統計では、真ん中の人の金額（<b>中央値</b>）もよく使われます。</p></div>
  </div>`;
  $("ltSeg").addEventListener("click", (e) => { const b = e.target.closest("button"); if (!b) return; zoom = b.dataset.z === "1"; chart(); });
  $("avIn").addEventListener("input", (e) => { x = +e.target.value; avg(); });
  chart(); avg();
})();

;

/* ===== okane-change.js ===== */
// おかねの物差し：おつりチャレンジ。お札で払ったときのおつりを、硬貨とお札をえらんで作る（5回）
(() => {
  const D = window, { $, yen, esc, store } = D.OK;
  const box = $("chgBox"); if (!box) return;
  const MONEY = [5000, 1000, 500, 100, 50, 10, 5, 1];
  const ROUNDS = 5;
  const pool = D.ITEMS.filter((i) => i.p25 <= 9000);
  // 硬貨とお札の絵
  const coin = (v, size = 46) => {
    if (v >= 1000) return `<svg class="cg-bill" viewBox="0 0 76 40" width="${size * 1.6}" height="${size * 0.85}" aria-hidden="true"><rect x="1" y="1" width="74" height="38" rx="4" fill="${v === 5000 ? "color-mix(in srgb, var(--seg5) 35%, var(--card))" : "color-mix(in srgb, var(--cool) 30%, var(--card))"}" stroke="var(--ink)" stroke-width="1.6"/><circle cx="56" cy="20" r="10" fill="none" stroke="var(--ink)" stroke-width="1.2" opacity=".6"/><text x="22" y="25" text-anchor="middle" font-size="14" font-weight="900" fill="var(--ink)">${v.toLocaleString()}</text></svg>`;
    const C = { 500: ["#d9b44a", "#a8862c"], 100: ["#d6d8de", "#9aa0ad"], 50: ["#dfe1e6", "#9aa0ad"], 10: ["#c98652", "#94592e"], 5: ["#d9b44a", "#a8862c"], 1: ["#eef0f4", "#b4b8c2"] }[v];
    const hole = v === 50 || v === 5 ? `<circle cx="20" cy="20" r="4.2" fill="var(--card)" stroke="${C[1]}" stroke-width="1.2"/>` : "";
    return `<svg class="cg-coin" viewBox="0 0 40 40" width="${size}" height="${size}" aria-hidden="true"><circle cx="20" cy="20" r="18.5" fill="${C[0]}" stroke="${C[1]}" stroke-width="2"/><circle cx="20" cy="20" r="14.5" fill="none" stroke="${C[1]}" stroke-width="1" opacity=".6"/>${hole}<text x="20" y="${hole ? 33 : 24.5}" text-anchor="middle" font-size="${hole ? 8 : v >= 100 ? 11 : 12}" font-weight="900" fill="#2b2b2b">${v}</text></svg>`;
  };
  const minCount = (n) => MONEY.reduce((a, v) => { a.c += Math.floor(a.r / v); a.r %= v; return a; }, { c: 0, r: n }).c;
  let round, stars, cur, tray, done;

  function newRound() {
    const it = pool[Math.floor(Math.random() * pool.length)];
    const pay = [1000, 5000, 10000].find((b) => b > it.p25);
    cur = { it, pay, change: pay - it.p25 }; tray = []; done = null; render();
  }
  function start() { round = 1; stars = 0; newRound(); }

  function render() {
    const sum = tray.reduce((a, b) => a + b, 0), c = cur;
    const best = store.get("chgBest", null);
    if (round > ROUNDS) {
      const rec = best == null || stars > best; if (rec) store.set("chgBest", stars);
      box.innerHTML = `<div class="cg-end">${D.OK.mascot ? D.OK.mascot(stars >= 12 ? "wow" : "smile", 64) : ""}<div><p class="cg-big">5回で <b>★${stars}</b> / ${ROUNDS * 3}${rec ? '<span class="newrec">新記録！</span>' : ""}</p>
        <p>${stars >= 13 ? "おつり名人！ 少ない枚数で、ぴったり作れました。" : "大きいお金から順に考えると、少ない枚数で作れるよ。"}</p>
        <button type="button" class="btn" id="cgAgain">もう一回</button></div></div>`;
      $("cgAgain").addEventListener("click", start); return;
    }
    box.innerHTML = `<div class="cg-top"><span class="cg-r">${round}回目 / ${ROUNDS}</span><span class="cg-s">★${stars}</span></div>
      <div class="cg-q"><div class="cg-item"><span class="cg-k">買うもの</span><b>${esc(c.it.name)}</b><span class="cg-u">${esc(c.it.unit)}</span><span class="cg-p">${yen(c.it.p25)}円</span></div>
        <div class="cg-pay"><span class="cg-k">はらったお金</span>${coin(c.pay, 40)}<span class="cg-p">${yen(c.pay)}円</span></div>
        <div class="cg-ask"><span class="cg-k">おつりは？</span><b>${done ? yen(c.change) + "円" : "？円"}</b></div></div>
      <div class="cg-tray" aria-label="おつりのトレイ">${tray.length ? tray.map((v, i) => `<button type="button" class="cg-t" data-i="${i}" aria-label="${v}円をもどす"${done ? " disabled" : ""}>${coin(v, 38)}</button>`).join("") : `<span class="cg-empty">下のお金を押して、おつりを作ろう</span>`}</div>
      <div class="cg-sum">トレイの合計：<b>${yen(sum)}円</b>　<small>${tray.length}枚</small></div>
      ${done ? `<div class="q-say">${D.OK.mascot ? D.OK.mascot(done.ok ? "wow" : "think", 44) : ""}<p>${done.msg}</p></div><button type="button" class="btn" id="cgNext">${round < ROUNDS ? "次の買い物へ" : "けっかを見る"}</button>`
        : `<div class="cg-bank">${MONEY.filter((v) => v < c.pay).map((v) => `<button type="button" class="cg-m" data-v="${v}" aria-label="${v}円を入れる">${coin(v)}</button>`).join("")}</div>
        <div class="cg-btns"><button type="button" class="btn ghost" id="cgClear">やりなおす</button><button type="button" class="btn" id="cgOk">これでOK</button></div>`}`;
    if (done) { $("cgNext").addEventListener("click", () => { round++; if (round > ROUNDS) render(); else newRound(); }); return; }
    $("cgClear").addEventListener("click", () => { tray = []; render(); });
    $("cgOk").addEventListener("click", check);
  }
  function check() {
    const sum = tray.reduce((a, b) => a + b, 0), c = cur, mn = minCount(c.change);
    if (sum !== c.change) { done = null; box.querySelector(".cg-sum").classList.add("ng"); box.querySelector(".cg-sum small").textContent = sum < c.change ? `あと${yen(c.change - sum)}円たりないよ` : `${yen(sum - c.change)}円多いよ`; return; }
    const got = tray.length === mn ? 3 : tray.length <= mn + 2 ? 2 : 1; stars += got;
    done = { ok: true, msg: `ぴったり！ ${yen(c.pay)}円 − ${yen(c.it.p25)}円 ＝ ${yen(c.change)}円。${got === 3 ? `いちばん少ない${mn}枚で作れたね。★3つ！` : `いちばん少ないのは${mn}枚。★${got}つ！`}` };
    render();
  }
  box.addEventListener("click", (e) => {
    const m = e.target.closest(".cg-m"); if (m && !done) { if (tray.length < 30) tray.push(+m.dataset.v); render(); return; }
    const t = e.target.closest(".cg-t"); if (t && !done) { tray.splice(+t.dataset.i, 1); render(); }
  });
  start();
})();

;

/* ===== okane-speak.js ===== */
// おかねの物差し：読み上げ。「この章のポイント」と「なぜなに相談室」の答えを、声で読む
(() => {
  const D = window;
  if (!("speechSynthesis" in D) || !("SpeechSynthesisUtterance" in D)) return;
  const syn = D.speechSynthesis;
  const ICON = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9z"/><path d="M16.5 8.5a5 5 0 0 1 0 7M19 6a8.5 8.5 0 0 1 0 12"/></svg>`;
  let voice = null;
  const pickVoice = () => { const v = syn.getVoices().filter((x) => /^ja/i.test(x.lang)); voice = v.find((x) => /Kyoko|Nanami|Haruka|Google/i.test(x.name)) || v[0] || null; };
  pickVoice(); if ("onvoiceschanged" in syn) syn.addEventListener("voiceschanged", pickVoice);

  // ふりがな（rt）とリンクは読まない
  const plain = (el) => { const c = el.cloneNode(true); c.querySelectorAll("rt, .say-btn, a, svg").forEach((x) => x.remove()); return c.textContent.replace(/\s+/g, " ").trim(); };
  let cur = null;
  const reset = () => { if (cur) { cur.setAttribute("aria-pressed", "false"); cur.querySelector("span").textContent = "よみあげ"; } cur = null; };
  function speak(btn, el) {
    const same = cur === btn; syn.cancel(); reset(); if (same) return;
    const u = new SpeechSynthesisUtterance(plain(el)); u.lang = "ja-JP"; u.rate = 0.95; if (voice) u.voice = voice;
    u.onend = u.onerror = () => { if (cur === btn) reset(); };
    cur = btn; btn.setAttribute("aria-pressed", "true"); btn.querySelector("span").textContent = "とめる";
    syn.speak(u);
  }
  const add = (host, target) => {
    if (host.querySelector(".say-btn")) return;
    const b = document.createElement("button"); b.type = "button"; b.className = "say-btn"; b.setAttribute("aria-pressed", "false");
    b.innerHTML = `${ICON}<span>よみあげ</span>`; b.setAttribute("aria-label", "声で読み上げる");
    b.addEventListener("click", (e) => { e.preventDefault(); e.stopPropagation(); speak(b, target()); });
    host.appendChild(b);
  };
  document.querySelectorAll(".takeaway .tk-b").forEach((h) => add(h, () => h.querySelector("p")));
  document.querySelectorAll(".fq-bub").forEach((h) => add(h, () => h));
  document.querySelectorAll(".hl-card").forEach((h) => add(h, () => h));
  // ほかの画面に移ったら止める
  addEventListener("hashchange", () => { syn.cancel(); reset(); });
  addEventListener("pagehide", () => syn.cancel());
})();

;
